PC_CSS = """body{font:13px system-ui,sans-serif;margin:10px;min-width:300px}h1{font-size:15px}.box{border:1px solid #8884;border-radius:6px;padding:8px;margin:8px 0}
button{margin:4px 0;padding:5px 8px}.small{font-size:11px;opacity:.8}input{margin:2px 4px}@media(prefers-color-scheme:dark){body{background:#1e1e1e;color:#ddd}}"""


def pc_manifest() -> Dict[str, Any]:
    return {
        "manifest_version": 3, "name": "AI Web Bridge - Personal Chrome", "version": PC_VERSION,
        "description": "Lets the AI Web Bridge on this computer use tabs it opened (or tabs you allow) in your own Chrome. Loopback only.",
        "minimum_chrome_version": "116",
        "permissions": ["debugger", "tabs", "storage", "alarms"],
        "host_permissions": ["http://127.0.0.1/*"],
        "background": {"service_worker": "background.js"},
        "action": {"default_title": "AI Web Bridge", "default_popup": "popup.html"},
        "options_ui": {"page": "options.html", "open_in_tab": True},
        "content_security_policy": {"extension_pages": "script-src 'self'; object-src 'self'"},
    }


def pc_assets() -> Dict[str, str]:
    """The embedded extension, as {relative path: text}. Everything the extension needs lives here; nothing is shipped as a separate file."""
    return {"manifest.json": json.dumps(pc_manifest(), indent=2), "background.js": PC_BACKGROUND_JS, "popup.html": PC_POPUP_HTML, "popup.js": PC_POPUP_JS,
            "options.html": PC_OPTIONS_HTML, "options.js": PC_OPTIONS_JS, "ext.css": PC_CSS}


def pc_extract(root: Path) -> Dict[str, Any]:
    """Write the embedded extension into <root>/extension (an application-owned folder), verify it by hash, and never touch anything else.
    Repeatable: unchanged files are left alone, changed ones are replaced, and a SHA-256 manifest records what was written."""
    ext = root / "extension"
    ext.mkdir(parents=True, exist_ok=True)
    assets, hashes, changed = pc_assets(), {}, []
    for rel, text in assets.items():
        data = text.encode("utf-8")
        hashes[rel] = hashlib.sha256(data).hexdigest()
        p = ext / rel
        if not p.exists() or p.read_bytes() != data:
            tmp = p.with_suffix(p.suffix + ".tmp")
            tmp.write_bytes(data)
            os.replace(tmp, p)
            changed.append(rel)
    for rel, h in hashes.items():                                   # verify what is on disk
        if hashlib.sha256((ext / rel).read_bytes()).hexdigest() != h:
            raise BridgeError(f"extension file {rel} failed its integrity check", "browser", 500)
    (root / "extension.sha256.json").write_text(json.dumps({"version": PC_VERSION, "files": hashes}, indent=1), "utf-8")
    return {"path": str(ext), "changed": changed, "files": len(hashes), "hashes": hashes}

# ---- secure local channel: loopback HTTP long-poll, bearer token from one-time pairing, extension origin pinned -------------------------------------------
PC_DEFAULT_PORT = 18765
PC_MAX_BODY = 8 * 1024 * 1024
PC_CONNECT_GRACE = 45.0                       # no poll for this long = the extension is considered disconnected
# commands that can safely be delivered twice (the extension also de-duplicates by id, but its worker may restart and forget)
PC_SAFE_OPS = {"ping", "tabs.list", "tab.get", "cdp.attach", "cdp.detach", "tab.focus"}
PC_SAFE_CDP = {"Network.getResponseBody", "Network.getCookies", "Page.getFrameTree", "Network.enable", "Page.enable", "Runtime.enable", "DOM.enable", "Debugger.enable",
               "Log.enable", "Page.setLifecycleEventsEnabled", "Network.streamResourceContent", "Network.getRequestPostData", "Debugger.getScriptSource", "Page.getResourceContent", "Page.captureScreenshot"}
PC_ALLOWED_OPS = {"ping", "tabs.list", "tab.get", "tab.create", "tab.close", "tab.focus", "cdp.attach", "cdp.detach", "cdp.send"}
PC_CDP_DOMAINS = {"Page", "Runtime", "Network", "Input", "DOM", "Debugger", "Log"}
PC_CDP_BLOCKED = {"Network.getAllCookies", "Network.clearBrowserCookies", "Network.deleteCookies", "Runtime.compileScript"}


class PCError(BridgeError):
    def __init__(self, msg: str, unknown_outcome: bool = False, status: int = 503):
        super().__init__(msg, "browser", status)
        self.unknown_outcome = unknown_outcome
        self.may_have_been_accepted = unknown_outcome


def pc_mode() -> str:
    """'personal_chrome' (default) or 'playwright' (the old separate-browser path, only when the owner asks for it with BRIDGE_BROWSER=playwright)."""
    return "playwright" if os.environ.get("BRIDGE_BROWSER", "").strip().lower() == "playwright" else "personal_chrome"


def pc_validate_command(op: str, args: Dict[str, Any]) -> None:
    if op not in PC_ALLOWED_OPS:
        raise PCError(f"command not allowed: {op}", status=400)
    if not isinstance(args, dict) or len(json.dumps(args, default=str)) > PC_MAX_BODY:
        raise PCError("command arguments invalid or too large", status=400)
    if op == "cdp.send":
        m = str(args.get("method") or "")
        if m.split(".")[0] not in PC_CDP_DOMAINS or m in PC_CDP_BLOCKED:
            raise PCError(f"CDP method not permitted: {m}", status=400)
    if op in ("cdp.send", "cdp.attach", "cdp.detach", "tab.close", "tab.focus", "tab.get") and not isinstance(args.get("tab"), int):
        raise PCError("a numeric tab id is required", status=400)


class _PCCmd:
    __slots__ = ("id", "op", "args", "state", "result", "error", "ev", "safe", "t_sent", "cancelled")

    def __init__(self, op: str, args: Dict[str, Any]):
        self.id, self.op, self.args = uuid.uuid4().hex, op, args
        self.state, self.result, self.error, self.ev, self.t_sent, self.cancelled = "queued", None, None, threading.Event(), 0.0, False
        self.safe = op in PC_SAFE_OPS or (op == "cdp.send" and str(args.get("method")) in PC_SAFE_CDP)


class PCHub:
    """Bridge side of the channel. Only 127.0.0.1 is bound; every request needs the pairing token AND the pinned extension origin AND a loopback Host header;
    request bodies are bounded; commands are validated against a whitelist before they are queued; each command has an id, an acknowledgement and one result."""

    def __init__(self, root: Path, port: Optional[int] = None):
        self.root, self.port = Path(root), int(port or os.environ.get("BRIDGE_PC_PORT") or PC_DEFAULT_PORT)
        self.root.mkdir(parents=True, exist_ok=True)
        self.lock = threading.RLock()
        self.cv = threading.Condition(self.lock)
        self.cmds: Dict[str, _PCCmd] = {}
        self.queue: deque = deque()
        self.srv: Optional[ThreadingHTTPServer] = None
        self.last_poll = 0.0
        self._sid = ""                                                       # id of the extension worker that polled last (changes on every worker restart)
        self.epoch = 0
        self.grace = PC_CONNECT_GRACE
        self.listeners: List[Callable[[Dict[str, Any]], None]] = []
        self.pair_code, self.pair_until, self.pair_fails = "", 0.0, 0
        self.state = self._load()
        self.stats = {"events": 0, "commands": 0, "rejected": 0, "dupe_results": 0}

    # -- persistent pairing state (only a hash of the token is stored) -----------------------------------------------------------------------------
    def _load(self) -> Dict[str, Any]:
        try:
            return json.loads((self.root / "pairing.json").read_text("utf-8"))
        except Exception:
            return {}

    def _save(self) -> None:
        p = self.root / "pairing.json"
        tmp = p.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.state), "utf-8")
        try:
            os.chmod(tmp, 0o600)
        except Exception:
            pass
        os.replace(tmp, p)

    def new_pairing(self) -> str:
        """A one-time code, valid ten minutes. A successful pairing replaces the stored token and the pinned extension id."""
        with self.lock:
            self.pair_code = "".join(secrets.choice("ABCDEFGHJKLMNPQRSTUVWXYZ23456789") for _ in range(8))
            self.pair_until, self.pair_fails = time.time() + 600, 0
            return self.pair_code                                                    # the previous pairing stays valid until a new one succeeds

    def paired(self) -> bool:
        return bool(self.state.get("token_sha256") and self.state.get("origin"))

    def connected(self) -> bool:
        return self.paired() and (time.time() - self.last_poll) < self.grace

    def status(self) -> Dict[str, Any]:
        with self.lock:
            return {"mode": pc_mode(), "listening": self.srv is not None, "port": self.port, "paired": self.paired(), "connected": self.connected(), "epoch": self.epoch,
                    "pending_commands": len(self.queue), "last_poll_age": round(time.time() - self.last_poll, 1) if self.last_poll else None, "stats": dict(self.stats),
                    "pairing_code_active": bool(self.pair_code and time.time() < self.pair_until)}

    # -- server ------------------------------------------------------------------------------------------------------------------------------------
    def start(self) -> bool:
        if self.srv is not None:
            return True
        hub = self

        class H(BaseHTTPRequestHandler):
            protocol_version = "HTTP/1.1"
            server_version = "PCHub"

            def log_message(self, *a: Any) -> None:
                pass

            def _reply(self, code: int, obj: Dict[str, Any]) -> None:
                data = json.dumps(obj, default=str).encode("utf-8")
                self.send_response(code)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(data)))
                org = hub.state.get("origin") or self.headers.get("Origin") or ""
                if org.startswith("chrome-extension://") and org == self.headers.get("Origin"):
                    self.send_header("Access-Control-Allow-Origin", org)
                    self.send_header("Vary", "Origin")
                self.end_headers()
                self.wfile.write(data)

            def do_OPTIONS(self) -> None:                                  # CORS is NOT authentication: the preflight only answers for the pinned origin, the token is still required
                org = self.headers.get("Origin") or ""
                if org and org == hub.state.get("origin"):
                    self.send_response(204)
                    self.send_header("Access-Control-Allow-Origin", org)
                    self.send_header("Access-Control-Allow-Headers", "Content-Type, X-Bridge-PC-Token")
                    self.send_header("Access-Control-Allow-Methods", "POST")
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                else:
                    self._reply(403, {"error": "forbidden"})

            def do_GET(self) -> None:
                self._reply(405, {"error": "POST only"})

            def do_POST(self) -> None:
                try:
                    host = (self.headers.get("Host") or "").lower()
                    if host not in (f"127.0.0.1:{hub.port}", f"localhost:{hub.port}"):
                        log_every("pc:badhost", 60, f"personal chrome channel: request refused, wrong Host header '{host[:60]}'", "warn")
                        return self._reply(403, {"error": "bad host"})
                    try:
                        n = int(self.headers.get("Content-Length") or "0")
                    except ValueError:
                        n = -1
                    if n < 0 or n > PC_MAX_BODY:
                        log_every("pc:413", 60, f"personal chrome channel: request body too large ({n} bytes, limit {PC_MAX_BODY})", "warn")
                        return self._reply(413, {"error": "body too large"})
                    raw = self.rfile.read(n) if n else b""
                    try:
                        body = json.loads(raw.decode("utf-8") or "{}")
                        if not isinstance(body, dict):
                            raise ValueError
                    except Exception:
                        log_every("pc:400", 60, "personal chrome channel: request body is not valid JSON", "warn")
                        return self._reply(400, {"error": "bad json"})
                    origin = self.headers.get("Origin") or ""
                    path = self.path.split("?")[0]
                    if path == "/pc/pair":
                        code, obj = hub._pair(origin, body)
                        return self._reply(code, obj)
                    tok = self.headers.get("X-Bridge-PC-Token") or ""
                    if not hub._auth(origin, tok):
                        hub.stats["rejected"] += 1
                        why_ = hub._auth_why(origin, tok)
                        log_every("pc:auth:" + why_, 60, f"personal chrome channel: extension request rejected - {why_} (the extension must be paired again: python bridge.py --pc-pair)", "warn")
                        time.sleep(0.2)
                        return self._reply(401, {"error": "unauthorized"})
                    if path == "/pc/poll":
                        return self._reply(200, {"commands": hub._poll(min(float(body.get("wait_ms") or 20000), 25000) / 1000.0, str(body.get("sid") or "")[:64])})
                    if path == "/pc/result":
                        return self._reply(200, hub._result(body))
                    if path == "/pc/events":
                        return self._reply(200, hub._events(body))
                    return self._reply(404, {"error": "not found"})
                except (BrokenPipeError, ConnectionResetError):
                    pass
                except Exception as e:
                    log(f"personal chrome hub: {type(e).__name__}: {e}", "debug")
                    try:
                        self._reply(500, {"error": "internal"})
                    except Exception:
                        pass

        try:
            self.srv = QuietServer(("127.0.0.1", self.port), H)
        except OSError as e:
            log(f"personal chrome channel could not listen on 127.0.0.1:{self.port} ({e}); set BRIDGE_PC_PORT to another port", "warn")
            self.srv = None
            return False
        self.srv.daemon_threads = True
        threading.Thread(target=self.srv.serve_forever, daemon=True, name="pc-hub").start()
        threading.Thread(target=self._monitor, daemon=True, name="pc-monitor").start()
        log(f"personal chrome channel listening on 127.0.0.1:{self.port} (paired: {self.paired()})", "info")
        return True

    def _monitor(self) -> None:
        """Writes one line whenever the extension connects or disconnects, so a Chrome that went to sleep or a disabled extension is visible in the log."""
        was = self.connected()
        while self.srv is not None:
            time.sleep(3)
            try:
                now_ = self.connected()
                if now_ != was:
                    if now_:
                        log(f"personal chrome: extension connected (epoch {self.epoch})", "ok")
                    else:
                        log(f"personal chrome: extension DISCONNECTED - no poll for {time.time() - self.last_poll:.0f}s (Chrome closed, extension disabled or reloaded, or the computer slept)", "warn")
                    was = now_
            except Exception:
                pass

    def stop(self) -> None:
        s, self.srv = self.srv, None
        if s is not None:
            try:
                s.shutdown()
                s.server_close()
            except Exception:
                pass
        with self.cv:
            for c in self.cmds.values():
                c.error = c.error or "bridge channel stopped"
                c.ev.set()
            self.cv.notify_all()

    # -- request handlers --------------------------------------------------------------------------------------------------------------------------
    def _auth(self, origin: str, token: str) -> bool:
        st = self.state
        if not (st.get("token_sha256") and st.get("origin")) or not origin or origin != st["origin"]:
            return False
        return hmac.compare_digest(hashlib.sha256(token.encode("utf-8")).hexdigest(), st["token_sha256"])

    def _auth_why(self, origin: str, token: str) -> str:
        """The reason a request was refused, for the log (never the token itself)."""
        st = self.state
        if not (st.get("token_sha256") and st.get("origin")):
            return "not paired yet"
        if not origin:
            return "no Origin header (not sent by the extension)"
        if origin != st["origin"]:
            return "the extension id differs from the paired one (the extension was reinstalled or is another copy)"
        return "wrong or missing token"

    def _pair(self, origin: str, body: Dict[str, Any]) -> Tuple[int, Dict[str, Any]]:
        with self.lock:
            if not origin.startswith("chrome-extension://") or len(origin) > 80:
                log("personal chrome pairing refused: the request did not come from a Chrome extension", "warn")
                return 403, {"error": "pairing is only accepted from the extension"}
            if not self.pair_code or time.time() > self.pair_until or self.pair_fails >= 5:
                log("personal chrome pairing refused: no active code (expired, used, or 5 wrong tries) - run `python bridge.py --pc-pair` or press the pair button in the dashboard", "warn")
                return 403, {"error": "no active pairing code (ask the bridge for a new one)"}
            if not hmac.compare_digest(str(body.get("code") or "").strip().upper(), self.pair_code):
                self.pair_fails += 1
                log(f"personal chrome pairing refused: wrong code (try {self.pair_fails} of 5)", "warn")
                if self.pair_fails >= 5:
                    self.pair_code = ""
                time.sleep(0.3)
                return 403, {"error": "wrong code"}
            token = secrets.token_urlsafe(32)
            self.state = {"token_sha256": hashlib.sha256(token.encode("utf-8")).hexdigest(), "origin": origin, "paired_at": time.time(), "version": PC_VERSION}
            self.pair_code = ""
            self._save()
        log("personal Chrome extension paired", "ok")
        return 200, {"token": token}

    def _poll(self, wait: float, sid: str = "") -> List[Dict[str, Any]]:
        end = time.time() + wait
        with self.cv:
            new_worker = bool(sid) and bool(getattr(self, "_sid", "")) and sid != self._sid          # the worker restarted faster than the grace time: its tabs must still be re-validated
            if sid:
                self._sid = sid
            if time.time() - self.last_poll > self.grace or new_worker:
                self.epoch += 1                                              # a new connection: listeners re-validate tabs
                self._fire({"k": "reconnected", "epoch": self.epoch})
            self.last_poll = time.time()
            while True:
                out = []
                while self.queue:
                    c = self.queue.popleft()
                    if c.cancelled:
                        continue
                    c.state, c.t_sent = "sent", time.time()
                    out.append({"id": c.id, "op": c.op, "args": c.args})
                if out or time.time() >= end or self.srv is None:
                    self.last_poll = time.time()
                    return out
                self.cv.wait(timeout=min(1.0, max(0.05, end - time.time())))
                self.last_poll = time.time()

    def _result(self, body: Dict[str, Any]) -> Dict[str, Any]:
        with self.cv:
            c = self.cmds.get(str(body.get("id") or ""))
            if c is None:
                return {"ok": False}
            if body.get("ack"):
                if c.state == "sent":
                    c.state = "acked"
                return {"ok": True}
            if c.state == "done":
                self.stats["dupe_results"] += 1
                return {"ok": True, "dupe": True}
            c.state = "done"
            if body.get("ok"):
                c.result = body.get("result")
            else:
                c.error = str(body.get("error") or "command failed")
                log_every(f"pc:cmd:{c.op}:{c.error[:60]}", 20, f"personal chrome: the browser reported an error for '{c.op}' after {time.time() - c.t_sent:.1f}s: {c.error[:300]}" if getattr(c, "t_sent", 0) else
                          f"personal chrome: the browser reported an error for '{c.op}': {c.error[:300]}", "warn")
            c.ev.set()
            return {"ok": True}

    def _events(self, body: Dict[str, Any]) -> Dict[str, Any]:
        evs = body.get("events")
        if not isinstance(evs, list):
            return {"ok": False}
        for e in evs[:2000]:
            if isinstance(e, dict):
                self.stats["events"] += 1
                if e.get("k") == "detached":
                    log_every(f"pc:detached:{e.get('tab')}", 10, f"personal chrome: the debugger was detached from tab {e.get('tab')} (reason: {str(e.get('reason'))[:80]}) - "
                              "'canceled_by_user' means the yellow 'debugging this browser' bar was closed", "warn")
                self._fire(e)
        return {"ok": True}

    def _fire(self, ev: Dict[str, Any]) -> None:
        for fn in list(self.listeners):
            try:
                fn(ev)
            except Exception as e:
                log(f"personal chrome listener: {type(e).__name__}: {e}", "debug")

    def add_listener(self, fn: Callable[[Dict[str, Any]], None]) -> None:
        if fn not in self.listeners:
            self.listeners.append(fn)

    def remove_listener(self, fn: Callable[[Dict[str, Any]], None]) -> None:
        if fn in self.listeners:
            self.listeners.remove(fn)

    # -- commands (called from bridge threads) -----------------------------------------------------------------------------------------------------
    def call(self, op: str, args: Optional[Dict[str, Any]] = None, timeout: float = 30.0, cancel: Optional[threading.Event] = None, connect_wait: float = 0.0) -> Any:
        args = args or {}
        pc_validate_command(op, args)
        t_end = time.time() + connect_wait
        while not self.connected():
            if time.time() >= t_end:
                why_ = self.not_ready_reason()
                log_every("pc:notready:" + why_[:50], 30, f"personal chrome: command '{op}' could not be sent - {why_}", "warn")
                raise PCError(why_)
            time.sleep(0.25)
        c = _PCCmd(op, args)
        with self.cv:
            self.cmds[c.id] = c
            self.queue.append(c)
            self.stats["commands"] += 1
            self.cv.notify_all()
        deadline = time.time() + timeout
        t_call = time.time()
        try:
            while not c.ev.wait(0.2):
                if cancel is not None and cancel.is_set():
                    c.cancelled = True
                    raise PCError(f"{op} cancelled", unknown_outcome=c.state != "queued" and not c.safe, status=499)
                if time.time() >= deadline:
                    c.cancelled = True
                    raise PCError(f"{op} timed out after {timeout:g}s" + ("" if c.state == "queued" else "; the browser may or may not have executed it"),
                                  unknown_outcome=c.state != "queued" and not c.safe)
                if not self.connected():                                      # extension went away while the command was in flight
                    with self.cv:
                        if c.state in ("sent", "acked") and c.safe:
                            c.state = "queued"
                            self.queue.append(c)                            # safe to deliver again after the reconnection
                        elif c.state in ("sent", "acked"):
                            c.cancelled = True
                            raise PCError(f"the browser extension disconnected while {op} was running; it may have been executed, so it was NOT repeated", unknown_outcome=True)
            if c.error:
                low = c.error.lower()
                if any(s in low for s in ("no tab with given id", "no tab with id", "tab not found", "debugger is not attached", "detached while")):
                    raise PCError("Target page, context or browser has been closed (" + c.error[:120] + ")", status=410)
                raise PCError(c.error[:600], status=502)
            if time.time() - t_call > 15:
                log_every(f"pc:slow:{op}", 60, f"personal chrome: command '{op}' was slow ({time.time() - t_call:.1f}s)", "info")
            return c.result
        except PCError as e_:
            log_every(f"pc:fail:{op}:{str(e_)[:50]}", 20, f"personal chrome: command '{op}' failed after {time.time() - t_call:.1f}s (state {c.state}): {str(e_)[:300]}", "warn")
            raise
        finally:
            with self.cv:
                self.cmds.pop(c.id, None)

    def not_ready_reason(self) -> str:
        if not self.srv:
            return "the personal-Chrome channel is not listening (port busy?); set BRIDGE_PC_PORT or close the program using it"
        if not self.paired():
            return "the Chrome extension is not paired yet: " + pc_instructions(self)
        return "your Chrome is not connected to the bridge (is Chrome open with the 'AI Web Bridge - Personal Chrome' extension enabled?)"


PC_HUB: Optional[PCHub] = None
_PC_HUB_LOCK = threading.Lock()


def pc_hub(root: Optional[Path] = None, start: bool = True) -> PCHub:
    """The one hub of this process. `root` is the application's data folder; the hub keeps its files in <root>/personal_chrome."""
    global PC_HUB
    with _PC_HUB_LOCK:
        if PC_HUB is None:
            PC_HUB = PCHub(Path(root or HOME) / "personal_chrome")
            pc_extract(PC_HUB.root)
        if start:
            PC_HUB.start()
        return PC_HUB


def pc_instructions(hub: Optional[PCHub] = None) -> str:
    hub = hub or pc_hub(start=False)
    ext = hub.root / "extension"
    return ("one-time setup in YOUR Chrome (Chrome does not allow silent extension installs): 1) open chrome://extensions  2) switch on 'Developer mode'  "
            f"3) 'Load unpacked' and pick  {ext}  4) click the extension icon, enter port {hub.port} and the pairing code from `python bridge.py --pc-pair`.")

# ---- compatibility layer: the subset of the Playwright sync API this application uses, implemented on the extension channel ----------------------------------
PC_FIND_JS = r"""(args) => {
  const [spec, op, extra] = args;
  const vis = e => { const r = e.getBoundingClientRect(), cs = getComputedStyle(e); return r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.display !== 'none'; };
  const m = (s, q) => { s = String(s || ''); return q.re !== undefined ? new RegExp(q.re, q.flags || '').test(s) : s.toLowerCase().includes(String(q.s).toLowerCase()); };
  const txt = e => (e.innerText !== undefined ? e.innerText : e.textContent) || '';
  const nm = e => e.getAttribute('aria-label') || (e.getAttribute('aria-labelledby') ? e.getAttribute('aria-labelledby').split(/\s+/).map(i => { const x = document.getElementById(i); return x ? txt(x) : ''; }).join(' ') : '') || txt(e) || e.value || e.title || e.alt || e.placeholder || '';
  const ROLE = {link: 'a[href],[role=link]', button: 'button,input[type=button],input[type=submit],input[type=reset],[role=button]',
    textbox: 'input:not([type]),input[type=text],input[type=email],input[type=search],input[type=url],input[type=tel],input[type=password],textarea,[role=textbox],[contenteditable=true]',
    checkbox: 'input[type=checkbox],[role=checkbox]', radio: 'input[type=radio],[role=radio]', combobox: 'select,[role=combobox]', menuitem: '[role=menuitem]', tab: '[role=tab]',
    option: 'option,[role=option]', heading: 'h1,h2,h3,h4,h5,h6,[role=heading]', listitem: 'li,[role=listitem]', img: 'img,[role=img]', dialog: 'dialog,[role=dialog]'};
  let els = [];
  try {
    if (spec.xpath) { const it = document.evaluate(spec.xpath, document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null); for (let i = 0; i < it.snapshotLength; i++) els.push(it.snapshotItem(i)); }
    else if (spec.role) { els = [...document.querySelectorAll(ROLE[spec.role] || '[role="' + spec.role + '"]')]; if (spec.name) els = els.filter(e => m(nm(e), spec.name)); }
    else if (spec.text) { const all = [...document.querySelectorAll('body *')].filter(e => !['SCRIPT', 'STYLE', 'NOSCRIPT'].includes(e.tagName) && m(txt(e), spec.text)); els = all.filter(e => !all.some(o => o !== e && e.contains(o))); }
    else els = [...document.querySelectorAll(spec.css)];
  } catch (e) { return {error: 'bad selector: ' + String(e.message || e).slice(0, 120)}; }
  if (spec.visible) els = els.filter(vis);
  if (spec.nth !== null && spec.nth !== undefined) { const i = spec.nth < 0 ? els.length + spec.nth : spec.nth; els = els[i] ? [els[i]] : []; }
  if (op === 'count') return {found: true, v: els.length};
  if (op === 'texts') return {found: true, v: els.map(txt)};
  const el = els[0]; if (!el) return {found: false};
  switch (op) {
    case 'text': return {found: true, v: txt(el)};
    case 'textcontent': return {found: true, v: el.textContent};
    case 'html': return {found: true, v: el.outerHTML};
    case 'attr': return {found: true, v: el.getAttribute(extra)};
    case 'value': return {found: true, v: el.value !== undefined ? el.value : (el.isContentEditable ? txt(el) : null)};
    case 'visible': return {found: true, v: vis(el)};
    case 'enabled': return {found: true, v: !(el.disabled === true || el.getAttribute('aria-disabled') === 'true')};
    case 'rect': {
      el.scrollIntoView({block: 'center', inline: 'center'}); const r = el.getBoundingClientRect(), x = r.left + r.width / 2, y = r.top + r.height / 2, top = document.elementFromPoint(x, y);
      return {found: true, x, y, w: r.width, h: r.height, vis: vis(el), enabled: !(el.disabled === true || el.getAttribute('aria-disabled') === 'true'), hit: !!top && (el === top || el.contains(top) || top.contains(el))};
    }
    case 'focus': {
      el.focus(); const tag = el.tagName.toLowerCase();
      if (tag === 'input' || tag === 'textarea') { try { el.select(); } catch (e) {} return {found: true, kind: 'field', editable: !(el.readOnly || el.disabled)}; }
      if (el.isContentEditable) { const s = getSelection(), r = document.createRange(); r.selectNodeContents(el); s.removeAllRanges(); s.addRange(r); return {found: true, kind: 'editable', editable: true}; }
      return {found: true, kind: 'other', editable: false};
    }
    case 'setvalue': {
      const proto = el.tagName.toLowerCase() === 'textarea' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype, d = Object.getOwnPropertyDescriptor(proto, 'value');
      if (d && d.set) d.set.call(el, extra); else el.value = extra; el.dispatchEvent(new Event('input', {bubbles: true})); el.dispatchEvent(new Event('change', {bubbles: true})); return {found: true, v: el.value};
    }
    case 'select': { const opt = [...el.options].find(o => o.value === extra || o.label === extra || o.text === extra); if (!opt) return {found: true, v: false}; el.value = opt.value; el.dispatchEvent(new Event('input', {bubbles: true})); el.dispatchEvent(new Event('change', {bubbles: true})); return {found: true, v: true}; }
    default: return {error: 'unknown op'};
  }
}"""

_PC_FN_RE = re.compile(r"^\s*(?:async\s*)?(?:\([^=]*?\)|[A-Za-z_$][\w$]*)\s*=>|^\s*(?:async\s+)?function\b")
_PC_RTYPE = {"Document": "document", "Stylesheet": "stylesheet", "Image": "image", "Media": "media", "Font": "font", "Script": "script", "TextTrack": "texttrack", "XHR": "xhr",
             "Fetch": "fetch", "EventSource": "eventsource", "WebSocket": "websocket", "Manifest": "manifest", "Other": "other", "Ping": "ping", "CSPViolationReport": "other"}
_PC_KEYS = {"Enter": ("Enter", 13, "\r"), "Tab": ("Tab", 9, ""), "Escape": ("Escape", 27, ""), "Backspace": ("Backspace", 8, ""), "Delete": ("Delete", 46, ""), "ArrowUp": ("ArrowUp", 38, ""),
            "ArrowDown": ("ArrowDown", 40, ""), "ArrowLeft": ("ArrowLeft", 37, ""), "ArrowRight": ("ArrowRight", 39, ""), "Home": ("Home", 36, ""), "End": ("End", 35, ""),
            "PageUp": ("PageUp", 33, ""), "PageDown": ("PageDown", 34, ""), " ": ("Space", 32, " "), "Space": ("Space", 32, " ")}
_PC_MODS = {"Alt": 1, "Control": 2, "Ctrl": 2, "Meta": 4, "Command": 4, "Shift": 8}
_PC_SHARED_OFF = {"Network.disable", "Page.disable", "Runtime.disable", "DOM.disable", "Debugger.disable", "Log.disable"}      # one debugger session serves every consumer of a tab


def pc_js_matcher(x: Any) -> Dict[str, Any]:
    """A str (case-insensitive substring) or a compiled regex -> the JS-side matcher."""
    if hasattr(x, "pattern"):
        return {"re": x.pattern, "flags": "i" if x.flags & re.I else ""}
    return {"s": str(x)}


def pc_spec(sel: str) -> Dict[str, Any]:
    """Selector string -> finder spec. Supported: CSS (with Playwright's :visible), text=..., xpath=... / //... ."""
    s = (sel or "").strip()
    if s.startswith("xpath=") or s.startswith("//"):
        return {"xpath": s[6:] if s.startswith("xpath=") else s, "visible": False, "nth": None}
    if s.startswith("text="):
        return {"text": {"s": s[5:].strip("\"'")}, "visible": False, "nth": None}
    vis = ":visible" in s
    return {"css": s.replace(":visible", "") or "*", "visible": vis, "nth": None}


class PCCdpSession:
    """Stands in for Playwright's CDPSession. Several sessions can share one tab (one debugger attach serves them all)."""

    def __init__(self, page: "PCPage"):
        self.page, self.handlers = page, {}

    def send(self, method: str, params: Optional[Dict[str, Any]] = None, timeout: float = 60.0) -> Any:
        if method in _PC_SHARED_OFF:
            return {}
        return self.page._cdp(method, params or {}, timeout)

    def on(self, event: str, fn: Callable[..., Any]) -> None:
        self.handlers.setdefault(event, []).append(fn)

    def detach(self) -> None:
        if self in self.page.sessions:
            self.page.sessions.remove(self)

    def _dispatch(self, method: str, params: Dict[str, Any]) -> None:
        for fn in list(self.handlers.get(method, [])):
            try:
                fn(params)
            except Exception as e:
                log(f"cdp handler {method}: {type(e).__name__}: {e}", "debug")


class PCRequest:
    def __init__(self, page: "PCPage", rid: str, p: Dict[str, Any]):
        rq = p.get("request") or {}
        self.page, self.rid, self.url, self.method = page, rid, rq.get("url", ""), rq.get("method", "GET")
        self.resource_type = _PC_RTYPE.get(p.get("type") or "Other", "other")
        self.headers = {k.lower(): str(v) for k, v in (rq.get("headers") or {}).items()}
        self._extra: Optional[Dict[str, str]] = None
        self._post, self._has_post = rq.get("postData"), bool(rq.get("hasPostData"))
        self._resp: Optional["PCResponse"] = None
        self.failure: Optional[str] = None
        self.frame_id = p.get("frameId", "")
        self.frame = {"id": self.frame_id}                                     # page requests have a frame (the recorder tells them from service-worker requests by this)

    def all_headers(self) -> Dict[str, str]:
        return dict(self._extra if self._extra is not None else self.headers)

    @property
    def post_data(self) -> Optional[str]:
        if self._post is None and self._has_post:
            try:
                self._post = (self.page._cdp("Network.getRequestPostData", {"requestId": self.rid}, 10) or {}).get("postData")
            except Exception:
                self._post = None
        return self._post

    @property
    def post_data_buffer(self) -> Optional[bytes]:
        d = self.post_data
        return d.encode("utf-8") if isinstance(d, str) else None

    def response(self) -> Optional["PCResponse"]:
        return self._resp


class PCResponse:
    def __init__(self, req: PCRequest, p: Dict[str, Any]):
        rs = p.get("response") or {}
        self.request, self.url, self.status = req, rs.get("url", req.url), int(rs.get("status") or 0)
        self.headers = {k.lower(): str(v) for k, v in (rs.get("headers") or {}).items()}
        self._extra: Optional[Dict[str, str]] = None
        self.mime = rs.get("mimeType", "")
        req._resp = self

    def all_headers(self) -> Dict[str, str]:
        return dict(self._extra if self._extra is not None else self.headers)

    def body(self) -> bytes:
        r = self.request.page._cdp("Network.getResponseBody", {"requestId": self.request.rid}, 20) or {}
        b = r.get("body") or ""
        return base64.b64decode(b) if r.get("base64Encoded") else b.encode("utf-8")

    def text(self) -> str:
        return self.body().decode("utf-8", "replace")


class PCKeyboard:
    def __init__(self, page: "PCPage"):
        self.page = page

    def _key(self, key: str) -> Tuple[str, str, int, str]:
        if key in _PC_KEYS:
            code, vk, text = _PC_KEYS[key]
            return key if key != "Space" else " ", code, vk, text
        if len(key) == 1:
            up = key.upper()
            return key, ("Key" + up if up.isalpha() else ("Digit" + key if key.isdigit() else "")), ord(up), key
        return key, key, 0, ""

    def press(self, key: str, delay: float = 0) -> None:
        parts = key.split("+") if len(key) > 1 and "+" in key[1:] else [key]
        mods, main = 0, parts[-1]
        for mname in parts[:-1]:
            mods |= _PC_MODS.get(mname, 0)
        k, code, vk, text = self._key(main)
        if mods & 6:
            text = ""
        base = {"modifiers": mods, "key": k, "code": code, "windowsVirtualKeyCode": vk, "nativeVirtualKeyCode": vk}
        self.page._cdp("Input.dispatchKeyEvent", dict(base, type="keyDown" if not text else "keyDown", text=text) if text else dict(base, type="rawKeyDown"))
        if delay:
            time.sleep(delay / 1000.0)
        self.page._cdp("Input.dispatchKeyEvent", dict(base, type="keyUp"))

    def insert_text(self, text: str) -> None:
        self.page._cdp("Input.insertText", {"text": text})

    def type(self, text: str, delay: float = 0) -> None:
        for ch in text:
            if ch == "\n":
                self.press("Enter")
            else:
                self.page._cdp("Input.dispatchKeyEvent", {"type": "keyDown", "text": ch, "key": ch})
                self.page._cdp("Input.dispatchKeyEvent", {"type": "keyUp", "key": ch})
            if delay:
                time.sleep(delay / 1000.0)


class PCMouse:
    def __init__(self, page: "PCPage"):
        self.page = page

    def move(self, x: float, y: float) -> None:
        self.page._cdp("Input.dispatchMouseEvent", {"type": "mouseMoved", "x": x, "y": y})

    def click(self, x: float, y: float, click_count: int = 1) -> None:
        self.move(x, y)
        self.page._cdp("Input.dispatchMouseEvent", {"type": "mousePressed", "x": x, "y": y, "button": "left", "clickCount": click_count})
        self.page._cdp("Input.dispatchMouseEvent", {"type": "mouseReleased", "x": x, "y": y, "button": "left", "clickCount": click_count})

    def wheel(self, dx: float, dy: float) -> None:
        self.page._cdp("Input.dispatchMouseEvent", {"type": "mouseWheel", "x": 10, "y": 10, "deltaX": dx, "deltaY": dy})


class PCLocator:
    def __init__(self, page: "PCPage", spec: Dict[str, Any]):
        self.page, self.spec = page, spec

    def _nth(self, i: Optional[int]) -> "PCLocator":
        return PCLocator(self.page, dict(self.spec, nth=i))

    @property
    def first(self) -> "PCLocator":
        return self._nth(0)

    @property
    def last(self) -> "PCLocator":
        return self._nth(-1)

    def nth(self, i: int) -> "PCLocator":
        return self._nth(int(i))

    def locator(self, sel: str) -> "PCLocator":
        sub = pc_spec(sel)
        if "css" in self.spec and "css" in sub and self.spec.get("nth") is None:
            return PCLocator(self.page, dict(sub, css=self.spec["css"] + " " + sub["css"], visible=self.spec["visible"] or sub["visible"]))
        raise PCError("nested locators are only supported for plain CSS selectors in personal-Chrome mode", status=501)

    def _q(self, op: str, extra: Any = None) -> Dict[str, Any]:
        r = self.page.evaluate(PC_FIND_JS, [self.spec, op, extra]) or {}
        if r.get("error"):
            raise PCError(r["error"], status=400)
        return r

    def count(self) -> int:
        return int(self._q("count").get("v") or 0)

    def _wait_el(self, op: str, timeout: Optional[float], extra: Any = None) -> Dict[str, Any]:
        t = (self.page.default_timeout if timeout is None else timeout) / 1000.0
        end = time.time() + t
        while True:
            r = self._q(op, extra)
            if r.get("found"):
                return r
            if time.time() >= end:
                raise PCError(f"Timeout {int(t * 1000)}ms exceeded waiting for the element ({self.page._describe(self.spec)}).", status=408)
            self.page.wait_for_timeout(100)

    def inner_text(self, timeout: Optional[float] = None) -> str:
        return str(self._wait_el("text", timeout).get("v") or "")

    def text_content(self, timeout: Optional[float] = None) -> Optional[str]:
        return self._wait_el("textcontent", timeout).get("v")

    def inner_html(self, timeout: Optional[float] = None) -> str:
        return str(self._wait_el("html", timeout).get("v") or "")

    def all_inner_texts(self) -> List[str]:
        return list(self._q("texts").get("v") or [])

    def get_attribute(self, name: str, timeout: Optional[float] = None) -> Optional[str]:
        return self._wait_el("attr", timeout, name).get("v")

    def input_value(self, timeout: Optional[float] = None) -> str:
        return str(self._wait_el("value", timeout).get("v") or "")

    def is_visible(self, timeout: Optional[float] = None) -> bool:
        r = self._q("visible")
        return bool(r.get("found") and r.get("v"))

    def is_enabled(self, timeout: Optional[float] = None) -> bool:
        r = self._q("enabled")
        return bool(r.get("found") and r.get("v"))

    def wait_for(self, state: str = "visible", timeout: Optional[float] = None) -> None:
        end = time.time() + (self.page.default_timeout if timeout is None else timeout) / 1000.0
        while True:
            c = self.count() if state in ("attached", "detached") else (1 if self.is_visible() else 0)
            if (state in ("visible", "attached") and c) or (state in ("hidden", "detached") and not c):
                return
            if time.time() >= end:
                raise PCError(f"Timeout exceeded waiting for state '{state}'", status=408)
            self.page.wait_for_timeout(100)

    def click(self, timeout: Optional[float] = None, click_count: int = 1, **_kw: Any) -> None:
        t = (self.page.default_timeout if timeout is None else timeout) / 1000.0
        end, tries = time.time() + t, 0
        while True:
            r = self._q("rect")
            tries += 1
            if r.get("found") and r.get("vis") and r.get("enabled") and (r.get("hit") or tries > 4):
                self.page.mouse.click(float(r["x"]), float(r["y"]), click_count)
                return
            if time.time() >= end:
                why = "not found" if not r.get("found") else ("not visible" if not r.get("vis") else ("disabled" if not r.get("enabled") else "covered by another element"))
                raise PCError(f"Timeout {int(t * 1000)}ms exceeded: element {why} ({self.page._describe(self.spec)}).", status=408)
            self.page.wait_for_timeout(120)

    def dblclick(self, timeout: Optional[float] = None, **_kw: Any) -> None:
        self.click(timeout=timeout, click_count=2)

    def hover(self, timeout: Optional[float] = None, **_kw: Any) -> None:
        r = self._wait_el("rect", timeout)
        self.page.mouse.move(float(r["x"]), float(r["y"]))

    def focus(self, timeout: Optional[float] = None) -> None:
        self._wait_el("focus", timeout)

    def fill(self, text: str, timeout: Optional[float] = None, **_kw: Any) -> None:
        r = self._wait_el("focus", timeout)
        if not r.get("editable"):
            raise PCError("Element is not an <input>, <textarea> or [contenteditable] element, or it is read-only.", status=400)
        if text == "":
            self.page.keyboard.press("Backspace")
        else:
            self.page.keyboard.insert_text(text)
        if r.get("kind") == "field":                                           # a plain field is verified; frameworks that swallowed the event get the value set directly
            if self.input_value(1000) != text:
                self._q("setvalue", text)

    def clear(self, timeout: Optional[float] = None) -> None:
        self.fill("", timeout)

    def press(self, key: str, timeout: Optional[float] = None, **_kw: Any) -> None:
        self._wait_el("focus", timeout)
        self.page.keyboard.press(key)

    def type(self, text: str, delay: float = 0, timeout: Optional[float] = None) -> None:
        self._wait_el("focus", timeout)
        self.page.keyboard.type(text, delay)

    def select_option(self, value: Any, timeout: Optional[float] = None) -> List[str]:
        if not self._wait_el("select", timeout, str(value)).get("v"):
            raise PCError("no such option", status=400)
        return [str(value)]

    def scroll_into_view_if_needed(self, timeout: Optional[float] = None) -> None:
        self._wait_el("rect", timeout)

    def set_input_files(self, *_a: Any, **_k: Any) -> None:
        raise PCError("file upload through the personal Chrome is not supported by this bridge (see --pc-status for the capability table)", status=501)


class PCPage:
    def __init__(self, ctx: "PCContext", tab_id: int, url: str = "", title: str = ""):
        self.ctx, self.tab_id, self._url, self._title = ctx, tab_id, url, title
        self.sessions: List[PCCdpSession] = []
        self.keyboard, self.mouse = PCKeyboard(self), PCMouse(self)
        self.default_timeout = 30000.0
        self._closed, self._attached = False, False
        self._flags: Dict[str, float] = {}
        self._inflight: Dict[str, float] = {}
        self._handlers: Dict[str, List[Callable[..., Any]]] = {}
        self._reqs: Dict[str, PCRequest] = {}
        self._lock = threading.RLock()

    # -- plumbing --------------------------------------------------------------------------------------------------------------------------------
    def _cdp(self, method: str, params: Optional[Dict[str, Any]] = None, timeout: float = 60.0) -> Any:
        if self._closed:
            raise PCError("Target page, context or browser has been closed", status=410)
        if not self._attached and method not in ("cdp.attach",):
            self._attach()
        try:
            return self.ctx.hub.call("cdp.send", {"tab": self.tab_id, "method": method, "params": params or {}}, timeout=timeout, cancel=self.ctx.cancel)
        except PCError as e:
            if "has been closed" in str(e):
                self._closed = True
            raise

    def _attach(self) -> None:
        with self._lock:
            if self._attached:
                return
            self.ctx.hub.call("cdp.attach", {"tab": self.tab_id}, timeout=20, cancel=self.ctx.cancel)
            self._attached = True
        for m, p in (("Page.enable", {}), ("Runtime.enable", {}), ("Page.setLifecycleEventsEnabled", {"enabled": True}),
                     ("Network.enable", {"maxPostDataSize": 1 << 20, "maxTotalBufferSize": 1 << 26, "maxResourceBufferSize": 1 << 25})):
            try:
                self.ctx.hub.call("cdp.send", {"tab": self.tab_id, "method": m, "params": p}, timeout=20, cancel=self.ctx.cancel)
            except PCError as e:
                log(f"personal chrome: {m} failed on tab {self.tab_id}: {e}", "debug")
        for name in list(self.ctx._bindings):
            self._cdp("Runtime.addBinding", {"name": name})
        for src in list(self.ctx._init_scripts):
            self._cdp("Page.addScriptToEvaluateOnNewDocument", {"source": src})

    def _describe(self, spec: Dict[str, Any]) -> str:
        return json.dumps({k: v for k, v in spec.items() if v not in (None, False)}, default=str)[:160]

    # -- events ----------------------------------------------------------------------------------------------------------------------------------
    def on(self, event: str, fn: Callable[..., Any]) -> None:
        self._handlers.setdefault(event, []).append(fn)

    def _emit(self, event: str, *a: Any) -> None:
        for fn in list(self._handlers.get(event, [])) + (list(self.ctx._handlers.get(event, [])) if event in ("request", "response", "requestfinished", "requestfailed") else []):
            try:
                fn(*a)
            except Exception as e:
                log(f"page handler {event}: {type(e).__name__}: {e}", "debug")

    def _on_cdp(self, method: str, p: Dict[str, Any]) -> None:
        if method == "Page.frameNavigated" and not (p.get("frame") or {}).get("parentId"):
            self._url = p["frame"].get("url", self._url)
        elif method == "Page.navigatedWithinDocument":
            self._url = p.get("url", self._url)
        elif method == "Page.domContentEventFired":
            self._flags["domcontentloaded"] = time.time()
        elif method == "Page.loadEventFired":
            self._flags["load"] = time.time()
        elif method == "Runtime.bindingCalled":
            fn = self.ctx._bindings.get(p.get("name", ""))
            if fn:
                try:
                    fn({"page": self}, p.get("payload", ""))
                except Exception as e:
                    log(f"binding {p.get('name')}: {type(e).__name__}: {e}", "debug")
        elif method == "Runtime.consoleAPICalled":
            self._emit("console", {"type": p.get("type"), "args": [str((a or {}).get("value", (a or {}).get("description", ""))) for a in p.get("args", [])][:8]})
        elif method == "Runtime.exceptionThrown":
            self._emit("pageerror", str(((p.get("exceptionDetails") or {}).get("exception") or {}).get("description") or (p.get("exceptionDetails") or {}).get("text", "")))
        elif method == "Page.javascriptDialogOpening":
            self._on_dialog(p)
        elif method.startswith("Network."):
            self._on_net(method, p)
        for s in list(self.sessions):
            s._dispatch(method, p)

    def _on_dialog(self, p: Dict[str, Any]) -> None:
        page = self

        class Dialog:
            type, message, default_value = p.get("type", ""), p.get("message", ""), p.get("defaultPrompt", "")

            def accept(self, prompt_text: str = "") -> None:
                page._cdp("Page.handleJavaScriptDialog", {"accept": True, "promptText": prompt_text})

            def dismiss(self) -> None:
                page._cdp("Page.handleJavaScriptDialog", {"accept": False})
        d = Dialog()
        if self._handlers.get("dialog"):
            self._emit("dialog", d)
        else:                                                                    # like Playwright: nobody listens -> the dialog is dismissed so the page never hangs
            try:
                d.accept() if p.get("type") == "beforeunload" else d.dismiss()
            except Exception:
                pass

    def _on_net(self, method: str, p: Dict[str, Any]) -> None:
        rid = p.get("requestId", "")
        if method == "Network.requestWillBeSent":
            old = self._reqs.get(rid)
            if old is not None and p.get("redirectResponse"):
                rp = {"response": p["redirectResponse"]}
                self._emit("response", PCResponse(old, rp))
                self._inflight.pop(rid, None)
                self._emit("requestfinished", old)
            if len(self._reqs) > 4000:
                self._reqs.pop(next(iter(self._reqs)), None)
            q = PCRequest(self, rid, p)
            self._reqs[rid] = q
            self._inflight[rid] = time.time()
            self._emit("request", q)
        elif method == "Network.requestWillBeSentExtraInfo":
            q = self._reqs.get(rid)
            if q is not None:
                q._extra = {k.lower(): str(v) for k, v in (p.get("headers") or {}).items() if not str(k).startswith(":")}
        elif method == "Network.responseReceived":
            q = self._reqs.get(rid)
            if q is not None:
                self._emit("response", PCResponse(q, p))
        elif method == "Network.responseReceivedExtraInfo":
            q = self._reqs.get(rid)
            if q is not None and q._resp is not None:
                q._resp._extra = {k.lower(): str(v) for k, v in (p.get("headers") or {}).items()}
        elif method == "Network.loadingFinished":
            self._inflight.pop(rid, None)
            q = self._reqs.get(rid)
            if q is not None:
                self._emit("requestfinished", q)
        elif method == "Network.loadingFailed":
            self._inflight.pop(rid, None)
            q = self._reqs.get(rid)
            if q is not None:
                q.failure = p.get("errorText", "failed")
                self._emit("requestfailed", q)

    # -- Playwright-shaped API -------------------------------------------------------------------------------------------------------------------
    @property
    def url(self) -> str:
        if not self._url and not self._closed:
            try:
                self._url = (self.ctx.hub.call("tab.get", {"tab": self.tab_id}, timeout=10, cancel=self.ctx.cancel) or {}).get("url", "")
            except PCError:
                pass
        return self._url

    def is_closed(self) -> bool:
        return self._closed

    def set_default_timeout(self, ms: float) -> None:
        self.default_timeout = float(ms)

    def create_cdp(self) -> PCCdpSession:
        s = PCCdpSession(self)
        self.sessions.append(s)
        self._attach()
        return s

    def evaluate(self, expr: str, arg: Any = None, timeout: float = 90.0) -> Any:
        code = f"({expr})({json.dumps(arg) if arg is not None else 'undefined'})" if _PC_FN_RE.match(expr or "") else expr
        r = self._cdp("Runtime.evaluate", {"expression": code, "returnByValue": True, "awaitPromise": True, "userGesture": True}, timeout) or {}
        if r.get("exceptionDetails"):
            ed = r["exceptionDetails"]
            raise PCError("page.evaluate: " + str(((ed.get("exception") or {}).get("description")) or ed.get("text") or "script error")[:400], status=500)
        return (r.get("result") or {}).get("value")

    def goto(self, url: str, wait_until: str = "load", timeout: float = 30000, referer: Optional[str] = None) -> None:
        if not re.match(r"^(https?:|about:blank$)", url or ""):
            raise PCError("only http(s) addresses can be opened", status=400)
        for k in ("domcontentloaded", "load"):
            self._flags.pop(k, None)
        r = self._cdp("Page.navigate", {"url": url, **({"referrer": referer} if referer else {})}, timeout / 1000.0 + 5) or {}
        if r.get("errorText"):
            raise PCError(f"page.goto: {r['errorText']} at {url}", status=502)
        self._url = url
        if "loaderId" not in r or wait_until == "commit":
            return
        self.wait_for_load_state("domcontentloaded" if wait_until == "domcontentloaded" else ("load" if wait_until == "load" else "networkidle"), timeout)

    def reload(self, wait_until: str = "load", timeout: float = 30000) -> None:
        for k in ("domcontentloaded", "load"):
            self._flags.pop(k, None)
        self._cdp("Page.reload", {})
        self.wait_for_load_state("domcontentloaded" if wait_until == "domcontentloaded" else "load", timeout)

    def wait_for_load_state(self, state: str = "load", timeout: float = 30000) -> None:
        end = time.time() + timeout / 1000.0
        key = "domcontentloaded" if state == "domcontentloaded" else "load"
        idle_since: Optional[float] = None
        while True:
            if self._closed:
                raise PCError("Target page, context or browser has been closed", status=410)
            if key in self._flags or self.evaluate("document.readyState") in (("interactive", "complete") if key == "domcontentloaded" else ("complete",)):
                if state != "networkidle":
                    return
                idle_since = idle_since or time.time()
                if self._inflight:
                    idle_since = None
                elif time.time() - idle_since >= 0.5:
                    return
            if time.time() >= end:
                raise PCError(f"Timeout {int(timeout)}ms exceeded waiting for load state '{state}'.", status=408)
            time.sleep(0.1)

    def wait_for_timeout(self, ms: float) -> None:
        end = time.time() + ms / 1000.0
        while True:
            if self._closed:
                raise PCError("Target page, context or browser has been closed", status=410)
            left = end - time.time()
            if left <= 0:
                return
            time.sleep(min(0.1, left))

    def wait_for_selector(self, selector: str, state: str = "visible", timeout: Optional[float] = None) -> PCLocator:
        loc = self.locator(selector).first
        loc.wait_for(state, timeout)
        return loc

    def wait_for_url(self, url: Any, timeout: float = 30000) -> None:
        end = time.time() + timeout / 1000.0
        while True:
            cur = self.evaluate("location.href") or ""
            if (url.search(cur) if hasattr(url, "search") else (url in cur)):
                return
            if time.time() >= end:
                raise PCError(f"Timeout {int(timeout)}ms exceeded waiting for URL", status=408)
            time.sleep(0.15)

    def wait_for_function(self, expr: str, arg: Any = None, timeout: float = 30000) -> Any:
        end = time.time() + timeout / 1000.0
        while True:
            v = self.evaluate(expr, arg)
            if v:
                return v
            if time.time() >= end:
                raise PCError(f"Timeout {int(timeout)}ms exceeded waiting for function", status=408)
            time.sleep(0.15)

    def locator(self, sel: str) -> PCLocator:
        return PCLocator(self, pc_spec(sel))

    def get_by_role(self, role: str, name: Any = None, exact: bool = False, **_kw: Any) -> PCLocator:
        return PCLocator(self, {"role": role, "name": pc_js_matcher(name) if name is not None else None, "visible": False, "nth": None})

    def get_by_text(self, text: Any, exact: bool = False) -> PCLocator:
        return PCLocator(self, {"text": pc_js_matcher(text), "visible": False, "nth": None})

    def title(self) -> str:
        return str(self.evaluate("document.title") or "")

    def content(self) -> str:
        return str(self.evaluate("document.documentElement.outerHTML") or "")

    def inner_text(self, selector: str, timeout: Optional[float] = None) -> str:
        return self.locator(selector).first.inner_text(timeout)

    def click(self, selector: str, timeout: Optional[float] = None, **kw: Any) -> None:
        self.locator(selector).first.click(timeout=timeout, **kw)

    def fill(self, selector: str, text: str, timeout: Optional[float] = None) -> None:
        self.locator(selector).first.fill(text, timeout=timeout)

    def screenshot(self, path: Optional[str] = None, full_page: bool = False, **_kw: Any) -> bytes:
        r = self._cdp("Page.captureScreenshot", {"format": "png", "captureBeyondViewport": bool(full_page)}, 30) or {}
        data = base64.b64decode(r.get("data") or "")
        if path:
            Path(path).write_bytes(data)
        return data

    @property
    def frames(self) -> List[Dict[str, str]]:
        def walk(n: Dict[str, Any], out: List[Dict[str, str]]) -> None:
            out.append({"id": (n.get("frame") or {}).get("id", ""), "url": (n.get("frame") or {}).get("url", ""), "name": (n.get("frame") or {}).get("name", "")})
            for c in n.get("childFrames") or []:
                walk(c, out)
        out: List[Dict[str, str]] = []
        walk((self._cdp("Page.getFrameTree", {}) or {}).get("frameTree") or {}, out)
        return out

    def bring_to_front(self) -> None:
        self.ctx.hub.call("tab.focus", {"tab": self.tab_id}, timeout=10, cancel=self.ctx.cancel)

    def close(self) -> None:
        if self._closed:
            return
        self.ctx._close_tab(self)

    def _mark_closed(self) -> None:
        self._closed = True
        self._emit("close", self)


class PCContext:
    """Plays the role of the Playwright BrowserContext for one account: the tabs it opens in the user's own Chrome (never other tabs), cookie access for the
    site, init scripts, bindings, CDP sessions. Closing it closes only the tabs it opened."""

    def __init__(self, hub: PCHub, acct_id: str = "", background: bool = True):
        self.hub, self.acct_id, self.background = hub, acct_id, background
        self.cancel = threading.Event()
        self._pages: Dict[int, PCPage] = {}
        self._handlers: Dict[str, List[Callable[..., Any]]] = {}
        self._bindings: Dict[str, Callable[..., Any]] = {}
        self._init_scripts: List[str] = []
        self._closed = False
        self._lock = threading.RLock()
        self._evq: "queue.Queue" = queue.Queue()
        threading.Thread(target=self._pump, daemon=True, name="pc-events").start()
        hub.add_listener(self._enqueue)
        self._adopt()

    def _enqueue(self, ev: Dict[str, Any]) -> None:
        if not self._closed:
            self._evq.put(ev)

    def _pump(self) -> None:
        while not self._closed:
            try:
                ev = self._evq.get(timeout=0.5)
            except queue.Empty:
                continue
            try:
                self._on_hub(ev)
            except Exception as e:
                log(f"personal chrome event: {type(e).__name__}: {e}", "debug")
            finally:
                self._evq.task_done()

    def drain(self, timeout: float = 5.0) -> bool:
        """Wait until every event received so far has been processed (used by tests and by callers that need a consistent view)."""
        end = time.time() + timeout
        while self._evq.unfinished_tasks and time.time() < end:
            time.sleep(0.02)
        return not self._evq.unfinished_tasks

    # -- tab bookkeeping (task <-> tab association is persisted without page content) --------------------------------------------------------------
    def _state_path(self) -> Path:
        return self.hub.root / "tabs.json"

    def _read_state(self) -> Dict[str, Any]:
        try:
            return json.loads(self._state_path().read_text("utf-8"))
        except Exception:
            return {}

    def _write_state(self) -> None:
        if not self.acct_id:
            return
        with self._lock:
            st = self._read_state()
            st[self.acct_id] = [{"tab": p.tab_id, "host": (urllib.parse.urlsplit(p._url).hostname or "")} for p in self._pages.values() if not p._closed]
            tmp = self._state_path().with_suffix(".tmp")
            tmp.write_text(json.dumps(st), "utf-8")
            os.replace(tmp, self._state_path())

    def _adopt(self) -> None:
        """After a bridge restart the tabs this account opened earlier are re-adopted - only if the browser still has them, they are still bridge-owned, and the site matches."""
        if not self.acct_id or not self.hub.connected():
            return
        saved = {int(x["tab"]): x.get("host", "") for x in (self._read_state().get(self.acct_id) or []) if isinstance(x, dict) and isinstance(x.get("tab"), int)}
        if not saved:
            return
        try:
            live = self.hub.call("tabs.list", {}, timeout=10) or []
        except PCError:
            return
        for t in live:
            host = (urllib.parse.urlsplit(t.get("url", "")).hostname or "")
            if t.get("owned") and t["id"] in saved and (not saved[t["id"]] or host == saved[t["id"]]):
                self._pages[t["id"]] = PCPage(self, t["id"], t.get("url", ""), t.get("title", ""))

    @property
    def pages(self) -> List[PCPage]:
        return [p for p in self._pages.values() if not p._closed]

    def new_page(self) -> PCPage:
        if self._closed:
            raise PCError("Target page, context or browser has been closed", status=410)
        active = (not self.background) or os.environ.get("BRIDGE_PC_FOREGROUND") == "1"
        t = self.hub.call("tab.create", {"url": "about:blank", "active": active}, timeout=20, cancel=self.cancel, connect_wait=5)
        pg = PCPage(self, int(t["id"]), "about:blank")
        self._pages[pg.tab_id] = pg
        pg._attach()
        self._write_state()
        self._emit("page", pg)
        return pg

    def _close_tab(self, pg: PCPage) -> None:
        try:
            self.hub.call("cdp.detach", {"tab": pg.tab_id}, timeout=10)
        except PCError:
            pass
        try:
            self.hub.call("tab.close", {"tab": pg.tab_id}, timeout=10)
        except PCError:
            pass
        pg._mark_closed()
        self._write_state()

    def _emit(self, event: str, *a: Any) -> None:
        for fn in list(self._handlers.get(event, [])):
            try:
                fn(*a)
            except Exception as e:
                log(f"context handler {event}: {type(e).__name__}: {e}", "debug")

    def on(self, event: str, fn: Callable[..., Any]) -> None:
        self._handlers.setdefault(event, []).append(fn)

    def new_cdp_session(self, page: PCPage) -> PCCdpSession:
        return page.create_cdp()

    def expose_binding(self, name: str, fn: Callable[..., Any]) -> None:
        self._bindings[name] = fn
        for p in self.pages:
            if p._attached:
                p._cdp("Runtime.addBinding", {"name": name})

    def add_init_script(self, script: str) -> None:
        self._init_scripts.append(script)
        for p in self.pages:
            if p._attached:
                p._cdp("Page.addScriptToEvaluateOnNewDocument", {"source": script})

    def _site_urls(self) -> List[str]:
        urls: List[str] = []
        for p in self.pages:
            sp = urllib.parse.urlsplit(p.url or "")
            if sp.scheme in ("http", "https") and sp.hostname:
                labels = sp.hostname.split(".")
                for h in {sp.hostname, ".".join(labels[-2:]) if len(labels) > 2 else sp.hostname, ("www." + ".".join(labels[-2:])) if len(labels) >= 2 else sp.hostname}:
                    urls.append(f"{sp.scheme}://{h}/")
        return sorted(set(urls))

    def cookies(self, urls: Optional[List[str]] = None) -> List[Dict[str, Any]]:
        """Only the cookies that apply to the sites of this account's own tabs - never the whole cookie jar of the personal profile."""
        pg = next(iter(self.pages), None)
        want = urls or self._site_urls()
        if pg is None or not want:
            return []
        r = pg._cdp("Network.getCookies", {"urls": want}) or {}
        return [{"name": c["name"], "value": c["value"], "domain": c.get("domain", ""), "path": c.get("path", "/"), "expires": c.get("expires", -1), "httpOnly": c.get("httpOnly", False),
                 "secure": c.get("secure", False), "sameSite": c.get("sameSite", "Lax")} for c in r.get("cookies", [])]

    def add_cookies(self, cookies: List[Dict[str, Any]]) -> None:
        pg = next(iter(self.pages), None) or self.new_page()
        pg._cdp("Network.setCookies", {"cookies": [{k: v for k, v in c.items() if k in ("name", "value", "url", "domain", "path", "secure", "httpOnly", "sameSite", "expires")} for c in cookies]})

    # -- hub events ------------------------------------------------------------------------------------------------------------------------------
    def _on_hub(self, ev: Dict[str, Any]) -> None:
        k, tab = ev.get("k"), ev.get("tab")
        pg = self._pages.get(tab) if isinstance(tab, int) else None
        if k == "cdp" and pg is not None:
            pg._on_cdp(str(ev.get("m") or ""), ev.get("p") or {})
        elif k == "tab_updated" and pg is not None:
            pg._url = ev.get("url") or pg._url
        elif k in ("tab_removed", "detached") and pg is not None:
            pg._attached = False
            if k == "tab_removed":
                pg._mark_closed()
                self._write_state()
        elif k == "tab_created" and isinstance(tab, int) and tab not in self._pages and ev.get("opener") in self._pages:
            np_ = PCPage(self, tab, ev.get("url", ""))                          # a popup opened by one of this account's tabs
            self._pages[tab] = np_
            threading.Thread(target=self._attach_popup, args=(tab, np_), daemon=True, name="pc-popup").start()
        elif k == "reconnected":
            threading.Thread(target=self._revalidate, daemon=True, name="pc-revalidate").start()

    def _attach_popup(self, tab: int, np_: "PCPage") -> None:
        """A popup of one of this account's tabs. Chrome refuses to attach a debugger to chrome:// / extension / devtools pages: that popup is simply not ours to drive (forgotten quietly),
        any other failure is logged once - it must never end as an unhandled exception in a thread."""
        try:
            np_._attach()
        except Exception as e:
            self._pages.pop(tab, None)
            if "chrome://" not in str(e) and "Cannot access" not in str(e):
                log(f"popup tab {tab} could not be attached: {redact_evidence(e, 160)}", "warn")
            return
        self._emit("page", np_)

    def _revalidate(self) -> None:
        """After the extension reconnects: tabs are re-checked one by one, the debugger is attached again where needed; a tab that is gone stays closed."""
        try:
            live = {t["id"]: t for t in (self.hub.call("tabs.list", {}, timeout=15) or [])}
        except PCError:
            return
        for p in list(self._pages.values()):
            if p._closed:
                continue
            if p.tab_id not in live:
                p._mark_closed()
                continue
            p._url = live[p.tab_id].get("url", p._url)
            p._attached = False
            try:
                p._attach()
            except PCError as e:
                log(f"personal chrome: re-attach of tab {p.tab_id} failed: {e}", "debug")
        self._write_state()

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        self.cancel.set()
        self.hub.remove_listener(self._enqueue)
        for p in list(self._pages.values()):
            if not p._closed:
                try:
                    self._close_tab(p)
                except Exception:
                    p._mark_closed()
        self._emit("close", self)


PC_CAPABILITIES = [
    ("tabs: list / open / focus / close (only tabs the bridge opened or you allowed)", "full", "chrome.tabs"),
    ("navigation, reload, URL, title, load-state waits", "full", "CDP Page"),
    ("DOM: CSS / text= / xpath= / get_by_role / get_by_text queries, text, attributes, values, visibility", "full", "CDP Runtime"),
    ("click, double-click, hover, fill, clear, type, key presses, select option, scroll into view", "full", "CDP Input (trusted events)"),
    ("page.evaluate with function strings and arguments (main world)", "full", "CDP Runtime"),
    ("network capture: requests, responses, headers (incl. extra info), redirects, bodies, streaming chunks, WebSocket and EventSource frames", "full for page traffic", "CDP Network"),
    ("worker / service-worker / out-of-process iframe traffic", "partial: not captured (one debugger session per tab)", "chrome.debugger"),
    ("JavaScript sources: scripts served to the page + Debugger.getScriptSource", "full for the attached tab", "CDP Network, Debugger"),
    ("console messages, page errors, dialogs (auto-dismissed unless a handler exists)", "full", "CDP Runtime / Page"),
    ("popups opened by a bridge tab", "partial: attached after they open, so their first requests can be missed", "chrome.tabs"),
    ("frames: tree inspection", "partial: listing only; locators and evaluate act on the top frame", "CDP Page"),
    ("cookies", "partial: only cookies that apply to the account's own site(s), never the whole jar", "CDP Network"),
    ("file upload / download handling", "none: not implemented (this application does not use them)", "-"),
    ("headless mode / viewport emulation / stealth", "none: your own visible Chrome is used; nothing is spoofed", "-"),
]

def pc_ensure_ready(root: Optional[Path] = None, wait: Optional[float] = None) -> PCHub:
    """Make sure the channel is listening and the user's Chrome is connected. If it is not, the error says exactly what the one human step is
    (Chrome does not allow an extension to be installed silently). A pairing code is created when none is active."""
    hub = pc_hub(root or HOME)
    if hub.srv is None:
        raise BridgeError(hub.not_ready_reason(), "browser", 503)
    if not hub.paired() and not (hub.pair_code and time.time() < hub.pair_until):
        code = hub.new_pairing()
        log(f"personal Chrome: pairing code {code} (valid 10 minutes). " + pc_instructions(hub), "warn")
    end = time.time() + (float(os.environ.get("BRIDGE_PC_CONNECT_WAIT", "20")) if wait is None else wait)
    while not hub.connected() and time.time() < end:
        time.sleep(0.4)
    if not hub.connected():
        extra = f" Pairing code: {hub.pair_code}." if hub.pair_code and time.time() < hub.pair_until else ""
        raise BridgeError(hub.not_ready_reason() + extra, "browser", 503)
    return hub


def pc_status_text(hub: Optional[PCHub] = None) -> str:
    hub = hub or pc_hub(start=False)
    st = hub.status()
    lines = [f"Personal Chrome mode: {st['mode']}  (BRIDGE_BROWSER=playwright selects the old separate browser)",
             f"channel: 127.0.0.1:{st['port']}  listening={st['listening']}  paired={st['paired']}  connected={st['connected']}",
             f"extension folder: {hub.root / 'extension'}  (version {PC_VERSION}, files verified by SHA-256)", "", "capabilities (what is and is not equivalent to the old Playwright browser):"]
    lines += [f"  - [{lvl}] {name}" for name, lvl, _api in PC_CAPABILITIES]
    lines += ["", "install: " + pc_instructions(hub),
              "privacy: Chrome shows its own 'is debugging this browser' bar while a tab is inspected; the toolbar badge is red then. Only tabs the bridge opened, or that you allow in the popup, are touched."]
    return "\n".join(lines)


def pc_cli(args: Any) -> int:
    """--pc-install / --pc-pair / --pc-status. They never contact a site and never send a model request."""
    hub = pc_hub(HOME, start=False)
    r = pc_extract(hub.root)
    if args.pc_install:
        print(f"extension written to {r['path']} ({r['files']} files, {len(r['changed'])} changed, hashes verified)")
        print(pc_instructions(hub))
        return 0
    if args.pc_pair:
        print("starting the channel to show a pairing code; press Ctrl+C when the extension says 'paired'...")
        if not hub.start():
            print(hub.not_ready_reason())
            return 1
        print(f"pairing code: {hub.new_pairing()}   (port {hub.port}; valid 10 minutes)")
        print(pc_instructions(hub))
        try:
            while not hub.paired():
                time.sleep(0.5)
            print("paired. The extension keeps its token in Chrome; start the bridge normally now.")
        except KeyboardInterrupt:
            pass
        return 0
    print(pc_status_text(hub))
    return 0


# ============================================================================
# Browser layer (Personal Chrome by default; Playwright only when BRIDGE_BROWSER=playwright) - used only to log in, learn, refresh tokens, and as fallback tiers
# ============================================================================
def ensure_playwright() -> None:
    """Name kept for compatibility. Personal-Chrome mode (default): checks that the channel is up and your Chrome is connected, and says the one human step if not.
    Playwright is only touched when the owner explicitly selects it with BRIDGE_BROWSER=playwright."""
    if pc_mode() == "playwright":
        return _ensure_playwright_legacy()
    pc_ensure_ready()


def _ensure_playwright_legacy() -> None:
    try:
        __import__("playwright.sync_api")
    except ImportError:
        log("installing playwright (one time)...", "warn")
        subprocess.check_call([sys.executable, "-m", "pip", "install", "--quiet", "playwright"])
    # make sure a browser exists (system Chrome/Edge is preferred, otherwise download Chromium once)
    from playwright.sync_api import sync_playwright
    with sync_playwright() as p:
        for ch in ("chrome", "msedge", None):
            try:
                b = p.chromium.launch(channel=ch, headless=True) if ch else p.chromium.launch(headless=True)
                b.close()
                return
            except Exception:
                continue
    log("downloading Chromium (one time)...", "warn")
    subprocess.check_call([sys.executable, "-m", "playwright", "install", "chromium"])


class AccountBrowser:
    """One persistent browser profile per account, owned by one thread (Playwright sync API is thread-bound).
    Closes itself after an idle period so it does not hold RAM."""

    def __init__(self, acct_id: str, profile: Path, idle: float = 90):
        self.acct_id, self.profile, self.idle = acct_id, profile, idle
        self.q: "queue.Queue" = queue.Queue()
        self.thread: Optional[threading.Thread] = None
        self.lock = threading.Lock()
        self.mode: Optional[bool] = None     # headless flag of the live context
        self.page_cache: Dict[str, Any] = {}

    def run(self, fn: Callable[[Any], Any], headless: bool = True, idle: Optional[float] = None) -> Any:
        fut: Future = Future()
        with self.lock:
            if not self.thread or not self.thread.is_alive():
                self.thread = threading.Thread(target=self._loop, daemon=True, name=f"browser-{self.acct_id}")
                self.thread.start()
        self.q.put((fn, headless, idle, fut))
        return fut.result()

    def close(self) -> None:
        fut: Future = Future()
        if self.thread and self.thread.is_alive():
            self.q.put((None, None, None, fut))
            try:
                fut.result(timeout=20)
            except Exception:
                pass

    def _open(self, pw: Any, headless: bool) -> Any:
        if pc_mode() == "personal_chrome":                      # the user's own Chrome: a context that owns only the tabs it opens (headless=True -> background tabs)
            hub = pc_hub(self.profile.parent.parent)
            if not hub.connected():
                hub = pc_ensure_ready(self.profile.parent.parent)
            return PCContext(hub, self.acct_id, background=bool(headless))
        self.profile.mkdir(parents=True, exist_ok=True)
        last: Optional[Exception] = None
        for ch in ("chrome", "msedge", None):
            try:
                args = ["--no-first-run", "--no-default-browser-check"]
                kw: Dict[str, Any] = dict(user_data_dir=str(self.profile), headless=headless,
                                          viewport={"width": 1280, "height": 860} if headless else None,
                                          args=args)
                if not headless:
                    # The visible window is where the OWNER logs in by hand (Google, etc.). Playwright's default
                    # --enable-automation flag and the AutomationControlled blink feature make the browser announce
                    # itself as automated (navigator.webdriver = true), and Google then refuses the sign-in with
                    # "This browser or app may not be secure". Dropping only these two signals makes the window an
                    # ordinary Chrome window. Nothing is spoofed or injected (no fake UA, no script patches); headless
                    # runs are unchanged.
                    args.append("--disable-blink-features=AutomationControlled")
                    kw["ignore_default_args"] = ["--enable-automation"]
                if ch:
                    kw["channel"] = ch
                ctx = pw.chromium.launch_persistent_context(**kw)
                if not ch:
                    log("no system Chrome/Edge found: using bundled Chromium; Google may still refuse sign-in there, install Google Chrome", "warn")
                return ctx
            except Exception as e:
                last = e
        raise BridgeError(f"cannot launch a browser: {last}", "browser", 500)

    def _loop(self) -> None:
        pw = None
        if pc_mode() == "playwright":                           # explicit opt-in only; the default path never imports Playwright
            from playwright.sync_api import sync_playwright
            pw = sync_playwright().start()
        ctx = None
        idle = self.idle
        try:
            while True:
                try:
                    fn, headless, job_idle, fut = self.q.get(timeout=idle if ctx else 3600)
                except queue.Empty:
                    break
                if fn is None:
                    fut.set_result(True)
                    break
                try:
                    if ctx is not None and self.mode != headless:
                        ctx.close()
                        ctx, self.page_cache = None, {}
                    if ctx is None:
                        ctx = self._open(pw, headless)
                        self.mode = headless
                    idle = job_idle or self.idle
                    fut.set_result(fn(ctx))
                except Exception as e:
                    fut.set_exception(e)
                    try:
                        if ctx is not None:
                            ctx.pages
                    except Exception:
                        ctx, self.page_cache = None, {}
        finally:
            try:
                if ctx is not None:
                    ctx.close()
            except Exception:
                pass
            try:
                if pw is not None:
                    pw.stop()
            except Exception:
                pass
            self.page_cache = {}


# ---- page helpers -----------------------------------------------------------------------------
INPUT_SELECTORS = ("textarea", "div[contenteditable='true']", "[role='textbox']", "input[type='text']")


def find_input(page: Any) -> Optional[Any]:
    for sel in INPUT_SELECTORS:
        loc = page.locator(sel + ":visible")
        try:
            if loc.count():
                return loc.last
        except Exception:
            continue
    return None


def login_detected(page: Any) -> bool:
    try:
        if page.locator("input[type='password']:visible").count():
            return False
        return find_input(page) is not None
    except Exception:
        return False


def read_storage(page: Any, ctx: Any) -> Dict[str, Any]:
    js = """() => { const d = s => { const o = {}; try { for (let i = 0; i < s.length; i++) { const k = s.key(i); o[k] = String(s.getItem(k)).slice(0, 6000); } } catch (e) {} return o; };
                    return {local: d(localStorage), session: d(sessionStorage)}; }"""
    try:
        st = page.evaluate(js)
    except Exception:
        st = {"local": {}, "session": {}}
    st["cookies"] = ctx.cookies()
    return st


def resolve_source(src: Optional[Dict[str, Any]], storage: Dict[str, Any]) -> Optional[str]:
    if not src:
        return None
    t = src.get("type")
    if t in ("localStorage", "sessionStorage"):
        raw = (storage.get("local" if t == "localStorage" else "session") or {}).get(src["key"])
        if raw is None:
            return None
        if "json_path" in src:
            o = _json_or_none(raw)
            for p in src["json_path"]:
                try:
                    o = o[p]
                except Exception:
                    return None
            return o if isinstance(o, str) else None
        return raw
    if t == "cookie":
        for c in storage.get("cookies") or []:
            if c["name"] == src["name"]:
                return c["value"]
    return None


def _post_text(r: Any) -> Optional[str]:
    """Request body as text. Playwright's post_data raises on a binary body (e.g. a gzip-compressed beacon); then the raw bytes are decoded (gzip opened) instead."""
    try:
        return r.post_data
    except Exception:
        pass
    try:
        raw = r.post_data_buffer
        if not raw:
            return None
        if raw[:2] == b"\x1f\x8b":
            raw = gzip.decompress(raw)
        return raw.decode("utf-8", "replace")
    except Exception:
        return None


class Capture:
    """Records fetch/xhr traffic of a whole browser context.
    Playwright's Request.response() and Response.finished() WAIT without a time limit. A single request that never answers (a long-poll, an
    event stream, a hung beacon) used to freeze the whole learn/login loop at "probe 1/3" and made the "I'm done logging in" button look dead.
    Here the answers are collected from the context events instead, and every wait is bounded."""
    STUCK_S = 15.0

    def __init__(self, ctx: Any):
        self.ctx = ctx
        self.reqs: List[Any] = []
        self.scripts: List[Any] = []
        self._resp: Dict[Any, Any] = {}
        self._fin: Set[Any] = set()
        self._t0: Dict[Any, float] = {}
        ctx.on("request", self._on)
        ctx.on("response", self._on_resp)
        ctx.on("requestfinished", self._on_fin)
        ctx.on("requestfailed", self._on_fin)

    def _on(self, r: Any) -> None:
        if r.resource_type in ("fetch", "xhr", "eventsource"):
            self.reqs.append(r)
            self._t0[r] = time.time()
        elif r.resource_type == "script" and len(self.scripts) < 80:
            self.scripts.append(r)
            self._t0[r] = time.time()

    def _on_resp(self, resp: Any) -> None:
        try:
            self._resp[resp.request] = resp
        except Exception:
            pass

    def _on_fin(self, r: Any) -> None:
        self._fin.add(r)

    def response_of(self, r: Any) -> Optional[Any]:
        return self._resp.get(r)

    def age(self, r: Any) -> float:
        return time.time() - self._t0.get(r, time.time())

    def poll(self, r: Any) -> str:
        """'ready' (finished with an answer: safe to read), 'wait' (still in flight and young), 'skip' (failed, or in flight for too long: never wait for it)."""
        if r in self._fin:
            return "ready" if r in self._resp else "skip"
        return "wait" if self.age(r) < self.STUCK_S else "skip"

    def _pump(self, ms: int = 150) -> None:
        try:
            pg = next((p for p in self.ctx.pages if not p.is_closed()), None)
            if pg is not None:
                pg.wait_for_timeout(ms)               # lets Playwright deliver its events
                return
        except Exception:
            pass
        time.sleep(ms / 1000.0)

    def wait_done(self, r: Any, timeout: float) -> bool:
        end = time.time() + max(0.0, timeout)
        while r not in self._fin:
            if time.time() >= end:
                return False
            self._pump(150)
        return True

    def script_bodies(self, limit: int = 40) -> List[Tuple[str, str]]:
        out = []
        for r in self.scripts[:limit]:
            try:
                resp = self._resp.get(r)
                if resp is not None and r in self._fin and resp.status == 200:
                    b = resp.body()
                    if len(b) < 4_000_000:
                        out.append((r.url, b.decode("utf-8", "replace")))
            except Exception:
                continue
        return out

    def mark(self) -> int:
        return len(self.reqs)

    def snapshot(self, since: int, settle: float = 6.0) -> List[Dict[str, Any]]:
        out = []
        end = time.time() + settle                      # one shared time budget for requests that are still finishing
        for r in self.reqs[since:]:
            try:
                done = r in self._fin or self.wait_done(r, end - time.time())
                resp = self._resp.get(r)
                body, status, rh = "", 0, {}
                if resp is not None:
                    status = resp.status
                    try:
                        rh = {k.lower(): v for k, v in (resp.all_headers() if done else resp.headers).items()}
                    except Exception:
                        rh = {k.lower(): v for k, v in resp.headers.items()}
                    if done:
                        try:
                            body = resp.body().decode("utf-8", "replace")
                        except Exception:
                            body = ""
                try:
                    qh = r.all_headers() if (done or resp is not None) else r.headers
                except Exception:
                    qh = r.headers
                out.append({"url": r.url, "method": r.method, "headers": {k.lower(): v for k, v in qh.items()},
                            "body": _post_text(r), "status": status, "resp_headers": rh, "resp_body": body})
            except Exception as e:
                log(f"capture skip: {e}", "debug")
        return out


# ---- UI readiness gate + pacing -----------------------------------------------------------------------------
# A page that shows a bot check (Cloudflare "Just a moment", a Turnstile widget, a red "cloudflare_challenge" line under the box) locks the chat input
# until the check finishes. The bridge never types into a locked input, never forces text in with the keyboard, never solves the check: it WAITS like a
# person would (most checks finish by themselves in a few seconds), keeps a minimum gap between sends, and after a check that did not finish it backs off
# (growing waits) and hands the window to the owner instead of retrying in a loop.
UI_READY_TIMEOUT = float(os.environ.get("BRIDGE_UI_READY_TIMEOUT", "90"))        # seconds to wait for the page to become usable
UI_MIN_GAP = float(os.environ.get("BRIDGE_UI_MIN_GAP", "4"))                     # minimum seconds between two sends to the same site
UI_BACKOFF_BASE = float(os.environ.get("BRIDGE_UI_BACKOFF", "60"))               # first back-off after an unfinished check (doubles, capped)
UI_BACKOFF_MAX = 900.0
UI_STABLE_LOOKS = 2                                                              # the page must look ready this many polls in a row
UI_CHALLENGE_TEXT_RE = re.compile(r"cloudflare[_\s-]?challenge|cf[_-]?chl|challenge[_\s-]?(?:required|failed|expired)", re.I)
_UI_GATE_LOCK = threading.Lock()
_UI_GATE: Dict[str, Dict[str, float]] = {}

UI_STATE_JS = """(sels) => {
  const vis = e => { const r = e.getBoundingClientRect(), cs = getComputedStyle(e); return r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.display !== 'none'; };
  let box = null;
  for (const s of sels) { const els = [...document.querySelectorAll(s)].filter(vis); if (els.length) { box = els[els.length - 1]; break; } }
  const out = {has_input: !!box, enabled: false, editable: false, scope_text: '', widget: false, title: document.title || ''};
  if (box) {
    const dis = box.disabled === true || box.hasAttribute('disabled') || box.getAttribute('aria-disabled') === 'true';
    const ro = box.readOnly === true || box.hasAttribute('readonly') || box.getAttribute('contenteditable') === 'false';
    out.enabled = !dis; out.editable = !ro;
    let c = box; for (let i = 0; i < 4 && c.parentElement && c.parentElement !== document.body; i++) c = c.parentElement;
    out.scope_text = (c.innerText || '').slice(0, 1500);
  }
  out.widget = [...document.querySelectorAll("iframe[src*='challenges.cloudflare.com'], .cf-turnstile iframe, [id^='cf-chl'], #challenge-running, #challenge-stage")].some(vis);
  return out;
}"""


def ui_page_state(page: Any) -> Dict[str, Any]:
    """What the page looks like right now, from the DOM only. `blocked_by` is '' when the chat input can be used,
    else one of: no_input | disabled | readonly | widget | challenge_text | challenge_page. `challenge` says whether a bot check is the likely reason."""
    raw = page.evaluate(UI_STATE_JS, list(INPUT_SELECTORS)) or {}
    why = ""
    ch = detect_challenge(0, None, str(raw.get("title") or ""), "", "")
    if ch:
        why = "challenge_page"
    elif raw.get("widget"):
        why = "widget"
    elif UI_CHALLENGE_TEXT_RE.search(str(raw.get("scope_text") or "")):
        why = "challenge_text"
    elif not raw.get("has_input"):
        why = "no_input"
    elif not raw.get("enabled"):
        why = "disabled"
    elif not raw.get("editable"):
        why = "readonly"
    return {"blocked_by": why, "challenge": why in ("challenge_page", "widget", "challenge_text"), "raw": raw}


def ui_input_ready(page: Any) -> bool:
    try:
        return not ui_page_state(page)["blocked_by"]
    except Exception as e:
        if is_window_closed_error(e):
            raise
        return False


def _ui_host(page: Any) -> str:
    try:
        return (urllib.parse.urlsplit(page.url).hostname or "").lower()
    except Exception:
        return ""


def ui_gate_check(host: str) -> None:
    """Fail fast (without touching the page) while the site is in a back-off after an unfinished check."""
    with _UI_GATE_LOCK:
        left = _UI_GATE.get(host, {}).get("blocked_until", 0.0) - time.time()
    if left > 0:
        raise BridgeError(f"the site's bot check did not finish earlier; not sending anything for another {int(left) + 1}s (the owner can solve it in the browser window)", "challenge", 503, retry_after=left)


def ui_gate_failed(host: str) -> float:
    with _UI_GATE_LOCK:
        g = _UI_GATE.setdefault(host, {"strikes": 0.0, "blocked_until": 0.0, "last_send": 0.0})
        g["strikes"] += 1
        wait = min(UI_BACKOFF_MAX, UI_BACKOFF_BASE * (2 ** (g["strikes"] - 1)))
        g["blocked_until"] = time.time() + wait
        return wait


def ui_gate_ok(host: str) -> None:
    with _UI_GATE_LOCK:
        g = _UI_GATE.setdefault(host, {"strikes": 0.0, "blocked_until": 0.0, "last_send": 0.0})
        g["strikes"], g["blocked_until"] = 0.0, 0.0


def ui_pace(page: Any, host: str) -> None:
    """Keep at least UI_MIN_GAP seconds between two sends to the same site (the page's own clock, so the Playwright thread is never blocked)."""
    with _UI_GATE_LOCK:
        g = _UI_GATE.setdefault(host, {"strikes": 0.0, "blocked_until": 0.0, "last_send": 0.0})
        gap = max(UI_MIN_GAP, g.get("learned", 0.0))
        wait = g["last_send"] + gap - time.time()
        g["last_send"] = max(time.time(), g["last_send"] + gap) if wait > 0 else time.time()
    if wait > 0:
        page.wait_for_timeout(int(wait * 1000))


def ui_gate_learn(host: str, waited: float) -> None:
    """Remember how long the page needed to become usable; the gap between sends grows to 1.5x that (cap 30 s). Measured, never guessed."""
    with _UI_GATE_LOCK:
        g = _UI_GATE.setdefault(host, {"strikes": 0.0, "blocked_until": 0.0, "last_send": 0.0})
        g["learned"] = min(30.0, max(g.get("learned", 0.0) * 0.7, waited * 1.5))


_UI_WHY = {"no_input": "the chat input is not on the page yet", "disabled": "the chat input is locked", "readonly": "the chat input is read-only",
           "widget": "a verification widget is on the page", "challenge_text": "the page shows a challenge message under the input",
           "challenge_page": "the page is a verification page ('Just a moment')"}


def ui_wait_ready(page: Any, timeout: float = UI_READY_TIMEOUT, say: Optional[Callable[[str], None]] = None, poll_ms: int = 1000) -> None:
    """Block until the chat input is visible, enabled, editable and no bot check is showing, for UI_STABLE_LOOKS polls in a row.
    On timeout: a check that never finished -> BridgeError kind 'challenge' (the owner is asked, no retry loop); anything else -> kind 'ui'."""
    t0, last_say, ok, seen_challenge, told = time.time(), 0.0, 0, False, False
    last = ""
    while True:
        try:
            st = ui_page_state(page)
        except Exception as e:
            if is_window_closed_error(e):
                raise
            st = {"blocked_by": "no_input", "challenge": False}
        why = st["blocked_by"]
        if not why:
            ok += 1
            if ok >= UI_STABLE_LOOKS:
                if told:
                    ui_gate_learn(_ui_host(page), time.time() - t0)
                    if say:
                        say(f"the page is ready now (it took {int(time.time() - t0)}s) - continuing")
                return
        else:
            ok, last = 0, why
            seen_challenge = seen_challenge or bool(st["challenge"])
            el = time.time() - t0
            if say and (not told or el - last_say >= 15):
                told, last_say = True, el
                say(f"waiting: {_UI_WHY.get(why, why)} ({int(el)}s of {int(timeout)}s) - nothing is typed or sent until the page is usable")
        el = time.time() - t0
        if el > timeout:
            break
        if last == "no_input" and not seen_challenge and el > min(timeout, 25.0):
            raise BridgeError("chat input box not found on the page", "ui")
        page.wait_for_timeout(poll_ms)
    if seen_challenge or last in ("disabled", "readonly"):
        raise BridgeError(f"the page stayed blocked by a bot check for {int(timeout)}s ({_UI_WHY.get(last, last)}); nothing was sent", "challenge", 503)
    raise BridgeError(f"the chat page was not usable after {int(timeout)}s ({_UI_WHY.get(last, last)}); nothing was sent", "ui")


def ui_type_and_send(page: Any, text: str, say: Optional[Callable[[str], None]] = None) -> None:
    """Type the prompt into the chat box and send it - only when the box is really usable. Never forces text into a locked input."""
    host = _ui_host(page)
    ui_gate_check(host)
    try:
        ui_wait_ready(page, say=say)
    except BridgeError as e:
        if e.kind == "challenge":
            wait = ui_gate_failed(host)
            e = BridgeError(str(e) + f"; backing off {int(wait)}s before the next attempt", "challenge", 503, retry_after=wait)
        raise e
    ui_pace(page, host)
    box = find_input(page)
    if box is None:
        raise BridgeError("chat input box not found on the page", "ui")
    box.click(timeout=5000)
    try:
        box.fill(text, timeout=8000)
    except Exception:
        if not ui_input_ready(page):
            raise BridgeError("the chat input became locked while typing; nothing was sent", "challenge", 503)
        box.click(timeout=5000)                                                  # an editor that refuses fill() but is enabled: typing the text is still honest input
        page.keyboard.insert_text(text)
    page.wait_for_timeout(250)
    if not ui_input_ready(page):                                                 # a check can appear right after the text lands: do not press Enter into it
        wait = ui_gate_failed(host)
        raise BridgeError(f"a bot check appeared while the message was being typed; it was not sent; backing off {int(wait)}s", "challenge", 503, retry_after=wait)
    page.keyboard.press("Enter")
    page.wait_for_timeout(1500)
    try:
        post = ui_page_state(page)
    except Exception as e:
        if is_window_closed_error(e):
            raise
        post = {"challenge": False}
    if post.get("challenge"):
        wait = ui_gate_failed(host)
        raise BridgeError(f"the site answered the send with a bot check; not retrying for {int(wait)}s", "challenge", 503, retry_after=wait)
    ui_gate_ok(host)


_UI_NEW_CHAT_RE = re.compile(r"^\s*(new chat|new conversation|start new chat|new)\s*$", re.I)


def ui_new_chat(page: Any, answer_sel: Optional[str]) -> bool:
    """Open a fresh conversation with the site's own 'New chat' control. A reload would start a new browser check every time; this keeps the page alive.
    Trusted only when the old answers are gone and the input is usable again; otherwise the caller opens the address as before."""
    if not answer_sel:
        return False
    makers: List[Callable[[], Any]] = [
        lambda: page.locator("[data-testid='create-new-chat-button']:visible"),
        lambda: page.get_by_role("link", name=_UI_NEW_CHAT_RE),
        lambda: page.get_by_role("button", name=_UI_NEW_CHAT_RE),
        lambda: page.get_by_text(_UI_NEW_CHAT_RE),
    ]
    for mk in makers:
        try:
            loc = mk()
            if loc.count() == 0:
                continue
            loc.first.click(timeout=3000)
            page.wait_for_timeout(1800)
            if page.locator(answer_sel).count() == 0 and ui_input_ready(page):
                return True
        except Exception as e_:
            if is_window_closed_error(e_):
                raise
    return False


def ui_click_send(page: Any) -> bool:
    for sel in ("button[type='submit']:visible", "button[aria-label*='send' i]:visible", "[data-testid*='send' i]:visible",
                "button:has(svg):visible"):
        try:
            loc = page.locator(sel)
            if loc.count():
                loc.last.click(timeout=2000)
                return True
        except Exception:
            continue
    return False


def run_probe(page: Any, cap: Capture, probe: Dict[str, str], timeout: float = 90) -> Dict[str, Any]:
    start = cap.mark()
    ui_type_and_send(page, probe["prompt"])
    deadline = time.time() + timeout
    clicked = False
    chat_req = None
    while time.time() < deadline:
        page.wait_for_timeout(400)
        for r in cap.reqs[start:]:
            try:
                if r.method in ("POST", "PUT", "PATCH") and probe["nonce"] in (_post_text(r) or ""):
                    chat_req = r
            except Exception:
                pass
        if chat_req is None and not clicked and time.time() > deadline - timeout + 3:
            clicked = ui_click_send(page)
            continue
        if chat_req is not None:
            cap.wait_done(chat_req, max(2.0, deadline - time.time()))      # bounded: never waits past the probe deadline
            page.wait_for_timeout(500)
            break
    if chat_req is None:
        raise LearnError("the prompt never appeared in a network request (WebSocket / protobuf / blocked?)")
    snap = cap.snapshot(start)
    chat = next((s for s in snap if s["url"] == chat_req.url and s["method"] == chat_req.method and probe["nonce"] in (s["body"] or "")), None)
    pre = [s for s in snap if s is not chat and snap.index(s) < snap.index(chat) and s["method"] in ("POST", "GET", "PUT")]
    return {"probe": probe, "chat": chat, "pre": pre, "page_url": page.url}


ANSWER_SELECTOR_JS = """(args) => {
  const [code] = args; const out = [];
  const els = [...document.querySelectorAll('body *')].filter(e => e.innerText && e.innerText.includes(code) &&
        e.innerText.toLowerCase().includes('eight') && !e.innerText.includes('Reply with exactly') && e.children.length < 40);
  if (!els.length) return out;
  const deepest = els.filter(e => !els.some(o => o !== e && e.contains(o)));
  let el = deepest[deepest.length - 1];
  for (let i = 0; i < 5 && el && el !== document.body; i++, el = el.parentElement) {
    const cls = [...el.classList].filter(c => !(/\\d/.test(c) && c.length >= 6) && !/^(css|sc|jsx|svelte|_)[-_]?[A-Za-z0-9]{3,}$/.test(c)).slice(0, 3);
    const tag = el.tagName.toLowerCase();
    const attrs = ['data-role', 'data-message-author-role', 'data-testid'].filter(a => el.getAttribute(a)).map(a => `[${a}="${el.getAttribute(a)}"]`);
    const sel = tag + attrs.join('') + cls.map(c => '.' + CSS.escape(c)).join('');
    out.push(sel);
  }
  return out;
}"""


def learn_ui_selectors(page: Any, code1: str, code2: str) -> Optional[Dict[str, Any]]:
    """Called after probe 2 in the same chat: finds a selector matching exactly one answer per assistant turn."""
    cands: List[str] = []
    for _ in range(14):                      # DOM rendering lags the network: wait for the full answer text
        try:
            cands = page.evaluate(ANSWER_SELECTOR_JS, [code2]) or []
        except Exception:
            cands = []
        if cands:
            break
        page.wait_for_timeout(500)
    if not cands:
        return None
    for sel in cands:
        try:
            els = page.locator(sel)
            n = els.count()
            if n >= 2 and code2.lower() in els.last.inner_text().lower() and code1.lower() in els.nth(n - 2).inner_text().lower():
                return {"answer": sel}
        except Exception:
            continue
    return None


# ============================================================================
# Backends: DIRECT (no browser) -> PAGE (in-page fetch) -> UI (typing)  + account manager
# ============================================================================
class Inline:
    """Lets browser-side helpers run inside an already-open browser thread."""
    def __init__(self, ctx: Any):
        self.ctx, self.page_cache = ctx, {}

    def run(self, fn: Callable[[Any], Any], headless: bool = True, idle: Optional[float] = None) -> Any:
        return fn(self.ctx)


def _page(ab: Any, ctx: Any, base: str, entry: Optional[str] = None) -> Any:
    pg = ab.page_cache.get("page")
    try:
        if pg is None or pg.is_closed():
            raise RuntimeError
    except Exception:
        pg = ctx.pages[0] if ctx.pages else ctx.new_page()
        ab.page_cache["page"] = pg
    if not (pg.url or "").startswith(base):
        pg.goto(entry or base + "/", wait_until="domcontentloaded", timeout=45000)
        pg.wait_for_timeout(800)
    return pg


class PageTransport:
    """fetch() executed inside a real page: same cookies/TLS/origin as the browser, no UI automation."""
    name = "page"
    skip_headers = {"cookie", "user-agent", "origin", "referer", "accept-encoding", "content-length", "host", "connection"}

    def __init__(self, ab: Any, base: str, session: Dict[str, Any], entry: Optional[str] = None):
        self.ab, self.base, self.session, self.entry = ab, base, session, entry

    def prepare(self, url: str, headers: Dict[str, str]) -> Dict[str, str]:
        return headers

    def request(self, method: str, url: str, headers: Dict[str, str], body: Optional[bytes], timeout: float = 300):
        rid = uuid.uuid4().hex
        hdrs = {k: v for k, v in headers.items() if k not in self.skip_headers and v != ""}
        start_js = """(a) => { window.__br = window.__br || {}; const st = window.__br[a.id] = {chunks: [], done: false, status: 0, hdr: {}, error: null};
            fetch(a.url, {method: a.method, headers: a.headers, body: a.body, credentials: 'include'}).then(async r => {
              st.status = r.status; r.headers.forEach((v, k) => st.hdr[k] = v);
              const rd = r.body.getReader(), dec = new TextDecoder();
              for (;;) { const {value, done} = await rd.read(); if (done) break; st.chunks.push(dec.decode(value, {stream: true})); }
              st.done = true; }).catch(e => { st.error = String(e); st.done = true; }); return true; }"""
        poll_js = """(id) => { const s = window.__br[id]; const c = s.chunks.splice(0); return {c: c, done: s.done, status: s.status, hdr: s.hdr, error: s.error}; }"""
        body_s = body.decode("utf-8") if body is not None else None
        self.ab.run(lambda ctx: _page(self.ab, ctx, self.base, self.entry).evaluate(start_js, {"id": rid, "url": url, "method": method,
                                                                                    "headers": hdrs, "body": body_s}), True, 120)
        first = self._poll(rid, poll_js, wait_status=True)
        status, rh = first["status"], first["hdr"]

        def gen() -> Iterator[bytes]:
            st = first
            while True:
                for c in st["c"]:
                    yield c.encode("utf-8")
                if st["done"]:
                    if st.get("error"):
                        raise BridgeError(f"in-page fetch failed: {st['error']}", "network", 502)
                    return
                time.sleep(0.12)
                st = self._poll(rid, poll_js)
        return status, rh, gen()

    def _poll(self, rid: str, js: str, wait_status: bool = False) -> Dict[str, Any]:
        deadline = time.time() + 60
        while True:
            st = self.ab.run(lambda ctx: _page(self.ab, ctx, self.base, self.entry).evaluate(js, rid), True, 120)
            if st.get("error") and st["done"] and not st["c"]:
                raise BridgeError(f"in-page fetch failed: {st['error']}", "network", 502)
            if not wait_status or st["status"] or st["done"] or time.time() > deadline:
                return st
            time.sleep(0.1)


class DirectBackend:
    tier = "direct"

    def __init__(self, recipe: Dict[str, Any], session: Dict[str, Any]):
        self.client = RecipeClient(recipe, DirectTransport(session), session)

    def new_conv(self, model: Optional[str] = None) -> Dict[str, Any]:
        return self.client.new_conv(model)

    def ask(self, conv: Dict[str, Any], prompt: str, cancel: Optional[threading.Event] = None, model: Optional[str] = None) -> Iterator[str]:
        return self.client.ask(conv, prompt, cancel, model)

    def upload_text(self, conv: Dict[str, Any], text: str, cancel: Optional[threading.Event] = None) -> Dict[str, Any]:
        return self.client.upload_text(conv, text, cancel)


class PageBackend(DirectBackend):
    tier = "page"

    def __init__(self, recipe: Dict[str, Any], session: Dict[str, Any], ab: Any):
        self.client = RecipeClient(recipe, PageTransport(ab, recipe["base"], session, recipe.get("entry")), session)
        self.ab, self.recipe, self.session = ab, recipe, session

    def sync_auth(self) -> None:
        def read(ctx: Any) -> Dict[str, Any]:
            return read_storage(_page(self.ab, ctx, self.recipe["base"], self.recipe.get("entry")), ctx)
        st = self.ab.run(read, True, 120)
        for name, spec in (self.recipe.get("auth") or {}).items():
            v = resolve_source(spec.get("source"), st)
            if v:
                self.session.setdefault("auth", {})[name] = v

    def ask(self, conv: Dict[str, Any], prompt: str, cancel: Optional[threading.Event] = None, model: Optional[str] = None) -> Iterator[str]:
        self.sync_auth()
        return self.client.ask(conv, prompt, cancel, model)

    def upload_text(self, conv: Dict[str, Any], text: str, cancel: Optional[threading.Event] = None) -> Dict[str, Any]:
        self.sync_auth()
        return self.client.upload_text(conv, text, cancel)


UI_GENERATING_SELECTOR = ('button[aria-label*="stop" i], button[data-testid*="stop" i], button[title*="stop" i], [aria-label*="stop generating" i], '
                          '[aria-label*="stop streaming" i], [aria-label*="stop response" i], [data-testid*="stop-button" i]')


def ui_generating(pg: Any) -> bool:
    """True while the page shows a 'stop generating' control, i.e. the site is still writing the answer. Never raises (a page without such a control just answers False)."""
    try:
        return pg.locator(UI_GENERATING_SELECTOR).count() > 0
    except Exception:
        return False


class UIBackend:
    tier = "ui"
    fenced_tools = True

    def __init__(self, recipe: Dict[str, Any], ab: Any):
        self.recipe, self.ab = recipe, ab
        self.sel = (recipe.get("ui") or {}).get("answer")
        self.diff = bool((recipe.get("ui") or {}).get("diff"))

    def new_conv(self, model: Optional[str] = None) -> Dict[str, Any]:
        return {"url": None, "turn": 0, "model": model}

    def select_model(self, pg: Any, model: str) -> None:
        """Replay the recorded UI steps that choose a model ({{model}} is the variant's display label here)."""
        ctx = {"model": model}
        for step in (self.recipe.get("model_select") or {}).get("steps") or []:
            if step.get("click"):
                pg.click(str(render(step["click"], ctx)))
            elif step.get("click_text"):
                pg.get_by_text(str(render(step["click_text"], ctx)), exact=True).first.click()
            else:
                raise BridgeError(f"unknown model_select step {step!r}", "setup", 500)
            pg.wait_for_timeout(300)

    def ask(self, conv: Dict[str, Any], prompt: str, cancel: Optional[threading.Event] = None, model: Optional[str] = None) -> Iterator[str]:
        model = model or conv.get("model")
        ui_select = (self.recipe.get("model_select") or {}).get("kind") == "ui" and bool(model)
        if ui_select and model != conv.get("model"):
            conv["url"] = None                                   # a different model means a fresh chat
        if not self.sel and not self.diff:
            raise BridgeError("UI tier has no learned answer selector - re-learn this site", "ui")
        base = self.recipe["base"]

        before: set = set()

        def page_text(ctx: Any) -> Tuple[int, str, str, bool]:
            pg = _page(self.ab, ctx, base, self.recipe.get("entry"))
            lines = [l.strip() for l in pg.inner_text("body").splitlines() if l.strip()]
            snip = prompt.strip()[:40]
            new = [l for l in lines if l not in before and not (snip and snip in l)]
            return len(new), "\n".join(new), pg.url, ui_generating(pg)

        def start(ctx: Any) -> int:
            pg = _page(self.ab, ctx, base, self.recipe.get("entry"))
            target = conv["url"] or self.recipe.get("entry") or base + "/"
            host_ = _ui_host(pg)
            ui_gate_check(host_ or (urllib.parse.urlsplit(base).hostname or ""))      # in a back-off: touch nothing
            fresh_ok = (conv["url"] is None and not ui_select and self.sel and (pg.url or "").startswith(base) and not url_on_login_path(pg.url) and ui_new_chat(pg, self.sel))
            if not fresh_ok and (conv["url"] is None or pg.url != target):
                pg.goto(target, wait_until="domcontentloaded", timeout=45000)
                pg.wait_for_timeout(900)
            if ui_select and (conv["url"] is None or conv.get("model") != model):
                self.select_model(pg, str(model))
                conv["model"] = model
            if self.diff:
                before.update(l.strip() for l in pg.inner_text("body").splitlines() if l.strip())
                n0 = 0
            else:
                n0 = pg.locator(self.sel).count()
            ui_type_and_send(pg, prompt)
            pg.wait_for_timeout(1200)
            return n0

        def read(ctx: Any) -> Tuple[int, str, str, bool]:
            pg = _page(self.ab, ctx, base, self.recipe.get("entry"))
            loc = pg.locator(self.sel)
            n = loc.count()
            return n, (loc.last.inner_text() if n else ""), pg.url, ui_generating(pg)

        n0 = self.ab.run(start, True, 120)
        last, stable, sent, t0 = "", 0, "", time.time()
        seen_generating = False                       # once the page has shown its 'stop' control, the control going away is the real end-of-answer signal
        while time.time() - t0 < 600:
            if cancel is not None and cancel.is_set():
                return
            time.sleep(0.4)
            n, txt, url, generating = self.ab.run(page_text if self.diff else read, True, 120)
            seen_generating = seen_generating or generating
            if n > n0 and txt:
                if txt.startswith(sent):
                    d = txt[len(sent):]
                    if d:
                        yield d
                        sent = txt
                stable = stable + 1 if (txt == last and not generating) else 0
                last = txt
                # A site that pauses mid-answer (thinking, a tool-call block, a slow chunk) must not be taken for finished: with a visible 'stop' control the answer ends when it is gone
                # (2 s of calm); without any such control the text must stay unchanged for 8 s.
                if stable >= (5 if seen_generating else 20):
                    conv["url"], conv["turn"] = url, conv["turn"] + 1
                    return
        raise BridgeError("UI tier timed out waiting for the answer", "ui", 504)


def verify_recipe(backend: Any, name: str = "") -> Dict[str, Any]:
    """Replays a fresh probe pair through a backend; returns {ok, continuity, error}."""
    try:
        conv = backend.new_conv()
        p = make_probe_prompt()
        t1 = "".join(backend.ask(conv, p["prompt"]))
        if p["expected"] not in nrm(t1):
            return {"ok": False, "error": f"{name}: answer did not contain the probe code: {t1[:80]!r}"}
        cont = False
        try:
            t2 = "".join(backend.ask(conv, "What was the connectivity-check code in my first message of this chat? "
                                           "Reply with only the code."))
            cont = p["code"].lower() in t2.lower()
        except BridgeError:
            cont = False
        return {"ok": True, "continuity": cont}
    except BridgeError as e:
        return {"ok": False, "error": f"{name}: {e}"}
    except Exception as e:
        return {"ok": False, "error": f"{name}: {type(e).__name__}: {e}"}


# ----------------------------------------------------------------------------
# docs + ready-made tool for every learned site
# ----------------------------------------------------------------------------
TOOL_EXPORTS = ["leaves", "norm_path", "set_path", "_var", "_filter", "render", "get_by_norm", "StreamDecoder",
                "TextExtractor", "cookie_header", "_proxy_for", "BridgeError", "AuthError", "RateLimited", "parse_retry_after", "parse_reset_hint", "_limited",
                "DirectTransport", "_read_all", "RecipeClient"]
TOOL_PRELUDE = '''import email.utils, http.client, json, os, re, ssl, sys, threading, time, urllib.parse, uuid
from pathlib import Path
from typing import Any, Dict, Iterator, List, Optional, Tuple
VAR_RE = re.compile(r"\\{\\{\\s*([A-Za-z_][\\w.]*)(?:\\|(\\w+))?\\s*\\}\\}")
_RATE_RE = re.compile(r"rate.?limit|too many requests|quota|usage limit|try again (later|in)|exceeded|busy", re.I)
_AUTH_RE = re.compile(r"unauthori[sz]ed|not logged|login required|invalid.{0,12}token|token.{0,12}(expired|invalid)|forbidden|please log", re.I)
'''


def generate_tool(recipe: Dict[str, Any]) -> str:
    funcs = "\n\n".join(inspect.getsource(globals()[n]) for n in TOOL_EXPORTS)
    return f'''#!/usr/bin/env python3
"""Standalone client for {recipe['host']} - generated by AI Web Bridge {VERSION}.
Talks straight to the site's server using the saved login (no browser, no bridge needed).
Usage:  python {recipe['host']}_client.py "your question"        (or run without args for a chat loop)
Re-login / refresh the session by adding the account again in the bridge dashboard."""
{TOOL_PRELUDE}
{funcs}

RECIPE = json.loads({json.dumps(json.dumps(recipe, ensure_ascii=False), ensure_ascii=False)})


def _session() -> Dict[str, Any]:
    root = Path(__file__).resolve().parent.parent
    accts = json.loads((root / "accounts.json").read_text("utf-8"))
    for a in accts:
        p = root / "sessions" / (a["id"] + ".json")
        if a.get("host") == RECIPE["host"] and p.exists():
            return json.loads(p.read_text("utf-8"))
    sys.exit("no saved session for this site - add the account in the bridge dashboard first")


def main() -> None:
    sess = _session()
    cl = RecipeClient(RECIPE, DirectTransport(sess), sess)
    conv = cl.new_conv()
    if len(sys.argv) > 1:
        for d in cl.ask(conv, " ".join(sys.argv[1:])):
            print(d, end="", flush=True)
        print()
        return
    while True:
        try:
            q = input("you> ")
        except EOFError:
            break
        for d in cl.ask(conv, q):
            print(d, end="", flush=True)
        print()


if __name__ == "__main__":
    main()
'''


def generate_doc(recipe: Dict[str, Any], verified: Dict[str, Any]) -> str:
    c, st = recipe["chat"], recipe["stream"]
    lines = [f"# {recipe['host']} - learned communication recipe", "",
             f"*Learned {time.strftime('%Y-%m-%d %H:%M', time.localtime(recipe['learned_at']))} by AI Web Bridge {VERSION}. "
             f"Active tier: **{recipe['tier']}**. Conversation continuity: **{recipe.get('continuity')}**.*", "",
             "## Chat request", f"`{c['method']} {c['url']}`", "", "Headers (template):", "```json",
             json.dumps(c["headers"], indent=2), "```", "", "Body template:", "```json", json.dumps(c["body"], indent=2, ensure_ascii=False), "```", ""]
    if recipe.get("pre"):
        lines += ["## Setup requests (run once per new chat)"]
        for s in recipe["pre"]:
            lines += [f"- `{s['method']} {s['url']}`"]
        lines += [""]
    lines += ["## Variables", "| kind | name | source |", "|---|---|---|"]
    for n, d in recipe["conv"].items():
        lines.append(f"| per-chat | `conv.{n}` | {json.dumps(d)} |")
    for n, d in recipe["state"].items():
        lines.append(f"| per-turn | `state.{n}` | {json.dumps(d)} |")
    lines += ["", "Generators: `{{uuid}}`, `{{now_ms}}`, `{{now_s}}`, `{{now_iso}}`; `{{prompt}}` is the user message.", "",
              "## Authentication", ""]
    for n, a in recipe["auth"].items():
        lines.append(f"- header `{n}` = `{a.get('prefix', '')}<token>`; token read from {json.dumps(a.get('source'))}")
    lines += ["- cookies of the logged-in browser profile are replayed as-is.", "",
              "## Response stream", f"- format: `{st['format']}`", f"- answer text paths: `{', '.join(st['text_paths'])}` "
              f"({'cumulative' if st['cumulative'] else 'incremental'})",
              f"- ignored non-answer values: `{', '.join(st['ignore_values']) or '-'}`", "",
              "## Verification", f"```json\n{json.dumps(verified, indent=2)}\n```"]
    if recipe.get("hints"):
        lines += ["", "## Front-end code excerpts the AI used"] + [f"- `{h[:400]}`" for h in recipe["hints"]]
    if recipe.get("unresolved"):
        lines += ["", "## Not derivable (why direct mode is off)"] + [f"- {u}" for u in recipe["unresolved"]]
    return "\n".join(lines) + "\n"


class ApiBackend:
    """Official API account (OpenAI- or Anthropic-compatible): native tool calls, no emulation, no browser."""
    tier = "api"

    allow_private = False

    def __init__(self, acct: Dict[str, Any], key: str):
        self.a, self.key = acct, key

    @staticmethod
    def _openai_messages(req: "NormReq") -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        if req.system.strip():
            out.append({"role": "system", "content": req.system})
        for m in req.messages:
            text = "".join(b.get("text", "") for b in m["content"] if b.get("type") == "text")
            if m["role"] == "assistant":
                msg: Dict[str, Any] = {"role": "assistant", "content": text or None}
                calls = [{"id": b.get("id", ""), "type": "function", "function": {"name": b["name"], "arguments": json.dumps(b.get("input") or {}, ensure_ascii=False)}}
                         for b in m["content"] if b.get("type") == "tool_use"]
                if calls:
                    msg["tool_calls"] = calls
                out.append(msg)
            else:
                for b in m["content"]:
                    if b.get("type") == "tool_result":
                        out.append({"role": "tool", "tool_call_id": b.get("tool_use_id", ""), "content": _result_text(b)})
                if text:
                    out.append({"role": "user", "content": text})
        return out

    def complete(self, req: "NormReq", emit: Callable[[str], None], cancel: threading.Event) -> "Outcome":
        kind = self.a["api_kind"]
        base = self.a["api_base"].rstrip("/")
        model = getattr(req, "variant_native", "") or self.a.get("api_model") or req.model
        if kind == "anthropic":
            url = base + ("/messages" if base.endswith("/v1") else "/v1/messages")
            hdr = {"x-api-key": self.key, "anthropic-version": "2023-06-01", "content-type": "application/json"}
            body: Dict[str, Any] = {"model": model, "max_tokens": req.max_tokens, "stream": True, "system": req.system,
                                    "messages": [{"role": m["role"], "content": [b for b in m["content"] if b.get("type") in ("text", "tool_use", "tool_result")] or [{"type": "text", "text": "."}]} for m in req.messages]}
            if req.tools:
                body["tools"] = [{"name": n, "description": t["description"], "input_schema": t["input_schema"]} for n, t in req.tools.items()]
            if req.tool_choice:
                body["tool_choice"] = req.tool_choice
        else:
            url = base + ("/chat/completions" if re.search(r"/v\d+$", base) else "/v1/chat/completions")
            hdr = {"authorization": "Bearer " + self.key, "content-type": "application/json"}
            body = {"model": model, "stream": True, "messages": self._openai_messages(req), "max_tokens": req.max_tokens}
            if req.tools:
                body["tools"] = [{"type": "function", "function": {"name": n, "description": t["description"], "parameters": t["input_schema"]}} for n, t in req.tools.items()]
                tc = req.tool_choice.get("type")
                if tc == "any":
                    body["tool_choice"] = "required"
                elif tc == "tool":
                    body["tool_choice"] = {"type": "function", "function": {"name": req.tool_choice.get("name")}}
        url_guard(url, self.allow_private)
        tr = DirectTransport({"cookies": [], "ua": "ai-web-bridge"})
        status, rh, it = tr.request("POST", url, hdr, json.dumps(body, ensure_ascii=False).encode(), 600)
        if status >= 400:
            raw = _read_all(it, 3000)
            if status in (401, 403):
                raise AuthError(f"API key rejected (HTTP {status}): {raw[:160]}")
            ra = parse_retry_after(rh.get("retry-after", ""))
            if status == 429:
                raise _limited(f"HTTP 429: {raw[:160]}", ra, "status")
            e5 = BridgeError(f"HTTP {status}: {raw[:240]}", "upstream", 502)
            if ra is not None:
                e5.retry_after, e5.explicit_retry_after = ra, True
            raise e5
        dec = StreamDecoder("sse")
        text: List[str] = []
        calls: Dict[Any, Dict[str, Any]] = {}
        finished = False
        declared = ""                                             # C7: the model name the provider itself declared in its response
        for chunk in it:
            if cancel.is_set():
                break
            for ev in dec.feed(chunk):
                if not isinstance(ev, dict):
                    continue
                if not declared:
                    declared = str(((ev.get("message") or {}).get("model") if kind == "anthropic" else ev.get("model")) or "")[:120]
                if kind == "anthropic":
                    t = ev.get("type")
                    if t == "content_block_start" and (ev.get("content_block") or {}).get("type") == "tool_use":
                        cb = ev["content_block"]
                        calls[ev["index"]] = {"id": cb["id"], "name": cb["name"], "args": ""}
                    elif t == "content_block_delta":
                        d = ev.get("delta") or {}
                        if d.get("type") == "text_delta":
                            text.append(d["text"])
                            emit(d["text"])
                        elif d.get("type") == "input_json_delta" and ev["index"] in calls:
                            calls[ev["index"]]["args"] += d.get("partial_json", "")
                    elif t == "message_stop":
                        finished = True
                    elif t == "error":
                        raise BridgeError(str((ev.get("error") or {}).get("message", ev)), "upstream", 502)
                else:
                    if ev.get("error"):
                        raise BridgeError(str(ev["error"])[:240], "upstream", 502)
                    for ch in ev.get("choices") or []:
                        if ch.get("finish_reason"):
                            finished = True
                        d = ch.get("delta") or {}
                        if d.get("content"):
                            text.append(d["content"])
                            emit(d["content"])
                        for tc in d.get("tool_calls") or []:
                            c = calls.setdefault(tc.get("index", 0), {"id": "", "name": "", "args": ""})
                            c["id"] = tc.get("id") or c["id"]
                            fn = tc.get("function") or {}
                            c["name"] = fn.get("name") or c["name"]
                            c["args"] += fn.get("arguments") or ""
        if not finished and not cancel.is_set():
            raise BridgeError("the API stream ended without a terminal event (connection cut?)", "stream_interrupted", 502)
        out_calls = []
        for _, c in sorted(calls.items(), key=lambda x: x[0]):
            try:
                inp = json.loads(c["args"] or "{}")
            except Exception:
                inp = loose_json(c["args"]) if c["args"] else {}
            out_calls.append({"id": c["id"] or "toolu_" + uuid.uuid4().hex[:22], "name": c["name"], "input": inp})
        full = "".join(text)
        res = Outcome(full, out_calls, full)
        if declared:
            res.identity = {"state": "revealed_in_response", "value": declared, "confidence": "observed", "source": "provider response field"}
        return res


# ============================================================================
# Model catalog, capability registry, site profile, change detection   (ledger A1/A2 part, B1-B9)
# No model names live in this file. Every entry below is filled at runtime from observed evidence.
# ============================================================================
CATALOG_SCHEMA = 1
PROFILE_SCHEMA = 1
CAP_KEYS = ("text", "streaming", "system_prompt", "native_tools", "emulated_tools", "image_input", "file_input",
            "structured_output", "thinking", "server_continuity", "stop_sequences", "usage_reporting", "cancellation")
CAP_VALUES = ("supported", "unsupported", "unknown")
V_STATUS = ("unknown", "discovering", "available", "degraded", "unavailable", "stale", "requires_auth")
V_CONF = ("verified", "observed", "inferred", "unknown")


def norm_caps(d: Any) -> Dict[str, str]:
    """Tri-state capabilities. Anything missing or invalid is 'unknown' - never silently 'supported'."""
    out = {k: "unknown" for k in CAP_KEYS}
    if isinstance(d, dict):
        for k, v in d.items():
            if k in out and v in CAP_VALUES:
                out[k] = v
    return out


def make_variant_id(native_id: str = "", display: str = "", mode: str = "default") -> str:
    """Stable id: derived from the observed native id when there is one, otherwise from the observed label.
    A later change of the display text therefore never changes the id of a variant that has a native id."""
    base = native_id.strip() or ("ui:" + display.strip())
    s = re.sub(r"[^a-z0-9._:@-]+", "-", base.lower()).strip("-")[:80]
    if not s or s == "ui:":
        raise ValueError("a model variant needs a native id or a display label")
    return s if mode in ("", "default") else f"{s}@{re.sub(r'[^a-z0-9._-]+', '-', mode.lower())[:24]}"


@dataclass
class ModelVariant:
    id: str
    display: str = ""
    native_id: str = ""              # provider-native identifier, ONLY when it was really observed
    mode: str = "default"
    capabilities: Dict[str, str] = field(default_factory=dict)
    source: str = "unknown"          # api_endpoint | site_network | site_ui | ai_validated | manual
    discovered_at: float = 0.0
    verified_at: float = 0.0
    status: str = "unknown"
    confidence: str = "unknown"
    constraints: List[str] = field(default_factory=list)
    failures: List[Dict[str, Any]] = field(default_factory=list)
    latency: Dict[str, Any] = field(default_factory=dict)
    extra: Dict[str, Any] = field(default_factory=dict)          # unknown fields from newer/older files are preserved

    def validate(self) -> Optional[str]:
        if not self.id or not isinstance(self.id, str):
            return "variant id missing"
        if self.status not in V_STATUS:
            return f"bad status '{self.status}'"
        if self.confidence not in V_CONF:
            return f"bad confidence '{self.confidence}'"
        if isinstance(self.capabilities, dict) and any(k not in CAP_KEYS or v not in CAP_VALUES for k, v in self.capabilities.items()):
            return "bad capability entry"
        return None

    def to_dict(self) -> Dict[str, Any]:
        d = dataclasses.asdict(self)
        extra = d.pop("extra") or {}
        d["capabilities"] = norm_caps(self.capabilities)
        return {**extra, **d}

    @staticmethod
    def from_dict(d: Dict[str, Any]) -> "ModelVariant":
        known = {f.name for f in dataclasses.fields(ModelVariant)} - {"extra"}
        kw = {k: v for k, v in d.items() if k in known}
        v = ModelVariant(**kw)
        v.extra = {k: val for k, val in d.items() if k not in known and k != "extra"}
        v.capabilities = norm_caps(v.capabilities)
        return v


def new_catalog(aid: str) -> Dict[str, Any]:
    return {"schema": CATALOG_SCHEMA, "account_id": aid, "variants": [], "status": "unknown", "stale_reason": "",
            "refreshed_at": 0.0, "last_attempt_at": 0.0, "last_error": "", "sources_tried": [], "events": []}


def caps_from_listing(item: Any) -> Dict[str, str]:
    """Capabilities a listing really states (documented shapes only); everything else stays unknown."""
    caps: Dict[str, str] = {}
    if not isinstance(item, dict):
        return caps
    sp = item.get("supported_parameters")
    if isinstance(sp, list):
        caps["native_tools"] = "supported" if "tools" in sp else "unsupported"
        caps["structured_output"] = "supported" if ("response_format" in sp or "structured_outputs" in sp) else "unsupported"
    mods = ((item.get("architecture") or {}).get("input_modalities") if isinstance(item.get("architecture"), dict) else None) or item.get("input_modalities")
    if isinstance(mods, list):
        caps["image_input"] = "supported" if "image" in mods else "unsupported"
        caps["file_input"] = "supported" if "file" in mods else "unsupported"
    return caps


def variants_from_items(items: List[Any], source: str, confidence: str, id_path: str = "id", label_path: str = "",
                        ts: Optional[float] = None) -> List[ModelVariant]:
    ts = now() if ts is None else ts
    seen: Dict[str, ModelVariant] = {}
    for it in items:
        if isinstance(it, str):
            nid, label = it, it
        elif isinstance(it, dict):
            ids = get_by_norm(it, id_path)
            nid = str(ids[0]) if ids and isinstance(ids[0], (str, int)) else ""
            labs = get_by_norm(it, label_path) if label_path else []
            label = str(labs[0]) if labs else (str(it.get("display_name") or it.get("name") or nid))
        else:
            continue
        if not nid.strip():
            continue
        vid = make_variant_id(nid, label)
        if vid in seen:
            continue
        seen[vid] = ModelVariant(id=vid, display=label, native_id=nid, capabilities=norm_caps(caps_from_listing(it)), source=source,
                                 discovered_at=ts, verified_at=ts, status="available", confidence=confidence)
    return list(seen.values())


def discover_api_models(acct: Dict[str, Any], key: str, allow_private: bool = False) -> List[ModelVariant]:
    """Source 1: the provider's documented model-list endpoint (API accounts)."""
    base = str(acct["api_base"]).rstrip("/")
    if acct.get("api_kind") == "anthropic":
        url = base + ("/models" if base.endswith("/v1") else "/v1/models")
        hdr = {"x-api-key": key, "anthropic-version": "2023-06-01"}
    else:
        url = base + ("/models" if re.search(r"/v\d+$", base) else "/v1/models")
        hdr = {"authorization": "Bearer " + key}
    url_guard(url, allow_private)
    st, rh, it = DirectTransport({"cookies": [], "ua": "ai-web-bridge"}).request("GET", url, hdr, None, 20)
    raw = _read_all(it, 2_000_000)
    if st in (401, 403):
        raise AuthError(f"model list endpoint refused the key (HTTP {st})")
    if st >= 400:
        raise BridgeError(f"model list endpoint returned HTTP {st}", "upstream", 502)
    try:
        data = json.loads(raw)
    except Exception:
        raise BridgeError("model list endpoint did not return JSON", "upstream", 502)
    items = data.get("data") if isinstance(data, dict) else data
    if not isinstance(items, list):
        raise BridgeError("model list endpoint returned an unexpected shape", "upstream", 502)
    return variants_from_items(items, "api_endpoint", "verified", "id")


def discover_site_endpoint(recipe: Dict[str, Any], session: Dict[str, Any], transport: Any = None, allow_private: bool = False) -> List[ModelVariant]:
    """Source 2: a model/config call recorded in the recipe (`models_call`) and replayed at the direct tier - no browser."""
    mc = recipe.get("models_call")
    if not isinstance(mc, dict):
        raise BridgeError("this site has no recorded model-list call", "setup", 404)
    url_guard(str(mc["url"]), allow_private)
    rc = RecipeClient(recipe, transport or DirectTransport(session), session)
    ctx: Dict[str, Any] = {"conv": {}, "state": {}, "turn": 0, "prompt": ""}
    st, rh, it = rc.t.request(mc.get("method", "GET"), str(mc["url"]), rc._headers(mc.get("headers") or {}, ctx, mc["url"]), rc._body(mc, ctx), 30)
    rc._check_status(st, rh, it)
    raw = _read_all(it, 2_000_000)
    try:
        data = json.loads(raw)
    except Exception:
        raise BridgeError(f"model-list call did not return JSON (looks like: {raw[:80]!r})", "empty", 502)
    items = get_by_norm_items(data, mc["list_path"])
    if not items:
        raise BridgeError(f"model-list call returned nothing at '{mc['list_path']}' (site format changed?)", "empty", 502)
    return variants_from_items(items, "site_network", "observed", mc.get("id_path", "id"), mc.get("label_path", ""))


def get_by_norm_items(obj: Any, npath: str) -> List[Any]:
    """Elements addressed by a path that ends in '*' (list items, which may be dicts or strings)."""
    base = npath[:-2] if npath.endswith(".*") else npath
    cur: List[Any] = [obj]
    for seg in [s for s in base.split(".") if s]:
        nxt: List[Any] = []
        for c in cur:
            if isinstance(c, dict) and seg in c:
                nxt.append(c[seg])
            elif isinstance(c, list) and seg == "*":
                nxt.extend(c)
        cur = nxt
    out: List[Any] = []
    for c in cur:
        out.extend(c if isinstance(c, list) else [c])
    return out


def find_models_call(caps: List[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """Learning side: look in captured traffic for a JSON response that lists selectable models. Returns a `models_call`
    spec (never guessed: it must be a real captured GET with a JSON list of id-bearing objects) or None."""
    for c in caps:
        if str(c.get("method", "GET")).upper() != "GET" or not (200 <= int(c.get("status") or 0) < 300):
            continue
        path = urllib.parse.urlparse(c.get("url", "")).path.lower()
        if not re.search(r"model|config|setting|bootstrap|capabilit", path):
            continue
        data = _json_or_none(c.get("resp_body"))
        if data is None:
            continue
        for lp, v in _lists_of_objects(data):
            idk = next((k for k in ("id", "slug", "model", "name") if all(isinstance(o.get(k), str) for o in v)), "")
            if idk and len(v) >= 1:
                labk = next((k for k in ("display_name", "label", "title", "name") if k != idk and all(isinstance(o.get(k), str) for o in v)), "")
                return {"url": c["url"], "method": "GET", "headers": {k: val for k, val in (c.get("headers") or {}).items()
                                                                     if k not in SKIP_HEADERS and not k.startswith((":", "sec-")) and _benign_header(k, val)},
                        "list_path": lp + ".*" if lp else "*", "id_path": idk, "label_path": labk, "observed_at": now()}
    return None


def derive_model_select(cap_a: Dict[str, Any], cap_b: Dict[str, Any], native_a: str, native_b: str) -> Optional[Dict[str, Any]]:
    """B4 learning: two chat requests captured with two different model selections. The place where A's id became B's id,
    and nothing else changed to those values, is the selection slot. Ambiguous or not found -> None (never guessed)."""
    va, vb = _view(cap_a), _view(cap_b)
    hits = [k for k, val in va.items() if val == native_a and vb.get(k) == native_b]
    if len(hits) != 1:
        return None
    k = hits[0]
    where = {"body": "body." + norm_path(k[1:]), "hdr": "header." + str(k[-1]), "url": "url." + "/".join(str(x) for x in k[1:])}[k[0]]
    return {"kind": "template", "slot": list(k), "where": where, "default": native_a}


def apply_model_select(recipe: Dict[str, Any], spec: Dict[str, Any]) -> Dict[str, Any]:
    """Rewrite the recipe's chat request so the slot holds {{model}}, and record the mechanism. Returns a new recipe."""
    r = json.loads(json.dumps(recipe))
    slot, chat = tuple(spec["slot"]), r["chat"]
    if slot[0] == "body":
        set_path(chat["body"], tuple(slot[1:]), "{{model}}")
    elif slot[0] == "hdr":
        chat["headers"][slot[1]] = "{{model}}"
    elif slot[0] == "url" and slot[1] == "seg":
        u = urllib.parse.urlparse(chat["url"])
        segs = u.path.split("/")
        if int(slot[2]) >= len(segs):
            raise ValueError("the recipe's chat URL does not have the path segment where the model id was observed")
        segs[int(slot[2])] = "{{model}}"
        chat["url"] = urllib.parse.urlunparse(u._replace(path="/".join(segs))).replace("%7B%7Bmodel%7D%7D", "{{model}}")
    elif slot[0] == "url" and slot[1] == "q":
        chat["url"] = re.sub(r"([?&]" + re.escape(str(slot[2])) + r"=)[^&]*", r"\g<1>{{model}}", chat["url"])
    else:
        raise ValueError(f"unsupported slot {slot!r}")
    r["model_select"] = {"kind": "template", "where": spec["where"], "slot": list(slot), "default": spec.get("default", "")}
    return r


_SECRETISH_NAME = re.compile(r"auth|token|key|secret|session|csrf|xsrf|cookie|bearer|signature|sign$|jwt|credential", re.I)


def _benign_header(name: str, value: Any) -> bool:
    """A recorded model-list call keeps only headers that cannot be credentials (the recipe's own auth mechanism adds real ones)."""
    v = str(value)
    return not _SECRETISH_NAME.search(name) and not (len(v) >= 32 and " " not in v)


def _lists_of_objects(o: Any, path: str = "") -> Iterator[Tuple[str, List[Dict[str, Any]]]]:
    if isinstance(o, list) and o and all(isinstance(x, dict) for x in o):
        yield path, o
    if isinstance(o, dict):
        for k, v in o.items():
            yield from _lists_of_objects(v, f"{path}.{k}" if path else str(k))


# ---- Source 3: the model selector as rendered in the UI ------------------------------------------------------------
UI_MODELS_JS = r"""() => {
  const out = {labels: [], evidence: ''};
  const trig = Array.from(document.querySelectorAll('button,[role=button],[role=combobox]')).filter(e => {
    const t = ((e.getAttribute('aria-label') || '') + ' ' + (e.getAttribute('title') || '') + ' ' + (e.getAttribute('data-testid') || '')).toLowerCase();
    return /model|\u6a21\u578b|\u0645\u062f\u0644|modell|modelo|\u043c\u043e\u0434\u0435\u043b/.test(t) || e.getAttribute('aria-haspopup') === 'listbox';
  });
  if (!trig.length) { out.evidence = (document.body.innerText || '').slice(0, 6000); return out; }
  trig[0].click();
  return new Promise(res => setTimeout(() => {
    const opts = Array.from(document.querySelectorAll('[role=option],[role=menuitemradio],[role=menuitem],[role=listbox] li'));
    out.labels = opts.map(o => (o.innerText || '').split('\n')[0].trim()).filter(x => x && x.length < 80);
    out.evidence = opts.map(o => (o.innerText || '').trim()).join('\n').slice(0, 6000);
    document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape'}));
    res(out);
  }, 700));
}"""


def read_ui_models(page: Any) -> Tuple[List[str], str]:
    """Open the page's model picker (if there is one), read its entries, close it. Read-only; no message is sent."""
    data = page.evaluate(UI_MODELS_JS) or {}
    labels, seen = [], set()
    for l in data.get("labels") or []:
        l = re.sub(r"\s+", " ", str(l)).strip()
        if 1 < len(l) < 80 and l.lower() not in seen:
            seen.add(l.lower())
            labels.append(l)
    return labels, str(data.get("evidence") or "")


def variants_from_labels(labels: List[str], evidence: str, selectable: bool = False, source: str = "site_ui") -> List[ModelVariant]:
    ts = now()
    out = []
    for l in labels:
        if _evid_norm(l) not in _evid_norm(evidence):
            continue                                              # a label that is not in the evidence is not a catalog entry
        out.append(ModelVariant(id=make_variant_id("", l), display=l, native_id="", source=source, discovered_at=ts, verified_at=ts,
                                status="available" if selectable else "unknown", confidence="observed",
                                constraints=[] if selectable else ["selection mechanism not learned yet: listed in the UI, cannot be chosen by the bridge"]))
    return out


def _evid_norm(s: str) -> str:
    return re.sub(r"\s+", " ", str(s)).strip().lower()


# ---- B3: AI proposes, evidence disposes -----------------------------------------------------------------------------
def catalog_proposal_prompt(evidence: str) -> str:
    return ("Below is captured evidence from a chat website (page text / network JSON; secrets are masked). List the model or mode choices "
            "the user can pick on this site. Reply with ONLY this JSON: {\"models\":[{\"label\":\"<text exactly as shown>\","
            "\"native_id\":\"<id exactly as it appears in the evidence, or empty>\",\"mode\":\"default\"}]}. Use only what is literally "
            "present in the evidence. If nothing is present reply {\"models\":[]}.\n\nEVIDENCE:\n" + evidence[:12000])


def validate_proposal(proposal: Any, evidence: str, selectable: bool = False) -> Tuple[List[ModelVariant], List[Dict[str, Any]]]:
    """Keep only entries whose label (and native id, if given) literally appear in the evidence. Returns (kept, dropped)."""
    ev, kept, dropped, ts = _evid_norm(evidence), [], [], now()
    items = proposal.get("models") if isinstance(proposal, dict) else None
    for e in items if isinstance(items, list) else []:
        if not isinstance(e, dict):
            continue
        label, nid = str(e.get("label") or "").strip(), str(e.get("native_id") or "").strip()
        if not (2 <= len(label) <= 80) or _evid_norm(label) not in ev:
            dropped.append({"entry": e, "why": "label not found in evidence"})
            continue
        if nid and _evid_norm(nid) not in ev:
            nid = ""                                              # an invented id is discarded, the label alone may still be real
        mode = re.sub(r"[^a-z0-9_-]+", "", str(e.get("mode") or "default").lower())[:24] or "default"
        kept.append(ModelVariant(id=make_variant_id(nid, label, mode), display=label, native_id=nid, mode=mode, source="ai_validated",
                                 discovered_at=ts, verified_at=ts, status="available" if selectable else "unknown", confidence="inferred",
                                 constraints=["proposed by the connected model; label confirmed in captured evidence"]))
    return kept, dropped


def ai_discover(ask: Callable[[str], str], evidence: str, selectable: bool = False) -> Tuple[List[ModelVariant], List[Dict[str, Any]]]:
    return validate_proposal(extract_json_object(ask(catalog_proposal_prompt(evidence))), evidence, selectable)


# ---- catalog merge / change events ---------------------------------------------------------------------------------
def merge_catalog(cat: Dict[str, Any], found: List[ModelVariant], source: str) -> List[Dict[str, Any]]:
    """Fold a successful discovery into the stored catalog. Returns the change events (also appended to cat['events'])."""
    ts, events = now(), []
    old = {v["id"]: ModelVariant.from_dict(v) for v in cat.get("variants", [])}
    new_ids = set()
    for nv in found:
        new_ids.add(nv.id)
        ov = old.get(nv.id)
        if ov is None:
            old[nv.id] = nv
            events.append({"t": ts, "type": "added", "id": nv.id, "display": nv.display})
            continue
        if ov.display != nv.display and nv.display:
            events.append({"t": ts, "type": "renamed", "id": nv.id, "from": ov.display, "to": nv.display})
            ov.display = nv.display
        for k, val in norm_caps(nv.capabilities).items():
            cur = ov.capabilities.get(k, "unknown")
            if val == "unknown" or cur == val:                          # unknown never erases a known fact
                continue
            events.append({"t": ts, "type": "capability_changed" if cur != "unknown" else "capability_appeared", "id": nv.id,
                           "cap": k, "from": cur, "to": val})
            ov.capabilities[k] = val
        if ov.status in ("unavailable", "stale", "unknown", "requires_auth", "discovering"):
            if ov.status == "unavailable":
                events.append({"t": ts, "type": "reappeared", "id": nv.id})
            ov.status = nv.status
        ov.verified_at, ov.source, ov.confidence = ts, source, nv.confidence
    for vid, ov in old.items():
        if vid not in new_ids and ov.status != "unavailable":
            ov.status = "unavailable"
            ov.constraints = [c for c in ov.constraints if not c.startswith("no longer listed")] + [f"no longer listed by the site as of {time.strftime('%Y-%m-%d %H:%M', time.localtime(ts))}"]
            events.append({"t": ts, "type": "removed", "id": vid, "display": ov.display})
    cat["variants"] = [v.to_dict() for v in old.values()]
    cat.update({"status": "fresh", "stale_reason": "", "refreshed_at": ts, "last_attempt_at": ts, "last_error": ""})
    if source not in cat["sources_tried"]:
        cat["sources_tried"].append(source)
    cat["events"] = (cat.get("events", []) + events)[-60:]
    return events


def mark_catalog_stale(cat: Dict[str, Any], reason: str, auth: bool = False) -> None:
    """A failed refresh never erases the last good snapshot - it only labels it."""
    ts = now()
    cat["status"], cat["stale_reason"], cat["last_error"], cat["last_attempt_at"] = ("requires_auth" if auth else "stale"), reason[:300], reason[:300], ts
    for v in cat.get("variants", []):
        if v.get("status") in ("available", "degraded", "unknown", "discovering"):
            v.setdefault("prev_status", v["status"])
            v["status"] = "requires_auth" if auth else "stale"


# ---- B5: capability-based eligibility ----------------------------------------------------------------------------
def variant_eligible(v: Dict[str, Any], required: Tuple[str, ...] = (), unknown_ok: bool = True) -> Tuple[bool, List[str]]:
    """(eligible, flagged). A required capability that is 'unsupported' excludes the variant; 'unknown' is allowed-but-flagged
    by default (policy may forbid it) and is never reported as verified."""
    caps, flagged = norm_caps(v.get("capabilities")), []
    for c in required:
        if caps.get(c, "unknown") == "unsupported":
            return False, []
        if caps.get(c, "unknown") == "unknown":
            if not unknown_ok:
                return False, []
            flagged.append(c)
    return True, flagged


# ---- O14: model choice after discovery ------------------------------------------------------------------------------
# The owner chooses, per account, which DISCOVERED model/mode the bridge asks the site for. Three modes (data, validated):
#   default  the site's own default; the bridge selects nothing
#   fixed    one variant, remembered by id AND by the native id that was observed when it was chosen (A2)
#   policy   an ordered preference list and/or required capabilities, optionally falling back to the lowest measured latency
# The selector exists only when the site really offers >= 2 variants the bridge can drive; one model (or no selection
# mechanism) means "absent", never a faked choice. A fixed choice that can no longer be resolved is reported as
# `unresolved` and the account is not used for `acct:<id>` routes - another model is never substituted silently.
O14_MODES = ("default", "fixed", "policy")
O14_MAX_PREFER = 20


def o14_selectable(a: Dict[str, Any], variant: Dict[str, Any], recipe: Optional[Dict[str, Any]]) -> bool:
    """Can the bridge actually choose this variant on this account? (a real native id AND a learned/API selection mechanism)"""
    sel = (recipe or {}).get("model_select") or {}
    val = variant.get("native_id") or (variant.get("display") if sel.get("kind") == "ui" else "")
    return bool(val) and (a.get("type") == "api" or bool(sel))


def o14_options(a: Dict[str, Any], cat: Dict[str, Any], recipe: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Variants the owner may pick: discovered, not marked unavailable, and drivable. Order = catalog order."""
    out = []
    for v in cat.get("variants", []) or []:
        if isinstance(v, dict) and v.get("id") and v.get("status") != "unavailable" and o14_selectable(a, v, recipe):
            out.append(v)
    return out


def o14_selector(a: Dict[str, Any], cat: Dict[str, Any], recipe: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """What the card may show. `present` is False when the site offers fewer than two selectable variants (the selector is absent, not faked)."""
    opts = o14_options(a, cat, recipe)
    total = [v for v in cat.get("variants", []) or [] if isinstance(v, dict) and v.get("id") and v.get("status") != "unavailable"]
    if len(opts) >= 2:
        why = ""
    elif len(opts) == 1:
        why = "the site offers one selectable model; there is nothing to choose"
    elif total:
        why = "models were discovered but the bridge has no way to select them on this site (no native id or no learned selection mechanism)"
    else:
        why = "no models were discovered for this account yet"
    return {"present": len(opts) >= 2, "reason": why, "count": len(opts), "discovered": len(total),
            "options": [{"id": v["id"], "display": v.get("display") or v.get("native_id") or v["id"], "native_id": v.get("native_id") or None,
                         "mode": v.get("mode", "default"), "status": v.get("status"), "confidence": v.get("confidence"),
                         "capabilities": norm_caps(v.get("capabilities"))} for v in opts] if len(opts) >= 2 else []}


def o14_validate(data: Any, cat: Dict[str, Any], a: Dict[str, Any], recipe: Optional[Dict[str, Any]]) -> Tuple[Optional[Dict[str, Any]], str]:
    """-> (clean choice, error). Every id must be a variant the bridge can really select now. Unknown keys are dropped, sizes are bounded."""
    if not isinstance(data, dict):
        return None, "the choice must be a JSON object"
    mode = str(data.get("mode") or "")
    if mode not in O14_MODES:
        return None, f"mode must be one of {', '.join(O14_MODES)}"
    if mode == "default":
        return {"mode": "default"}, ""
    sel = o14_selector(a, cat, recipe)
    if not sel["present"]:
        return None, "this account has no model selector: " + sel["reason"]
    by_id = {v["id"]: v for v in o14_options(a, cat, recipe)}
    if mode == "fixed":
        vid = str(data.get("variant") or "")
        v = by_id.get(vid)
        if v is None:
            return None, f"'{vid}' is not a selectable model of this account (GET /api/accounts/<id>/model-choice lists them)"
        return {"mode": "fixed", "variant": v["id"], "native_id": v.get("native_id") or "", "display": v.get("display") or "", "variant_mode": v.get("mode", "default")}, ""
    prefer = data.get("prefer") or []
    require = data.get("require") or []
    if not isinstance(prefer, list) or not isinstance(require, list) or len(prefer) > O14_MAX_PREFER or len(require) > len(CAP_KEYS):
        return None, "prefer/require must be short lists"
    bad = [p for p in prefer if str(p) not in by_id]
    if bad:
        return None, f"not selectable models of this account: {', '.join(str(b)[:60] for b in bad[:3])}"
    badc = [c for c in require if c not in CAP_KEYS]
    if badc:
        return None, f"unknown capability: {str(badc[0])[:40]}"
    fb = str(data.get("fallback") or "latency")
    if fb not in ("latency", "none"):
        return None, "fallback must be 'latency' or 'none'"
    if not prefer and not require:
        return None, "a policy choice needs a prefer list or required capabilities"
    return {"mode": "policy", "prefer": [str(p) for p in dict.fromkeys(prefer)], "require": list(dict.fromkeys(require)), "fallback": fb,
            "native_ids": {p: by_id[str(p)].get("native_id") or "" for p in prefer}}, ""


def o14_resolve(choice: Optional[Dict[str, Any]], a: Dict[str, Any], cat: Dict[str, Any], recipe: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """Turn the stored choice into a variant of the CURRENT catalog. -> {status: default|ok|unresolved, variant, how, reason, flags}.
    fixed: by id; else by the native id observed at choice time (same mode) = a re-resolution after a repair/rename (A2); else unresolved.
    A display label is used only on a site whose selection mechanism is the UI and only when it is unique (weaker, flagged)."""
    ch = choice if isinstance(choice, dict) else {}
    mode = ch.get("mode") or "default"
    if mode == "default":
        return {"status": "default", "variant": None, "how": "default", "reason": "", "flags": []}
    opts = o14_options(a, cat, recipe)
    if mode == "fixed":
        vid, nid, disp, vmode = ch.get("variant", ""), ch.get("native_id") or "", ch.get("display") or "", ch.get("variant_mode") or "default"
        v = next((x for x in opts if x["id"] == vid), None)
        if v is not None and (not nid or not v.get("native_id") or v.get("native_id") == nid):
            return {"status": "ok", "variant": v, "how": "id", "reason": "", "flags": []}
        if nid:
            hits = [x for x in opts if x.get("native_id") == nid and (x.get("mode") or "default") == vmode]
            if len(hits) == 1:
                return {"status": "ok", "variant": hits[0], "how": "native_id", "reason": f"re-resolved by native id '{nid}' (id changed from '{vid}' to '{hits[0]['id']}')", "flags": []}
        kind = ((recipe or {}).get("model_select") or {}).get("kind")
        if not nid and disp and kind == "ui":
            hits = [x for x in opts if (x.get("display") or "") == disp]
            if len(hits) == 1:
                return {"status": "ok", "variant": hits[0], "how": "display", "reason": "re-resolved by display label (weaker: the site gave no native id)", "flags": ["display_match"]}
        return {"status": "unresolved", "variant": None, "how": "none", "flags": [],
                "reason": f"the chosen model '{disp or vid}'" + (f" (native id {nid})" if nid else "") + " is no longer offered by the site or can no longer be selected; nothing else was substituted"}
    # policy
    req = list(ch.get("require") or [])
    by_id = {x["id"]: x for x in opts}

    def fits(v: Dict[str, Any]) -> Tuple[bool, List[str]]:
        return variant_eligible(v, tuple(req), unknown_ok=True)
    for p in ch.get("prefer") or []:
        v = by_id.get(p)
        if v is None:                                                   # the preferred id may have been renamed: try its remembered native id
            nid = (ch.get("native_ids") or {}).get(p) or ""
            v = next((x for x in opts if nid and x.get("native_id") == nid), None)
        if v is not None:
            okv, flagged = fits(v)
            if okv:
                return {"status": "ok", "variant": v, "how": "policy:prefer", "reason": "", "flags": [f"{c} support unknown" for c in flagged]}
    if ch.get("fallback", "latency") == "latency":
        pool = [(v, fits(v)) for v in opts]
        pool = [(v, f) for v, (okv, f) in pool if okv]
        if pool:
            def lat(item: Tuple[Dict[str, Any], List[str]]) -> float:
                l = item[0].get("latency") or {}
                return float(l.get("ema_ms") or 0) if int(l.get("samples") or 0) > 0 else float("inf")
            best = min(pool, key=lat)                                    # min is stable: unmeasured variants keep catalog order
            how = "policy:latency" if lat(best) != float("inf") else "policy:first"
            return {"status": "ok", "variant": best[0], "how": how, "reason": "", "flags": [f"{c} support unknown" for c in best[1]]}
    return {"status": "unresolved", "variant": None, "how": "none", "flags": [],
            "reason": "no discovered model satisfies the owner's policy (preferred models are gone or lack a required capability); nothing else was substituted"}


# ---- B8: per-site behaviour profile -----------------------------------------------------------------------------
@dataclass
class SiteProfile:
    host: str
    schema: int = PROFILE_SCHEMA
    version: int = 1
    status: str = "unverified"          # unverified | ok | degraded | stale
    status_reason: str = ""
    confidence: str = "unknown"
    last_verified_at: float = 0.0
    recipe_version: Any = None
    auth: Dict[str, Any] = field(default_factory=lambda: {"mechanism": "unknown", "expiry_signals": []})
    submit: Dict[str, Any] = field(default_factory=lambda: {"tier": "unknown", "mode": "unknown"})
    stream_format: str = "unknown"
    continuity: str = "unknown"
    long_paste: Dict[str, Any] = field(default_factory=lambda: {"converts_to_attachment": "unknown", "limit_chars": None})
    rate_limit_shapes: List[str] = field(default_factory=list)
    error_map: List[Dict[str, Any]] = field(default_factory=list)     # D1: this site's error shapes -> taxonomy categories (data, validated)
    model_selection: Dict[str, Any] = field(default_factory=lambda: {"mechanism": "unknown"})
    known_failures: List[Dict[str, Any]] = field(default_factory=list)
    extra: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        d = dataclasses.asdict(self)
        extra = d.pop("extra") or {}
        return {**extra, **d}

    @staticmethod
    def from_dict(d: Dict[str, Any]) -> "SiteProfile":
        known = {f.name for f in dataclasses.fields(SiteProfile)} - {"extra"}
        p = SiteProfile(**{k: v for k, v in d.items() if k in known})
        p.extra = {k: v for k, v in d.items() if k not in known and k != "extra"}
        return p


def profile_from_recipe(recipe: Dict[str, Any], old: Optional[SiteProfile] = None) -> SiteProfile:
    p = old or SiteProfile(host=str(recipe.get("host", "")))
    ms = recipe.get("model_select") or {}
    p.submit = {"tier": recipe.get("tier", "unknown"), "mode": "recipe" if recipe.get("chat") else "unknown"}
    p.stream_format = (recipe.get("stream") or {}).get("format", "unknown")
    p.continuity = str(recipe.get("continuity", "unknown"))
    p.auth = {"mechanism": "header" if recipe.get("auth") else "cookie", "expiry_signals": ["HTTP 401/403", "login page with HTTP 200"]}
    p.model_selection = {"mechanism": ms.get("kind", "unknown"), **({"detail": ms.get("where") or ms.get("path") or ""} if ms else {})}
    p.recipe_version, p.confidence = recipe.get("version"), "observed"
    return p


NON_ANSWER_RULES = (
    (re.compile(r"challenge|captcha|just a moment|cloudflare", re.I), "challenge_page", "bot-protection challenge page instead of an answer"),
    (re.compile(r"sign.?in|log.?in|\u767b\u5f55|\u0648\u0631\u0648\u062f|<form[^>]*password|name=[\"']?password", re.I), "login_page", "a login page was returned with HTTP 200"),
    (re.compile(r"stream format changed", re.I), "stream_format_changed", "the stream format is no longer the one that was learned"),
    (re.compile(r"^\s*<(!doctype|html)", re.I), "html_instead_of_stream", "HTML was returned instead of the learned stream"),
)


def classify_non_answer(snippet: str) -> Tuple[str, str]:
    """A 200 status is never proof of an answer: name what a non-answer looks like (or 'unknown')."""
    s = snippet or ""
    body = s.split(": ", 1)[1] if s.startswith("empty answer from site: ") else s
    for rx, code, why in NON_ANSWER_RULES:
        if rx.search(body[:600]) or (code == "stream_format_changed" and rx.search(s)):
            return code, why
    return "unknown", "an empty or unparseable answer"


