def port_in_use(port: int) -> bool:
    with socket.socket() as s:
        s.settimeout(0.4)
        return s.connect_ex(("127.0.0.1", port)) == 0


def running_bridge(port: int) -> bool:
    try:
        c = http.client.HTTPConnection("127.0.0.1", port, timeout=2)
        c.request("GET", "/health")
        return json.loads(c.getresponse().read()).get("ok") is True
    except Exception:
        return False


def print_banner(cfg: Config, port: int) -> None:
    k = cfg["keys"][0]["key"]
    print(textwrap.dedent(f"""
        ┌─ AI Web Bridge {VERSION} ─────────────────────────────────────────────
        │ Dashboard : http://127.0.0.1:{port}/#k={cfg['admin_key']}
        │ API base  : http://127.0.0.1:{port}        (OpenAI-style: http://127.0.0.1:{port}/v1)
        │ API key   : {k}
        │ Claude Code (PowerShell):
        │   $env:ANTHROPIC_BASE_URL="http://127.0.0.1:{port}"; $env:ANTHROPIC_API_KEY="{k}"; claude
        │ Keep this window open. Closing it stops the bridge (Claude Code may come and go).
        └──────────────────────────────────────────────────────────────────────
    """), flush=True)


class QuietServer(ThreadingHTTPServer):
    """ThreadingHTTPServer that does not print a traceback when a client simply hangs up (WinError 10053/10054, broken pipe)."""
    def handle_error(self, request: Any, client_address: Any) -> None:
        et = sys.exc_info()[0]
        if et is not None and issubclass(et, (ConnectionError, TimeoutError)):
            return
        super().handle_error(request, client_address)


def serve(app: App, port: int) -> ThreadingHTTPServer:
    Handler.app = app
    srv = QuietServer(("127.0.0.1", port), Handler)
    srv.daemon_threads = True
    threading.Thread(target=srv.serve_forever, daemon=True, name="http").start()
    return srv


def run_folder_command(args: Any) -> int:
    """O10: --doctor / --export-bundle / --import-bundle. These never start the server and never send a model request."""
    import getpass
    pw = os.environ.get("BRIDGE_BUNDLE_PASSPHRASE", "")
    try:
        if args.import_bundle:
            src = Path(args.import_bundle)
            if not pw and src.exists() and src.read_bytes()[:len(BUNDLE_MAGIC)] == BUNDLE_MAGIC:
                pw = getpass.getpass("bundle passphrase: ")
            r = import_bundle(src, HOME, pw)
            print(f"imported {r['files']} files into {r['path']}. Run `python bridge.py --doctor --home {r['path']}` to see which sessions still work on this machine.")
            return 0
        if args.export_bundle:
            if args.encrypt and not pw:
                pw = getpass.getpass("passphrase for the bundle: ")
            r = export_bundle(HOME, Path(args.export_bundle), pw if args.encrypt else "", include_profiles=not args.no_profiles)
            print(f"WARNING: {r['warning']}.\nwrote {r['files']} files to {r['path']} ({'encrypted' if r['encrypted'] else 'NOT encrypted'}).")
            return 0
        store = Store(HOME)                                       # --doctor
        cfg = Config(store)
        acc = Accounts(store, cfg)
        rep_ = acc.validate_sessions(apply=False)
        print(f"data folder: {HOME}")
        for n in rep_["folder"]["notes"]:
            print("  note:", n)
        for r in rep_["accounts"]:
            print(f"  [{r['status']}] {r['label']} ({r['host']}): {r['reason']}" + (f"  [confidence: {r['confidence']}]" if r["confidence"] else ""))
        if not rep_["accounts"]:
            print("  no browser accounts yet")
        print("  (nothing was changed; start the bridge normally to apply the result)")
        print("  unattended use: " + Autonomy.CLIENT_NOTE)
        return 0
    except BridgeError as e:
        print("error:", e)
        return 1


def main() -> int:
    ap = argparse.ArgumentParser(description="AI Web Bridge")
    ap.add_argument("--port", type=int)
    ap.add_argument("--home")
    ap.add_argument("--no-browser", action="store_true", help="do not open the dashboard automatically")
    ap.add_argument("--doctor", action="store_true", help="O10: check every stored session once (cheap, no model request) and print valid / expired / looks IP-device-bound / needs_login per account, then exit")
    ap.add_argument("--autonomous", action="store_true", help="O15: run unattended (auto-approve only what routing.json `autonomous_approve` allows, queue what needs a human, log every action)")
    ap.add_argument("--analyze", metavar="HOST", help="O22/O21/O23: re-run the offline site analysis from the stored captures of HOST and print where the report is (no browser, no network, no model request)")
    ap.add_argument("--export-bundle", metavar="FILE", help="O10: write the data folder as ONE file (it contains logged-in sessions: keep it private) and exit")
    ap.add_argument("--import-bundle", metavar="FILE", help="O10: unpack a bundle into an empty --home folder and exit")
    ap.add_argument("--encrypt", action="store_true", help="with --export-bundle: encrypt with a passphrase (needs the 'cryptography' package; BRIDGE_BUNDLE_PASSPHRASE or a prompt)")
    ap.add_argument("--no-profiles", action="store_true", help="with --export-bundle: leave out the browser profile directories (smaller; they are only portable between identical OS/browser builds)")
    ap.add_argument("--claude", nargs=argparse.REMAINDER, help="start the bridge and launch Claude Code (bridge keeps running after it exits)")
    ap.add_argument("--selftest", action="store_true", help="run the offline self-test suite (temporary data folder, no accounts needed) and exit")
    ap.add_argument("--pc-install", action="store_true", help="7.24: write the embedded Chrome extension into <data>/personal_chrome/extension, verify it and print the one-time install steps, then exit")
    ap.add_argument("--pc-pair", action="store_true", help="7.24: show a one-time pairing code for the extension (valid 10 minutes) and wait until it is paired")
    ap.add_argument("--pc-status", action="store_true", help="7.24: print the personal-Chrome status and which browser capabilities are / are not equivalent to the old Playwright browser, then exit")
    ap.add_argument("--quick", action="store_true", help="with --selftest: only a <10 s smoke check (start the server on a free port, one request through the mock site, shut down)")
    args = ap.parse_args()
    if args.selftest:
        return run_selftest(quick=args.quick)
    global HOME
    if args.home:
        HOME = Path(args.home)
    if args.pc_install or args.pc_pair or args.pc_status:
        return pc_cli(args)
    if args.analyze:
        try:
            st_ = Store(HOME)
            r_ = run_site_analysis(st_, Config(st_), args.analyze, args.analyze)
            print(json.dumps(r_, indent=2))
            print(f"report: {st_.path('analysis', safe_host_dir(args.analyze), 'report.md')}")
            return 0
        except BridgeError as e_:
            print("error:", e_)
            return 1
    if args.import_bundle or args.export_bundle or args.doctor:
        return run_folder_command(args)
    store = Store(HOME)
    cfg = Config(store)
    lf_ = log_file_open(store.path("logs"))
    log_install_hooks()
    log_install_extras()
    log_session_header(f"data folder: {store.home} | log file: {lf_ or 'DISABLED'}")
    log(f"program: {SCRIPT} | python: {sys.executable} | os: {sys.platform} | cwd: {os.getcwd()} | admin key and API keys are never written to this log", "info")
    port = args.port or int(os.environ.get("BRIDGE_PORT") or cfg["port"])
    url = f"http://127.0.0.1:{port}/#k={cfg['admin_key']}"
    if port_in_use(port):
        if running_bridge(port):
            print(f"AI Web Bridge is already running on port {port} - opening the dashboard.")
            if not args.no_browser:
                webbrowser.open(url)
            return 0
        print(f"Port {port} is used by another program. Start with --port <other>.")
        return 1
    cfg.set("port", port)
    if args.autonomous:
        cfg.set("autonomous", True)
    app = App(store, cfg)
    app.acc.start_health_loop()
    if cfg["o9_supervisor_seconds"]:
        app.acc.o9_supervisor().standby = app.engine.standby_tick                # type: ignore[attr-defined]
        app.acc.o9_supervisor().start(float(cfg["o9_supervisor_seconds"]))
    if cfg["validate_on_start"] and any(a.get("type") != "api" for a in app.acc.items):
        def _check_sessions() -> None:                          # O10: one cheap probe per account, in the background; only the invalid ones ask for a login
            try:
                rep_ = app.acc.validate_sessions()
                log("session check: " + ", ".join(f"{n} {k}" for k, n in rep_["counts"].items() if n) + "".join(f" | {n}" for n in rep_["folder"]["notes"]), "ok")
            except Exception as e:
                log(f"session check skipped: {type(e).__name__}", "warn")
        threading.Thread(target=_check_sessions, daemon=True, name="session-check").start()
    srv = serve(app, port)
    print_banner(cfg, port)
    log(f"data folder: {HOME}", "ok")
    log_heartbeat_start(app, float(os.environ.get("BRIDGE_HEARTBEAT_SECONDS") or 600))
    if pc_mode() == "personal_chrome":
        try:
            hub_ = pc_hub(HOME)
            if hub_.connected():
                log("personal Chrome: connected (browser steps use your own Chrome)", "ok")
            elif hub_.srv is None:
                log(hub_.not_ready_reason(), "warn")
            else:
                log("personal Chrome: not connected yet. " + pc_instructions(hub_) + " (browser steps wait for it; API-only accounts are not affected)", "warn")
        except Exception as e_:
            log(f"personal Chrome channel not started: {type(e_).__name__}: {e_}", "warn")
    if not any(a.get("state") == "ready" for a in app.acc.items):
        log("no ready accounts yet - add one in the dashboard", "warn")
    log("startup state:\n" + diag_report(app), "info")
    if cfg["auto_open_dashboard"] and not args.no_browser:
        webbrowser.open(url)
    if args.claude is not None:
        import shutil
        exe = shutil.which("claude")
        if not exe:
            log("`claude` was not found in PATH", "error")
        else:
            env = dict(os.environ, ANTHROPIC_BASE_URL=f"http://127.0.0.1:{port}", ANTHROPIC_API_KEY=cfg["keys"][0]["key"],
                       CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC="1")
            rc = subprocess.call([exe] + [a for a in args.claude if a != "--"], env=env)
            log(f"Claude Code exited ({rc}); the bridge keeps running. Press Ctrl+C or close this window to stop it.", "ok")
    try:
        while True:
            time.sleep(3600)
    except KeyboardInterrupt:
        print("bye")
        log("SESSION END: stopped by Ctrl+C", "info")
    srv.shutdown()
    app.acc.o9().close_all()
    for b in list(app.acc.browsers.values()):
        b.close()
    return 0


# ============================================================================
# Self-test suite (offline; temporary data folders; no accounts or network needed)
#   python bridge.py --selftest
# ============================================================================
def run_selftest(quick: bool = False) -> int:
    import shutil
    import tempfile
    import types
    import unittest
    import http.client as hc

    def mk_env(extra_cfg: Optional[Dict[str, Any]] = None) -> Tuple[Path, Store, Config, "App"]:
        tmp = Path(tempfile.mkdtemp(prefix="bridge_selftest_"))
        store = Store(tmp)
        cfg = Config(store)
        cfg.data.update({"catalog_auto_refresh": False, "profile_auto_relearn": False, "human_window_autoshow": False, **(extra_cfg or {})})   # no background work in tests
        return tmp, store, cfg, App(store, cfg)

    def add_acct(app: "App", aid: str, label: str, host: str = "x.test", **kw: Any) -> Dict[str, Any]:
        a = {"id": aid, "label": label, "host": host, "url": "https://" + host, "state": "ready", "tier": "direct", "requests": 0,
             "ok": 0, "fail": 0, "streak_fail": 0, "ema_ms": 0, "cooldown_until": 0, "last_error": "", "health": None}
        a.update(kw)
        app.acc.items.append(a)
        return a

    def call(port: int, method: str, path: str, body: Any = None, headers: Optional[Dict[str, str]] = None) -> Tuple[int, Dict[str, str], bytes]:
        c = hc.HTTPConnection("127.0.0.1", port, timeout=15)
        h = dict(headers or {})
        data = None
        if body is not None:
            data = json.dumps(body).encode()
            h.setdefault("content-type", "application/json")
        c.request(method, path, body=data, headers=h)
        r = c.getresponse()
        b = r.read()
        out = (r.status, {k.lower(): v for k, v in r.getheaders()}, b)
        c.close()
        return out

    def sse_events(body: bytes) -> List[Tuple[Optional[str], str]]:
        evs = []
        for blk in body.decode("utf-8").split("\n\n"):
            if not blk.strip():
                continue
            name, data = None, ""
            for ln in blk.split("\n"):
                if ln.startswith("event: "):
                    name = ln[7:]
                elif ln.startswith("data: "):
                    data = ln[6:]
            evs.append((name, data))
        return evs

    def check_anthropic(evs: List[Tuple[Optional[str], str]], expect_error: bool = False) -> Dict[str, Any]:
        """Independent strict check of the Anthropic streaming grammar."""
        assert evs and evs[0][0] == "message_start", "first event must be message_start"
        open_idx, nxt, text, tools, stop_reason, ended = None, 0, "", [], None, False
        cur: Dict[str, Any] = {}
        for i, (name, data) in enumerate(evs):
            d = json.loads(data)
            assert d["type"] == name, f"event name/type mismatch at {i}"
            assert not ended, "event after terminal event"
            if name == "message_start":
                assert i == 0 and d["message"]["role"] == "assistant" and d["message"]["content"] == []
            elif name == "content_block_start":
                assert open_idx is None and d["index"] == nxt, "block order/index"
                open_idx, nxt, cur = d["index"], nxt + 1, {"type": d["content_block"]["type"], "json": "", "block": d["content_block"]}
            elif name == "content_block_delta":
                assert open_idx == d["index"], "delta outside its block"
                dt = d["delta"]["type"]
                assert (dt, cur["type"]) in (("text_delta", "text"), ("input_json_delta", "tool_use")), "delta/block type mismatch"
                if dt == "text_delta":
                    text += d["delta"]["text"]
                else:
                    cur["json"] += d["delta"]["partial_json"]
            elif name == "content_block_stop":
                assert open_idx == d["index"]
                if cur["type"] == "tool_use":
                    tools.append({"id": cur["block"]["id"], "name": cur["block"]["name"], "input": json.loads(cur["json"] or "{}")})
                open_idx = None
            elif name == "message_delta":
                assert open_idx is None, "message_delta with an open block"
                stop_reason = d["delta"]["stop_reason"]
                assert stop_reason in ("end_turn", "tool_use", "max_tokens", "stop_sequence")
            elif name == "message_stop":
                assert stop_reason is not None, "message_stop before message_delta"
                ended = True
            elif name == "error":
                assert expect_error and d["error"]["type"] and d["error"]["message"]
                ended = True
        assert ended, "stream has no terminal event"
        return {"text": text, "tools": tools, "stop_reason": stop_reason}

    def check_openai(body: bytes, expect_error: bool = False) -> Dict[str, Any]:
        lines = [ln for ln in body.decode("utf-8").split("\n\n") if ln.strip()]
        assert lines[-1] == "data: [DONE]", "stream must end with [DONE]"
        text, tools, finish, first = "", {}, None, True
        for ln in lines[:-1]:
            assert ln.startswith("data: ")
            d = json.loads(ln[6:])
            if "error" in d:
                assert expect_error
                return {"error": d["error"]}
            assert d["object"] == "chat.completion.chunk"
            ch = d["choices"][0]
            if first:
                assert ch["delta"].get("role") == "assistant", "first chunk must carry the role"
                first = False
            text += ch["delta"].get("content") or ""
            for tc in ch["delta"].get("tool_calls") or []:
                t = tools.setdefault(tc["index"], {"id": tc["id"], "name": tc["function"]["name"], "args": ""})
                t["args"] += tc["function"].get("arguments", "")
            if ch["finish_reason"]:
                assert finish is None, "two finish_reason chunks"
                finish = ch["finish_reason"]
        assert finish in ("stop", "tool_calls", "length") or expect_error
        return {"text": text, "tools": [dict(v, args=json.loads(v["args"] or "{}")) for _, v in sorted(tools.items())], "finish": finish}

    class Server:
        def __init__(self, app: "App") -> None:
            self.srv = serve(app, 0)
            self.port = self.srv.server_address[1]

        def close(self) -> None:
            self.srv.shutdown()
            self.srv.server_close()

