        # B6
        def test_refresh_lifecycle_events_and_snapshot_rules(self) -> None:
            add_acct(self.app, "a1", "One", "life.test")
            self.hook({"a1": [self.mv("alpha-1", "Alpha One"), self.mv("alpha-2")]})
            c = self.acc.refresh_catalog("a1", "account_added", force=True)
            self.assertEqual([e["type"] for e in c["events"]], ["added", "added"])
            self.hook({"a1": [self.mv("alpha-1", "Alpha One v2", native_tools="supported"), self.mv("alpha-3")]})      # rename + capability + add + remove
            c = self.acc.refresh_catalog("a1", "stale", force=True)
            types = [e["type"] for e in c["events"][2:]]
            self.assertEqual(sorted(types), ["added", "capability_appeared", "removed", "renamed"])
            by = {v["id"]: v for v in c["variants"]}
            self.assertEqual((by["alpha-1"]["display"], by["alpha-1"]["capabilities"]["native_tools"]), ("Alpha One v2", "supported"))
            self.assertEqual(by["alpha-2"]["status"], "unavailable")                                # disappeared: kept as history, not deleted
            self.hook({"a1": [self.mv("alpha-1", "Alpha One v2", native_tools="unsupported"), self.mv("alpha-2")]})
            c = self.acc.refresh_catalog("a1", "explicit", force=True)
            ev = {e["type"] for e in c["events"]}
            self.assertTrue({"capability_changed", "reappeared"} <= ev)
            self.assertEqual({v["id"]: v["status"] for v in c["variants"]}["alpha-2"], "available")
            self.hook({"a1": [self.mv("alpha-1")]})                                                  # unknown never erases a known capability
            c = self.acc.refresh_catalog("a1", "explicit", force=True)
            self.assertEqual({v["id"]: v for v in c["variants"]}["alpha-1"]["capabilities"]["native_tools"], "unsupported")
            self.hook({"a1": BridgeError("timed out", "network", 502)})
            before = len(self.acc.catalog("a1")["variants"])
            c = self.acc.refresh_catalog("a1", "stale", force=True)
            self.assertEqual((c["status"], len(c["variants"])), ("stale", before))
            self.assertIn("timed out", c["stale_reason"])
            self.assertTrue(c["last_attempt_at"] > c["refreshed_at"])

        def test_concurrent_refreshes_run_once(self) -> None:
            add_acct(self.app, "a1", "One", "conc.test")
            calls: List[int] = []

            def slow(a: Dict[str, Any], allow_ui: bool) -> Tuple[List[ModelVariant], str]:
                calls.append(1)
                time.sleep(0.5)
                return [self.mv("alpha-1")], "site_network"
            self.acc.discover_hook = slow
            bar, res = threading.Barrier(6), []

            def go() -> None:
                bar.wait()
                res.append(self.acc.refresh_catalog("a1", "t", force=True))
            ths = [threading.Thread(target=go) for _ in range(6)]
            for t in ths:
                t.start()
            for t in ths:
                t.join()
            self.assertEqual(len(calls), 1)
            self.assertEqual(len(res), 6)
            self.assertTrue(all(len(r["variants"]) == 1 for r in res))

        def test_due_logic_has_no_polling(self) -> None:
            add_acct(self.app, "a1", "One", "due.test")
            self.hook({"a1": [self.mv("alpha-1")]})
            fresh = self.acc.refresh_catalog("a1", "t", force=True)
            self.assertFalse(self.acc.catalog_due(fresh))                                           # fresh and inside the TTL
            self.cfg.data["catalog_ttl_seconds"] = 1
            fresh["refreshed_at"] -= 5
            self.assertTrue(self.acc.catalog_due(fresh))                                            # older than the TTL
            self.cfg.data["catalog_retry_seconds"] = 3600
            self.assertFalse(self.acc.catalog_due(fresh))                                           # but never retried faster than the retry gap
            n: List[int] = []
            self.acc.discover_hook = lambda a, ui: (n.append(1) or [self.mv("alpha-1")], "site_network")
            self.acc.refresh_catalog("a1", "dashboard_open")                                        # not forced + not due -> no discovery run
            self.assertEqual(n, [])

        def test_http_routes_models_profile_rollback(self) -> None:
            add_acct(self.app, "a1", "One", "http.test")
            self.hook({"a1": [self.mv("alpha-1")]})
            srv = Server(self.app)
            try:
                H = {"x-admin-key": self.cfg["admin_key"]}
                code, _h, body = call(srv.port, "GET", "/api/accounts/a1/models?refresh=if_stale", headers=H)
                self.assertEqual(code, 200)
                self.assertEqual([v["id"] for v in json.loads(body)["variants"]], ["alpha-1"])      # stale (never discovered) -> refreshed on open
                self.cfg.data["catalog_retry_seconds"] = 3600
                self.hook({"a1": [self.mv("alpha-1"), self.mv("alpha-2")]})
                code, _h, body = call(srv.port, "GET", "/api/accounts/a1/models?refresh=if_stale", headers=H)
                self.assertEqual(len(json.loads(body)["variants"]), 1)                              # fresh -> no discovery on open
                code, _h, body = call(srv.port, "POST", "/api/accounts/a1/models/refresh", body={}, headers=H)
                self.assertEqual(len(json.loads(body)["variants"]), 2)                              # explicit refresh always runs
                self.assertEqual(call(srv.port, "GET", "/api/accounts/nope/models", headers=H)[0], 404)
                self.assertEqual(call(srv.port, "GET", "/api/accounts/a1/models")[0], 401)
                code, _h, body = call(srv.port, "GET", "/api/profiles/http.test", headers=H)
                self.assertEqual((code, json.loads(body)["status"]), (200, "unverified"))
                self.assertEqual(call(srv.port, "POST", "/api/recipes/http.test/rollback", body={}, headers=H)[0], 404)
                st = json.loads(call(srv.port, "GET", "/api/state", headers=H)[2])
                self.assertEqual(st["accounts"][0]["models"]["count"], 2)
            finally:
                srv.close()

