    class TestRouting(unittest.TestCase):
        """Phase B: C1 policies, C2 profiles, C3 eligibility, C6 decisions, C7 identity, C10 preview (mock accounts only)."""

        def setUp(self) -> None:
            self.tmp, self.store, self.cfg, self.app = mk_env({"cache_seconds": 0})
            self.acc, self.eng = self.app.acc, self.app.engine
            for aid, lab in (("a1", "Alpha"), ("b2", "Beta"), ("c3", "Gamma")):
                add_acct(self.app, aid, lab, f"{lab.lower()}.test")
            self.seen: List[Tuple[str, str, str]] = []
            self.outcome_identity: Optional[Dict[str, Any]] = None

            def fake_run(acct: Dict[str, Any], req: NormReq, emit: Callable[[str], None], cancel: threading.Event) -> Outcome:
                self.seen.append((acct["id"], req.model, req.variant_native))
                emit("ok")
                o = Outcome("ok", [], "ok")
                o.identity = self.outcome_identity
                return o
            self.app.router._run = fake_run                                  # type: ignore[assignment]

        def tearDown(self) -> None:
            shutil.rmtree(self.tmp, ignore_errors=True)

        # -- helpers
        def api_acct(self, aid: str, variants: List[ModelVariant], **kw: Any) -> Dict[str, Any]:
            a = add_acct(self.app, aid, aid.upper(), "127.0.0.1", type="api", api_kind="openai", api_base="http://127.0.0.1:9/v1", api_model="dflt",
                         tier="api", private_ok=True, **kw)
            cat = new_catalog(aid)
            cat["variants"] = [v.to_dict() for v in variants]
            cat["status"] = "ok"
            self.acc.save_catalog(aid, cat)
            return a

        @staticmethod
        def var(nid: str, status: str = "available", **caps: str) -> ModelVariant:
            return ModelVariant(id=make_variant_id(nid, nid), display=nid, native_id=nid, capabilities=norm_caps(caps), source="api_endpoint",
                                discovered_at=1.0, verified_at=1.0, status=status, confidence="observed")

        def setup_policy(self, name: str = "p", **pol: Any) -> str:
            errs = self.eng.save_config({"policies": {name: pol}, "aliases": {"use-" + name: name}})
            self.assertEqual(errs, [], errs)
            return "use-" + name

        def mkreq(self, model: str = "bridge-auto", image: bool = False, tools: bool = False) -> NormReq:
            content: Any = "hello"
            if image:
                content = [{"type": "image", "source": {"type": "base64", "media_type": "image/png", "data": "AAAA"}}, {"type": "text", "text": "what is this"}]
            d: Dict[str, Any] = {"model": model, "max_tokens": 100, "messages": [{"role": "user", "content": content}]}
            if tools:
                d["tools"] = [{"name": "Bash", "description": "d", "input_schema": {}}]
            return normalize_anthropic(d)

        def plan(self, model: str = "bridge-auto", pinned: str = "", key_id: str = "", tried: Any = (), conv: str = "", **kw: Any) -> Tuple[Dict[str, Any], RouteDecision]:
            return self.eng.plan(self.mkreq(model, **kw), pinned, key_id, set(tried), "req_t", conv)

        def codes(self, rid: str, policy: Optional[Dict[str, Any]] = None, needs: Optional[Dict[str, Any]] = None, pinned: str = "", tried: Any = (),
                  cfgd: Optional[Dict[str, Any]] = None, breaker: Any = None) -> List[str]:
            r = self.eng.assess(rid, {"name": "t", "kind": "auto", **(policy or {})}, needs or {"capabilities": [], "tokens": 0, "max_tokens": 0}, pinned, set(tried),
                                {**default_routing(), **(cfgd or {})}, breaker)
            return [c for c, _d in r["codes"]]

        # -- C1: validator
        def test_validator_rejects_impossible_configs_with_precise_messages(self) -> None:
            add_acct(self.app, "d4", "Delta", "delta.test", state="login_required")
            cases = [
                ({"policies": {"p": {"kind": "fixed", "members": ["acct:zz"]}}}, "account_missing"),
                ({"policies": {"p": {"kind": "fixed", "members": ["acct:a1/model:nope"]}}}, "variant_unknown"),
                ({"policies": {"p": {"kind": "rotation", "members": []}}}, "empty_pool"),
                ({"policies": {"p": {"kind": "rotation", "members": ["acct:d4"]}}}, "no_eligible_member"),
                ({"policies": {"p": {"kind": "fixed", "members": ["acct:a1", "acct:b2"]}}}, "fixed_needs_one"),
                ({"policies": {"p": {"kind": "failover", "primary": "acct:a1", "backups": []}}}, "no_backups"),
                ({"policies": {"p": {"kind": "failover", "primary": "acct:a1", "backups": ["acct:a1"]}}}, "primary_in_backups"),
                ({"policies": {"p": {"kind": "magic"}}}, "unknown_kind"),
                ({"policies": {"p": {"kind": "auto"}}, "aliases": {"x": "nope"}}, "unknown_policy"),
                ({"policies": {"p": {"kind": "auto"}}, "weights": {"fast": {"load": 99}}}, "bad_weight"),
                ({"policies": {"p": {"kind": "rotation", "members": ["acct:a1"], "strategy": "dice"}}}, "bad_strategy"),
                ({"policies": {"bridge-x": {"kind": "auto"}}}, "bad_name"),
                ({"policies": {"p": {"kind": "auto"}}, "account_policy": {"gone": "p"}}, "account_missing"),
                ({"policies": {"p": {"kind": "auto", "required_capabilities": ["telepathy"]}}}, "unknown_capability"),
            ]
            for cfg_, code in cases:
                errs = self.eng.validate({**default_routing(), **cfg_})
                self.assertIn(code, [e["code"] for e in errs], (code, errs))
                self.assertTrue(all(e["message"] and e["path"] is not None for e in errs))
            self.assertEqual(self.eng.validate({**default_routing(), "policies": {"p": {"kind": "rotation", "members": ["acct:a1", "acct:b2"]}}}), [])
            before = self.eng.config()
            self.assertTrue(self.eng.save_config({"policies": {"p": {"kind": "fixed", "members": ["acct:zz"]}}}))
            self.assertEqual(self.eng.config(), before)                      # an invalid config is refused and never stored
            self.assertFalse(self.store.path("routing.json").exists())

        # -- C1: one test per policy
        def test_policy_fixed_never_substitutes(self) -> None:
            m = self.setup_policy(kind="fixed", members=["acct:b2"])
            self.acc.inflight["b2"] = 1                                       # b2 is busier than a1, a fixed route does not care
            self.assertEqual(self.plan(m)[0]["acct"]["id"], "b2")
            self.acc.get("b2")["cooldown_until"] = now() + 60
            with self.assertRaises(BridgeError) as cx:
                self.plan(m)
            self.assertIn("cooldown", str(cx.exception))
            self.assertEqual(cx.exception.kind, "unavailable")                # a1 / c3 were NOT used
            m2 = self.setup_policy("q", kind="fixed", members=["acct:b2"], on_unavailable="ask")
            with self.assertRaises(ApprovalRequired) as cx2:
                self.plan(m2)
            self.assertEqual(cx2.exception.kind, "approval_required")

        def test_policy_auto_ranks_eligible_routes(self) -> None:
            self.acc.inflight["a1"] = 3
            r, dec = self.plan("bridge-auto")
            self.assertNotEqual(r["acct"]["id"], "a1")
            self.assertEqual((dec.policy_kind, dec.selection_basis), ("auto", "capability-based"))

        def test_policy_rotation_strategies_and_units(self) -> None:
            members = ["acct:a1", "acct:b2", "acct:c3"]
            m = self.setup_policy(kind="rotation", members=members, strategy="round_robin")
            order = [self.plan(m)[0]["acct"]["id"] for _ in range(9)]
            self.assertEqual(order, ["a1", "b2", "c3"] * 3)
            m = self.setup_policy("ll", kind="rotation", members=members, strategy="least_loaded")
            self.acc.inflight.update({"a1": 2, "b2": 0, "c3": 1})
            self.assertEqual(self.plan(m)[0]["acct"]["id"], "b2")
            self.acc.inflight.clear()
            m = self.setup_policy("lru", kind="rotation", members=members, strategy="least_recently_used")
            self.eng.lru.clear()
            self.assertEqual([self.plan(m)[0]["acct"]["id"] for _ in range(4)], ["a1", "b2", "c3", "a1"])
            m = self.setup_policy("hw", kind="rotation", members=members, strategy="health_weighted")
            self.acc.get("a1").update(ok=1, fail=9)
            self.acc.get("b2").update(ok=9, fail=1)
            self.assertEqual(self.plan(m)[0]["acct"]["id"], "b2")
            m = self.setup_policy("cv", kind="rotation", members=members, strategy="round_robin", unit="conversation")
            first = self.plan(m, conv="x")[0]["acct"]["id"]
            other = self.plan(m, conv="y")[0]["acct"]["id"]
            self.assertNotEqual(first, other)
            self.assertEqual(self.plan(m, conv="x")[0]["acct"]["id"], first)   # the same conversation stays on its route

        def test_policy_failover_only_uses_listed_backups(self) -> None:
            m = self.setup_policy(kind="failover", primary="acct:a1", backups=["acct:b2"])
            r, dec = self.plan(m)
            self.assertEqual((r["acct"]["id"], dec.fallback), ("a1", False))
            self.acc.get("a1")["cooldown_until"] = now() + 60
            r, dec = self.plan(m)
            self.assertEqual((r["acct"]["id"], dec.fallback), ("b2", True))
            self.acc.get("b2")["disabled"] = True
            with self.assertRaises(BridgeError):                              # c3 is healthy but was never permitted
                self.plan(m)

        def test_policy_lowest_latency_needs_samples(self) -> None:
            m = self.setup_policy(kind="lowest_latency", members=["acct:a1", "acct:b2", "acct:c3"], min_samples=3)
            r, dec = self.plan(m)
            self.assertEqual(dec.selection_basis, "capability-based")          # no latency data: not pretended
            self.assertIn("not by latency", dec.reason)
            self.acc.get("a1").update(ok=5, ema_ms=3000)
            self.acc.get("b2").update(ok=5, ema_ms=1000)
            self.acc.get("c3").update(ok=1, ema_ms=10)                         # fastest, but only one sample
            r, dec = self.plan(m)
            self.assertEqual((r["acct"]["id"], dec.selection_basis), ("b2", "measured"))
            self.assertIn("latency_samples_insufficient", [e["code"] for e in dec.excluded])

        def test_policy_best_fit_uses_capabilities_not_names(self) -> None:
            va, vb = self.var("zeta-1", image_input="supported"), self.var("omega-9")
            self.api_acct("x1", [va])
            self.api_acct("x2", [vb])
            m = self.setup_policy(kind="best_fit", members=[f"acct:x2/model:{vb.id}", f"acct:x1/model:{va.id}"], required_capabilities=["image_input"])
            r, dec = self.plan(m)
            self.assertEqual(r["acct"]["id"], "x1")                            # stated support beats unknown, whatever the order or name
            self.acc.get("x1")["cooldown_until"] = now() + 60
            r, dec = self.plan(m)
            self.assertEqual(r["acct"]["id"], "x2")
            self.assertTrue(any("image_input support unknown" in f for f in dec.flags))

