        # -- C7: identity
        def test_identity_hidden_revealed_and_never_inferred(self) -> None:
            def run() -> RouteDecision:
                self.app.router.handle(self.mkreq("claude-sonnet-x"), lambda t: None, "", threading.Event(), scope="k", meta={"request_id": "req_i"})
                return self.eng.decisions[-1]
            self.outcome_identity = None                                         # site that never says which model answered
            d = run()
            self.assertEqual(d.identity["observed"]["state"], "unknown")
            self.assertEqual(d.identity["requested"], "claude-sonnet-x")
            self.assertTrue(d.identity["selected_route"].startswith("acct:"))   # three separate fields
            self.outcome_identity = {"state": "revealed_after_response", "value": "model-q", "confidence": "observed", "source": "site"}
            d = run()
            self.assertEqual((d.identity["observed"]["state"], d.identity["observed"]["value"]), ("revealed_after_response", "model-q"))
            self.assertNotEqual(d.identity["requested"], d.identity["observed"]["value"])
            self.outcome_identity = None                                         # a reply that merely CLAIMS an identity changes nothing
            self.app.router._run = lambda a, r, e, c: Outcome("I am Foo-9, built by Bar.", [], "")     # type: ignore[assignment]
            self.assertEqual(run().identity["observed"]["state"], "unknown")

        def test_api_backend_records_only_what_the_provider_declared(self) -> None:
            class H(BaseHTTPRequestHandler):
                protocol_version = "HTTP/1.1"

                def log_message(self, *a: Any) -> None:
                    pass

                def do_POST(self) -> None:
                    self.rfile.read(int(self.headers.get("content-length") or 0))
                    self.send_response(200)
                    self.send_header("content-type", "text/event-stream")
                    self.send_header("connection", "close")
                    self.end_headers()
                    for e in ['data: {"model":"declared-x","choices":[{"index":0,"delta":{"content":"hi"},"finish_reason":null}]}\n\n',
                              'data: {"choices":[{"index":0,"delta":{},"finish_reason":"stop"}]}\n\n', "data: [DONE]\n\n"]:
                        self.wfile.write(e.encode())
                    self.wfile.flush()
                    self.close_connection = True
            srv = ThreadingHTTPServer(("127.0.0.1", 0), H)
            srv.daemon_threads = True
            threading.Thread(target=srv.serve_forever, daemon=True).start()
            try:
                be = ApiBackend({"api_kind": "openai", "api_base": f"http://127.0.0.1:{srv.server_address[1]}/v1", "api_model": "m"}, "k")
                be.allow_private = True
                out = be.complete(self.mkreq("m"), lambda t: None, threading.Event())
                self.assertEqual((out.identity or {}).get("value"), "declared-x")
                self.assertEqual((out.identity or {}).get("state"), "revealed_in_response")
            finally:
                srv.shutdown()
                srv.server_close()

        # -- C10: preview
        def test_preview_blocks_a_switch_that_loses_an_image_capability(self) -> None:
            vi, vn = self.var("img-1", image_input="supported"), self.var("txt-1", image_input="unsupported")
            self.api_acct("x1", [vi])
            self.api_acct("x2", [vn])
            m = self.setup_policy(kind="failover", primary=f"acct:x1/model:{vi.id}", backups=[f"acct:x2/model:{vn.id}"])
            self.acc.get("x1")["cooldown_until"] = now() + 60
            r, dec = self.plan(m)                                                # text-only task: the backup is fine and is labelled a fallback
            self.assertEqual((r["acct"]["id"], dec.fallback), ("x2", True))
            with self.assertRaises(BridgeError) as cx:                           # the task contains an image: the backup cannot take it
                self.plan(m, image=True)
            self.assertIn("capability_unsupported", str(cx.exception))
            pv = self.eng.preview(f"acct:x1/model:{vi.id}", f"acct:x2/model:{vn.id}", {"capabilities": ["image_input"], "tokens": 0, "max_tokens": 0})
            self.assertTrue(pv["blocked"] and pv["requires_approval"])
            self.assertEqual((pv["blocking_capabilities"], "image_input" in pv["capabilities_lost"]), (["image_input"], True))
            self.assertIn("context will be rebuilt", pv["remote_memory"])
            self.assertTrue(pv["uncertain"])                                     # identity is only 'observed', not verified: stated, not hidden

