                self.assertEqual(call(srv.port, "POST", "/api/routing/validate", good, A)[0], 200)
                st, _h, b = call(srv.port, "POST", "/api/routing", {"policies": {"p": {"kind": "fixed", "members": ["acct:zz"]}}}, A)
                self.assertEqual((st, json.loads(b)["problems"][0]["code"]), (400, "account_missing"))
                self.assertEqual(call(srv.port, "POST", "/api/routing", good, A)[0], 200)
                st, _h, b = call(srv.port, "GET", "/api/routing", headers=A)
                self.assertEqual((st, json.loads(b)["config"]["aliases"]), (200, {"pool": "p"}))
                st, _h, b = call(srv.port, "POST", "/api/routing/preview", {"from": "acct:a1", "to": "acct:b2", "needs": {"capabilities": ["tools"]}}, A)
                self.assertEqual((st, json.loads(b)["blocked"]), (200, False))
