        # -- D1
        def test_classification_table_status_first_text_second_unknown_is_not_quota(self) -> None:
            B = BridgeError
            table = [
                (RateLimited("HTTP 429: slow down", 60, False, "status"), "rate_limited_model", "low", True),
                (_limited("HTTP 429: daily usage limit reached", None, "status"), "usage_cap_account", "high", True),
                (_limited("your account has too many requests", None, "text"), "rate_limited_account", "medium", False),
                (_limited("\u0633\u0642\u0641 \u0631\u0648\u0632\u0627\u0646\u0647 \u067e\u0631 \u0634\u062f - \u067e\u0633 \u0627\u0632 \u06f5 \u062f\u0642\u06cc\u0642\u0647 \u062f\u0648\u0628\u0627\u0631\u0647 \u062a\u0644\u0627\u0634 \u06a9\u0646\u06cc\u062f", None, "text"), "usage_cap_account", "medium", False),
                (_limited("this model is limited", None, "status"), "rate_limited_model", "medium", True),
                (B("network error: [Errno -2] Name or service not known", "network"), "dns_error", "high", False),
                (B("network error: [Errno 111] Connection refused", "network"), "network_error", "high", False),
                (B("network error: timed out", "network"), "timeout", "medium", False),
                (B("stream interrupted: reset", "network"), "stream_interrupted", "high", False),
                (B("HTTP 503: server busy, quota exceeded", "upstream"), "upstream_unavailable", "high", False),
                (B("HTTP 504: gateway", "upstream"), "timeout", "high", False),
                (B("HTTP 400: model 'x' does not exist", "upstream"), "model_not_found", "medium", False),
                (B("HTTP 400: maximum context length is 8192 tokens", "upstream"), "context_too_large", "medium", False),
                (B("HTTP 413: too big", "upstream"), "context_too_large", "high", False),
                (B("HTTP 400: unsupported parameter: foo", "upstream"), "unsupported_parameter", "medium", False),
                (B("HTTP 400: blocked by our content policy", "upstream"), "content_blocked", "medium", False),
                (B("HTTP 400: bad thing", "upstream"), "invalid_request", "medium", False),
                (B("HTTP 418: teapot", "upstream"), "unknown", "low", False),
                (B("something strange happened", "upstream"), "unknown", "low", False),
                (B("we are very busy", "upstream"), "upstream_unavailable", "low", False),
                (AuthError("HTTP 401: nope"), "auth_expired", "high", False),
                (AuthError("HTTP 403: nope"), "permission_denied", "medium", False),
                (B("blocked by bot protection", "challenge", 403), "challenge_required", "high", False),
                (B("empty answer from site: <html>Please sign in</html>", "empty"), "auth_expired", "medium", False),
                (B("empty answer from site: stream format changed (learned sse, now looks like json)", "empty"), "recipe_invalid", "high", False),
                (B("empty answer from site: {}", "empty"), "empty_response", "medium", False),
            ]
            for e, cat, conf, confirmed in table:
                i = classify_error(e)
                self.assertEqual((i.category, i.confidence, i.limit_confirmed), (cat, conf, confirmed), str(e))
                self.assertIn(i.category, ERROR_CATEGORIES)
                self.assertIn(i.scope, ERROR_SCOPES)
            self.assertNotIn("quota", [classify_error(B(m, "upstream")).category for m in ("quota?", "something strange", "limit")])   # words alone on a non-limit kind
            self.assertFalse(classify_error(B("HTTP 400: bad", "upstream")).failover_ok)
            self.assertTrue(classify_error(B("HTTP 503: x", "upstream")).failover_ok)
            self.assertTrue(classify_error(B("HTTP 500: x", "upstream")).may_have_been_accepted)
            self.assertFalse(classify_error(B("HTTP 503: x", "upstream")).may_have_been_accepted)
            self.assertTrue(classify_error(B("x", "upstream"), partial_output=True).partial_output_sent)

        def test_a_5xx_that_mentions_quota_is_not_a_rate_limit(self) -> None:
            rc = RecipeClient(mk_recipe(), None, {})
            for status, body, want in ((500, "quota exceeded, server busy", BridgeError), (429, "x", RateLimited), (400, "usage limit exceeded", RateLimited)):
                with self.assertRaises(BridgeError) as cx:
                    rc._check_status(status, {"retry-after": "7"}, iter([body.encode()]))
                self.assertIs(type(cx.exception), want, (status, body))
            self.assertEqual((cx.exception.retry_after, cx.exception.explicit_retry_after, cx.exception.signal), (7.0, True, "text"))
            with self.assertRaises(RateLimited) as c2:
                rc._check_status(429, {}, iter([b"slow down"]))
            self.assertFalse(c2.exception.explicit_retry_after)                               # a missing wait is never presented as the site's

