        def test_model_scoped_limit_rests_only_that_route(self) -> None:
            self.a1["state"] = "login_required"
            a = self.api2("x1", ["m-one", "m-two"])
            v1, v2 = (v["id"] for v in self.acc.catalog("x1")["variants"])
            self.app.engine.save_config({"policies": {"pool": {"kind": "rotation", "members": [f"acct:x1/model:{v1}", f"acct:x1/model:{v2}"], "strategy": "round_robin"}},
                                         "aliases": {"p": "pool"}})
            self.script = [_limited("HTTP 429: this model is limited", 90, "status")]
            self.script[0].explicit_retry_after = True
            self.go("p")
            self.assertEqual([c[1] for c in self.calls], ["m-one", "m-two"])                  # m-one limited -> permitted sibling m-two served it
            self.assertEqual(a.get("cooldown_until", 0), 0)                                   # the account is NOT cooling
            until, why = self.acc.route_cooldown(f"acct:x1/model:{v1}")
            self.assertTrue(80 < until - now() <= 90)                                        # Retry-After honoured
            self.assertEqual(self.acc.route_cooldown(f"acct:x1/model:{v2}")[0], 0)           # the sibling is untouched
            for _ in range(4):
                self.go("p")
            self.assertEqual({c[1] for c in self.calls[2:]}, {"m-two"})                       # m-one rests while it is limited
            self.assertEqual(a["last_limit"]["scope"], "route")

