        # -- D3 breaker
        def test_breaker_state_machine_with_a_fake_clock(self) -> None:
            clk = [0.0]
            b = CircuitBreaker(3, 30, 100, lambda: clk[0])
            self.assertEqual(b.peek(), ("closed", 0.0))
            b.failure(); b.failure()
            self.assertEqual(b.peek()[0], "closed")
            b.success()                                                                       # consecutive: a success resets the count
            b.failure(); b.failure()
            self.assertEqual(b.peek()[0], "closed")
            b.failure()
            self.assertEqual(b.peek(), ("open", 30.0))
            self.assertFalse(b.acquire())
            clk[0] = 29.9
            self.assertEqual(b.peek()[0], "open")
            clk[0] = 30.0
            self.assertEqual(b.peek()[0], "half_open")
            self.assertTrue(b.acquire())                                                      # exactly ONE probe
            self.assertEqual(b.peek()[0], "half_open_busy")
            self.assertFalse(b.acquire())
            b.failure()                                                                       # probe failed -> open again, twice as long
            self.assertEqual(b.peek(), ("open", 60.0))
            clk[0] = 90.0
            self.assertTrue(b.acquire())
            b.release()                                                                       # an attempt that proved nothing frees the slot
            self.assertTrue(b.acquire())
            b.failure()
            self.assertEqual(b.peek(), ("open", 100.0))                                       # bounded by max_open
            clk[0] = 190.0
            self.assertTrue(b.acquire())
            b.success()
            self.assertEqual(b.peek(), ("closed", 0.0))
            self.assertTrue(b.acquire())

        def test_breaker_counts_only_health_failures_and_scopes_keys(self) -> None:
            clk = [0.0]
            self.acc.breakers = BreakerBoard(self.cfg, lambda: clk[0])
            bd = self.acc.breakers
            for cat in ("rate_limited_model", "usage_cap_account", "auth_expired", "invalid_request", "content_blocked", "unknown") * 3:
                bd.on_failure("a1", "", ErrorInfo(category=cat, scope="provider"))
            self.assertIsNone(bd.blocked("a1", ""))
            for _ in range(3):
                bd.on_failure("a1", "v1", ErrorInfo(category="upstream_unavailable", scope="model"))
            self.assertEqual(bd.blocked("a1", "v1")[0], "acct:a1/model:v1")                   # a model-scoped failure opens that route only
            self.assertIsNone(bd.blocked("a1", "v2"))
            self.assertIsNone(bd.blocked("a1", ""))
            for _ in range(3):
                bd.on_failure("a1", "v2", ErrorInfo(category="network_error", scope="network"))
            self.assertEqual(bd.blocked("a1", "v9")[0], "acct:a1")                            # a wider failure opens the account: every route of it
            self.assertIn("acct:a1", bd.snapshot())

