        def test_transient_error_on_the_only_route_is_retried_with_backoff_inside_the_budget(self) -> None:
            e = BridgeError("network error: [Errno -2] Name or service not known", "network")
            self.script = [e, BridgeError("network error: [Errno -2] Name or service not known", "network")]
            meta: Dict[str, Any] = {}
            out = self.go(meta=meta)
            self.assertEqual(out.text, "ok")
            self.assertEqual(len(self.calls), 3)
            self.assertEqual(len(self.slept), 2)
            self.assertTrue(0.25 <= self.slept[0] <= 0.5 and 0.5 <= self.slept[1] <= 1.0)       # exponential, jittered: base 0.5 -> 0.25..0.5, then 0.5..1.0
            self.assertEqual(meta["backoff_s"], [round(x, 2) for x in self.slept])

        def test_retry_is_bounded_by_attempts_same_route_limit_and_deadline(self) -> None:
            self.script = [BridgeError("HTTP 503: down", "upstream")] * 10
            with self.assertRaises(BridgeError):
                self.go()
            self.assertEqual(len(self.calls), 3)                                              # first try + retry_same_route (2)
            self.calls.clear(); self.slept.clear()
            self.acc.breakers = BreakerBoard(self.cfg)
            self.cfg.data.update(retry_deadline_seconds=0.3, breaker_threshold=99)
            self.script = [BridgeError("HTTP 503: down", "upstream")] * 10
            with self.assertRaises(BridgeError):
                self.go()
            self.assertEqual((len(self.calls), self.slept), (1, []))                          # the next backoff would cross the deadline: no retry at all
            self.cfg.data.update(retry_deadline_seconds=120, retry_attempts=2)
            self.calls.clear()
            self.script = [BridgeError("HTTP 503: down", "upstream")] * 10
            with self.assertRaises(BridgeError):
                self.go()
            self.assertEqual(len(self.calls), 2)                                              # the attempts budget is global

