    class TestGroupO(unittest.TestCase):
        """Group O governing rules (O16, O20, O6) and O1 lifecycle. Mock only: no real site, login or browser was exercised."""

        def setUp(self) -> None:
            self.tmp, self.store, self.cfg, self.app = mk_env()
            self.acc = self.app.acc

        def tearDown(self) -> None:
            shutil.rmtree(self.tmp, ignore_errors=True)

        def mk(self, aid: str = "g1", lcs: str = "learning", **kw: Any) -> Dict[str, Any]:
            a = add_acct(self.app, aid, "Gamma", "g.test", **kw)
            lc_init(a, lcs, "test")
            return a

        # -- O1
        def test_every_listed_transition_works_every_other_is_refused_and_each_is_logged_with_a_reason(self) -> None:
            ok_pairs = 0
            for src in LIFECYCLE_STATES:
                for dst in LIFECYCLE_STATES:
                    a = self.mk()
                    a["lifecycle"]["state"] = src
                    n0 = len(a["lifecycle"]["events"])
                    legal = dst == src or (dst == "logging_in" and src != "disabled") or dst in LIFECYCLE_ALLOWED.get(src, ())
                    ev = {"validation_id": "v1"} if dst == "stable_direct" else None
                    if legal:
                        lc_transition(a, dst, "because " + dst, ev)
                        self.assertEqual(a["lifecycle"]["state"], dst)
                        if dst != src:
                            ok_pairs += 1
                            last = a["lifecycle"]["events"][-1]
                            self.assertEqual((last["from"], last["to"], last["reason"]), (src, dst, "because " + dst))
                            self.assertEqual(len(a["lifecycle"]["events"]), n0 + 1)
                    else:
                        with self.assertRaises(BridgeError) as cm:
                            lc_transition(a, dst, "x", ev)
                        self.assertEqual(cm.exception.status, 409)
                        self.assertEqual((a["lifecycle"]["state"], len(a["lifecycle"]["events"])), (src, n0))
            self.assertGreater(ok_pairs, 30)
            with self.assertRaises(BridgeError):
                lc_transition(self.mk(), "no_such_state", "x")
            with self.assertRaises(BridgeError):
                lc_transition(self.mk(), "validating", "  ")                      # a reason is required

        def test_stable_direct_is_reachable_only_from_validating_and_only_with_a_validation_id(self) -> None:
            self.assertEqual([s for s, d in LIFECYCLE_ALLOWED.items() if "stable_direct" in d], ["validating"])
            a = self.mk(lcs="validating")
            for bad in (None, {}, {"validation_id": ""}, {"validation_id": "  "}, {"note": "looks fine"}):
                with self.assertRaises(BridgeError):
                    lc_transition(a, "stable_direct", "promote", bad)
                self.assertEqual(a["lifecycle"]["state"], "validating")
            lc_transition(a, "stable_direct", "battery passed", {"validation_id": "val-1"})
            self.assertEqual(a["lifecycle"]["state"], "stable_direct")
            b = self.mk("g2", lcs="degraded_fallback")
            with self.assertRaises(BridgeError):                                   # no shortcut from the fallback tier
                lc_transition(b, "stable_direct", "it works now", {"validation_id": "val-1"})

        def test_lifecycle_survives_a_restart_work_in_flight_is_recovered_and_old_accounts_are_migrated_honestly(self) -> None:
            for i, s in enumerate(LIFECYCLE_STATES):
                self.mk(f"s{i}", s, state="ready", tier="page")
            self.mk("nr", "learning", state="login_required", tier="")             # a learn that never produced anything
            add_acct(self.app, "old1", "Old", "o1.test")                          # predates the lifecycle: ready + tier
            add_acct(self.app, "old2", "Old2", "o2.test", state="login_required", tier="")
            add_acct(self.app, "old3", "Old3", "o3.test", disabled=True)
            add_acct(self.app, "api1", "Api", "api.test", type="api", tier="api")
            self.acc.save()
            acc2 = Accounts(self.store, self.cfg)                                  # "kill the process and restart"
            for i, s in enumerate(LIFECYCLE_STATES):
                st = acc2.get(f"s{i}")["lifecycle"]["state"]
                self.assertNotIn(st, LIFECYCLE_TRANSIENT, s) if s in LIFECYCLE_TRANSIENT else self.assertEqual(st, s)
                if s in LIFECYCLE_TRANSIENT:
                    self.assertEqual(st, "degraded_fallback")
                    self.assertEqual(acc2.get(f"s{i}")["lifecycle"]["events"][-1]["from"], s)
            self.assertEqual(acc2.get("nr")["lifecycle"]["state"], "needs_login")
            self.assertEqual([acc2.get(x)["lifecycle"]["state"] for x in ("old1", "old2", "old3")], ["degraded_fallback", "needs_login", "disabled"])
            self.assertIn("never validated", acc2.get("old1")["lifecycle"]["reason"])
            self.assertNotIn("lifecycle", acc2.get("api1"))
            self.assertFalse(any(acc2.get(x)["lifecycle"]["state"] == "stable_direct" for x in ("nr", "old1", "old2", "old3")))     # migration never invents a stable account
            acc3 = Accounts(self.store, self.cfg)                                  # a second restart changes nothing more
            self.assertEqual([a.get("lifecycle", {}).get("state") for a in acc2.items], [a.get("lifecycle", {}).get("state") for a in acc3.items])

        def test_add_relogin_forget_and_disable_move_the_lifecycle_and_are_listed_in_the_account_view(self) -> None:
            self.acc.start_job = lambda a, kind, **kw: Job(kind, a["label"])      # type: ignore[assignment]
            a, _job = self.acc.add("https://new.test", "New")
            self.assertEqual(a["lifecycle"]["state"], "logging_in")
            self.assertEqual([e["to"] for e in a["lifecycle"]["events"]], ["adding", "logging_in"])
            self.assertEqual(a["learn_budget"]["limit"], 12)
            self.acc.lc(a["id"], "capturing", "c"); self.acc.lc(a["id"], "learning", "l"); self.acc.lc(a["id"], "degraded_fallback", "d")
            self.acc.relogin(a["id"])
            self.assertEqual(a["lifecycle"]["state"], "logging_in")
            pub = [x for x in self.acc.public() if x["id"] == a["id"]][0]
            self.assertEqual((pub["lifecycle"]["state"], pub["learn_budget"]["used"]), ("logging_in", 0))
            self.assertTrue(pub["lifecycle"]["reason"] and pub["lifecycle"]["at"])
            self.store.write("recipes/new.test.json", {"x": 1})
            self.acc.delete_recipe("new.test")
            self.assertEqual(a["lifecycle"]["state"], "needs_login")

        def test_needs_login_and_needs_human_make_a_route_ineligible_with_a_reason_code(self) -> None:
            self.mk("h1", "needs_human", state="ready")
            self.mk("l1", "needs_login", state="ready")
            self.mk("ok1", "degraded_fallback", state="ready")
            self.mk("st1", "stable_direct", state="ready")
            def codes(aid: str) -> List[str]:
                r = self.app.engine.assess(f"acct:{aid}", {"name": "t", "kind": "auto"}, {"capabilities": [], "tokens": 0, "max_tokens": 0}, "", set(), default_routing(), None)
                return [c for c, _d in r["codes"]]
            self.assertIn("needs_human", codes("h1"))
            self.assertIn("session_expired", codes("l1"))
            self.assertNotIn("needs_human", codes("ok1") + codes("st1"))
            self.assertNotIn("session_expired", codes("ok1") + codes("st1"))
            self.assertIn("needs_human", EXCLUSION_CODES)

        def test_http_disable_and_enable_follow_the_lifecycle(self) -> None:
            self.mk("g1", "degraded_fallback", state="ready")
            srv = Server(self.app)
            try:
                H = {"x-admin-key": self.cfg["admin_key"]}
                self.assertEqual(call(srv.port, "POST", "/api/accounts/g1/enabled", {"enabled": False}, H)[0], 200)
                self.assertEqual(self.acc.get("g1")["lifecycle"]["state"], "disabled")
                self.assertEqual(call(srv.port, "POST", "/api/accounts/g1/enabled", {"enabled": True}, H)[0], 200)
                self.assertEqual(self.acc.get("g1")["lifecycle"]["state"], "degraded_fallback")
            finally:
                srv.close()

        def test_a_failed_login_job_ends_in_needs_login_and_its_reason_carries_no_credential(self) -> None:
            a = self.mk("j1", "logging_in", state="learning")
            job = Job("login", "Gamma")
            def boom() -> None:
                raise RuntimeError("login failed with Authorization: Bearer abcdef0123456789SECRETXYZ")
            old = globals()["ensure_playwright"]
            globals()["ensure_playwright"] = boom
            try:
                self.acc._job_main(a, job)
            finally:
                globals()["ensure_playwright"] = old
            self.assertEqual(a["lifecycle"]["state"], "needs_login")
            self.assertNotIn("SECRETXYZ", json.dumps(a["lifecycle"]))
            self.assertIn("redacted", a["lifecycle"]["reason"])
            self.assertEqual(json.loads(self.store.path("accounts.json").read_text())[0]["lifecycle"]["state"], "needs_login")

        # -- O6
        def test_learning_budget_defaults_limits_automatic_spending_and_counts_the_owners_own_requests(self) -> None:
            a = self.mk("b1", "logging_in")
            b = self.acc.begin_learn("b1", "learn")
            self.assertEqual((b["limit"], b["used"]), (12, 0))
            for _ in range(4):
                self.acc.spend_learn("b1", 3, "step")
            with self.assertRaises(BridgeError) as cm:
                self.acc.spend_learn("b1", 1, "one more")
            self.assertEqual(cm.exception.status, 429)
            self.assertIn("12/12", str(cm.exception))
            self.assertEqual(a["learn_budget"]["used"], 12)                         # a refused spend changes nothing
            self.acc.spend_learn("b1", 5, "owner pressed the button", explicit=True)
            self.assertEqual((a["learn_budget"]["used"], a["learn_budget"]["owner_explicit"]), (12, 5))
            r = self.acc.begin_learn("b1", "repair")
            self.assertEqual((r["limit"], r["used"]), (3, 0))
            self.cfg.data["repair_budget_requests"] = 1
            self.assertEqual(self.acc.begin_learn("b1", "repair")["limit"], 1)
            self.assertEqual(json.loads(self.store.path("accounts.json").read_text())[0]["learn_budget"]["limit"], 1)   # persisted: the card can show it after a restart

