    class TestGroupO18(unittest.TestCase):
        """O18 on mock traffic and mock scripts ONLY (fixtures of TestGroupO17). No real site, browser or model."""
        HOST = "m18.mock17.test"

        def setUp(self) -> None:
            self.f = TestGroupO17("test_o17_the_deterministic_path_never_asks_a_model")
            self.tmp = tempfile.mkdtemp()
            self.store = Store(Path(self.tmp))
            self.specs = [self.f.sig_spec(), self.f.pow_spec()]
            self.exs = self.f.site()

        def tearDown(self) -> None:
            shutil.rmtree(self.tmp, ignore_errors=True)

        def run_o18(self, exs: Optional[List[Dict[str, Any]]] = None, specs: Optional[List[Dict[str, Any]]] = None, scripts: Optional[List[Dict[str, Any]]] = None) -> Dict[str, Any]:
            return o18_run(self.store, self.HOST, self.exs if exs is None else exs, self.f.scripts() if scripts is None else scripts, self.specs if specs is None else specs, ("body.$.prompt",), "POST /api/chat")

        def sdir(self) -> Path:
            return self.store.path("site_modules", safe_host_dir(self.HOST))

        def test_o18_trusted_algorithms_become_readable_modules_that_rebuild_the_request(self) -> None:
            r = self.run_o18()
            self.assertTrue(r["ok"], r)
            tok = (self.sdir() / "tokens.py").read_text()
            self.assertIn("# source: https://mock17.test/static/app.js", tok)                       # provenance is visible in the module itself
            self.assertIn("def make_header_x_sig(ctx):", tok)
            man = self.store.read(f"site_modules/{safe_host_dir(self.HOST)}/manifest.json")
            self.assertEqual((man["scenarios"], man["script_hashes"][self.f.app_url()]), ({"captures": 3, "passed": 3}, o17_script_hash(self.f.APP)))
            self.assertEqual(man["modules"]["tokens.py"], hashlib.sha256(tok.encode()).hexdigest())
            self.assertTrue(man["validated_at"])
            self.assertNotIn(self.f.SECRET, json.dumps(man))                                        # the manifest carries hashes, never constants
            ld = o18_load(self.store, self.HOST, self.f.scripts())
            self.assertEqual((ld["use"], ld["source"]), (True, "current"))
            out = o18_build_request(ld, {"body.$.prompt": "brand new"}, {"body.$.prefix": "x"})
            want = hmac.new(self.f.SECRET.encode(), f"{out['header.x-ts']}.brand new".encode(), hashlib.sha256).hexdigest()
            self.assertEqual((out["header.x-sig"], out["header.x-client"]), (want, "web-1.4"))
            self.assertTrue(o17_pow_ok(out["header.x-pow-prefix"], out["header.x-pow"], int(out["header.x-pow-bits"])))

        def test_o18_ast_allow_list_refuses_everything_outside_the_small_set(self) -> None:
            bad = ["import os\n", "import subprocess\n", "import socket\n", "from os import path\n", "from hashlib import *\n", "import urllib.request\n", "def f():\n    return open('x')\n",
                   "def f():\n    return eval('1')\n", "def f():\n    exec('x=1')\n", "def f():\n    return __import__('os')\n", "def f(x):\n    return x.__class__\n", "def f(x):\n    return getattr(x, 'a')\n",
                   "def f():\n    global z\n", "class A:\n    pass\n", "def f():\n    return compile('1', 'a', 'eval')\n", "import hashlib\nx = hashlib._hashlib\n", "async def f():\n    pass\n", "def f(:\n"]
            for src in bad:
                self.assertTrue(o18_ast_problems(src), src)
                with self.assertRaises(BridgeError):
                    o18_load_source(src)
            self.assertEqual(o18_ast_problems("import hashlib\nimport hmac\nimport base64\nimport json\nimport re\nimport math\nimport time\nimport uuid\nimport struct\nimport urllib.parse\ndef f(a):\n    return hashlib.sha256(a.encode()).hexdigest()\n"), [])

        def test_o18_runtime_namespace_is_restricted_and_runaway_code_is_stopped(self) -> None:
            ns = o18_load_source("def f():\n    return print('x')\n\ndef g():\n    while True:\n        pass\n\ndef h(a):\n    return len(a)\n")
            with self.assertRaises(NameError):
                o18_call(ns["f"])                                                                   # print is not provided
            with self.assertRaises(BridgeError):
                o18_call(ns["g"], max_steps=5000)
            before = sys.gettrace()
            self.assertEqual(o18_call(ns["h"], "abc"), 3)
            with self.assertRaises(BridgeError):
                o18_call(ns["g"], max_steps=1000)
            self.assertIs(sys.gettrace(), before)                                                   # the trace hook is restored even after a stop

        def test_o18_hash_pin_edit_uses_last_known_good_until_both_are_broken(self) -> None:
            self.assertTrue(self.run_o18()["ok"])
            tp = self.sdir() / "tokens.py"
            tp.write_text(tp.read_text() + "\n# edited by the owner\n")
            ld = o18_load(self.store, self.HOST)
            self.assertEqual((ld["use"], ld["source"], ld["revalidate"]), (True, "last_known_good", True))
            self.assertIn("edited after validation", ld["notes"][0])
            lp = self.sdir() / "lkg" / "tokens.py"
            lp.write_text(lp.read_text() + "\n# also edited\n")
            ld2 = o18_load(self.store, self.HOST)
            self.assertEqual((ld2["use"], ld2["revalidate"]), (False, True))                        # nothing trusted: classic path
            with self.assertRaises(BridgeError):
                o18_build_request(ld2, {}, {})

        def test_o18_an_edit_that_adds_forbidden_code_is_refused_even_if_the_hash_is_repinned(self) -> None:
            self.assertTrue(self.run_o18()["ok"])
            hd = safe_host_dir(self.HOST)
            tp = self.sdir() / "tokens.py"
            evil = tp.read_text() + "\nimport os\n"
            tp.write_text(evil)
            man = self.store.read(f"site_modules/{hd}/manifest.json")
            man["modules"]["tokens.py"] = hashlib.sha256(evil.encode()).hexdigest()
            self.store.write(f"site_modules/{hd}/manifest.json", man, private=True)
            ld = o18_load(self.store, self.HOST)
            self.assertEqual(ld["source"], "last_known_good")
            self.assertIn("not allowed", " ".join(ld["notes"]))

        def test_o18_changed_script_means_stale_modules_and_the_classic_path(self) -> None:
            self.assertTrue(self.run_o18()["ok"])
            ld = o18_load(self.store, self.HOST, self.f.scripts(self.f.APP.replace("mock-signing-key-91", "rotated-key-02")))
            self.assertEqual((ld["use"], ld["revalidate"]), (False, True))
            self.assertIn("stale", ld["notes"][0])
            self.assertTrue((self.sdir() / "tokens.py").is_file())                                  # nothing is deleted

        def test_o18_what_cannot_be_ported_cleanly_stays_on_the_page_tier(self) -> None:
            r = self.run_o18(specs=[self.specs[1]])                                                 # the signature has no extracted algorithm
            self.assertEqual((r["ok"], r["written"], r["verdict"]), (False, False, "page_tier"))
            self.assertIn("header.x-sig", json.dumps(r["not_ported"]))
            self.assertFalse(self.sdir().exists())
            r2 = self.run_o18(exs=self.f.site(n=2))
            self.assertFalse(r2["ok"])
            self.assertFalse(self.sdir().exists())

        def test_o18_a_failed_validation_is_written_for_inspection_but_never_promoted(self) -> None:
            tr = o18_translate(self.HOST, o17_analyze(self.exs, self.HOST, self.f.scripts(), self.specs, endpoint="POST /api/chat", input_locs=("body.$.prompt",)), self.specs, self.exs, ("body.$.prompt",))
            self.assertTrue(tr["ok"])
            files = dict(tr["files"])
            files["tokens.py"] = files["tokens.py"].replace("hashlib.sha256", "hashlib.sha1")      # a module that no longer matches the browser
            val = o18_validate(files, self.specs, self.exs, tr["endpoint"])
            self.assertFalse(val["ok"])
            o18_write(self.store, self.HOST, files, val, self.f.scripts(), self.specs, tr["endpoint"])
            self.assertFalse((self.sdir() / "lkg").exists())
            ld = o18_load(self.store, self.HOST)
            self.assertEqual(ld["use"], False)
            self.assertIn("never passed validation", ld["notes"][0])

        @unittest.skipIf(os.name == "nt", "POSIX permissions")
        def test_o18_module_files_are_private(self) -> None:
            import stat
            self.assertTrue(self.run_o18()["ok"])
            for p in (self.sdir() / "tokens.py", self.sdir() / "manifest.json", self.sdir() / "lkg" / "tokens.py"):
                self.assertEqual(stat.S_IMODE(p.stat().st_mode) & 0o077, 0, str(p))

        def test_o18_no_model_hook_and_code_is_translated_not_written_by_a_model(self) -> None:
            for fn in (o18_translate, o18_validate, o18_write, o18_load, o18_run, o18_build_request, o18_load_source):
                self.assertNotIn("ask", inspect.signature(fn).parameters)

    class TestQuickSmoke(unittest.TestCase):
        """--selftest --quick: the whole path in one go (server on a free port, one request through the mock, clean shutdown)."""
        def test_server_request_shutdown(self) -> None:
            tmp, _store, cfg, app = mk_env({"cache_seconds": 0})
            try:
                add_acct(app, "q1", "Quick", "quick.test")
                app.router._run = lambda acct, req, emit, cancel: (emit("pong"), Outcome("pong", [], "pong"))[1]   # type: ignore[assignment]
                srv = Server(app)
                try:
                    self.assertEqual(call(srv.port, "GET", "/health")[0], 200)
                    key = cfg.add_key("quick", None)["key"]
                    st, _, b = call(srv.port, "POST", "/v1/messages", {"model": "bridge-auto", "max_tokens": 50, "messages": [{"role": "user", "content": "ping"}]}, {"x-api-key": key})
                    self.assertEqual(st, 200)
                    self.assertIn("pong", b.decode("utf-8", "replace"))
                finally:
                    srv.close()
            finally:
                shutil.rmtree(tmp, ignore_errors=True)

    class TestAccessAndDashboardLog(unittest.TestCase):
        """7.30: every request leaves one line in the log file, failures say why, the dashboard can report its own errors, the file can be read back through the API."""
        def test_requests_failures_dashboard_errors_and_readback(self) -> None:
            tmp, _store, cfg, app = mk_env({"cache_seconds": 0})
            old = dict(_LOGFILE)
            try:
                lf = log_file_open(tmp / "logs")
                add_acct(app, "q1", "Quick", "quick.test")
                app.router._run = lambda acct, req, emit, cancel: (emit("pong"), Outcome("pong", [], "pong"))[1]   # type: ignore[assignment]
                srv = Server(app)
                try:
                    key = cfg.add_key("quick", None)["key"]
                    adm = {"x-admin-key": cfg["admin_key"]}
                    self.assertEqual(call(srv.port, "POST", "/v1/messages", {"model": "bridge-auto", "max_tokens": 5, "messages": [{"role": "user", "content": "SECRET-PROMPT-TEXT"}]}, {"x-api-key": key})[0], 200)
                    self.assertEqual(call(srv.port, "POST", "/v1/messages", {"model": "bridge-auto"}, {"x-api-key": "wrong"})[0], 401)
                    self.assertEqual(call(srv.port, "GET", "/api/state", None, {})[0], 401)
                    self.assertEqual(call(srv.port, "GET", "/nothing-here")[0], 404)
                    self.assertEqual(call(srv.port, "POST", "/api/clientlog", {"kind": "js_error", "msg": "boom-in-page", "src": "x.js", "line": 3, "stack": "Error: boom\n at f"}, adm)[0], 200)
                    st, _, b = call(srv.port, "GET", "/api/logfile?level=warn&tail=50&report=1", None, adm)
                    self.assertEqual(st, 200)
                    rep_ = json.loads(b)["text"]
                    self.assertIn("AI Web Bridge " + VERSION, rep_)
                    self.assertIn("boom-in-page", rep_)
                    self.assertIn("-> 401", rep_)
                finally:
                    srv.close()
                txt = lf.read_text("utf-8")
                self.assertIn("HTTP POST /v1/messages -> 200", txt)
                self.assertIn("chat request |", txt)
                self.assertIn("chat answered |", txt)
                self.assertIn("refused: bridge API key missing or wrong", txt)
                self.assertIn("refused: admin key missing or wrong", txt)
                self.assertIn("HTTP GET /nothing-here -> 404", txt)
                self.assertIn("DASHBOARD js_error: boom-in-page", txt)
                self.assertNotIn("SECRET-PROMPT-TEXT", txt)                                 # no message text is ever written
                self.assertNotIn(key, txt)
                self.assertNotIn(cfg["admin_key"], txt)
            finally:
                _LOGFILE.clear()
                _LOGFILE.update(old)
                shutil.rmtree(tmp, ignore_errors=True)

        def test_dashboard_script_reports_its_own_errors(self) -> None:
            self.assertIn("window.addEventListener('error'", DASHBOARD_HTML)
            self.assertIn("/api/clientlog", DASHBOARD_HTML)
            self.assertIn("id=\"lgcp\"", DASHBOARD_HTML)

    class TestGroupO19(unittest.TestCase):
        """O19 on mock traffic ONLY (fixtures of TestGroupO17 with browser-like identity headers added). No real site, browser or model."""
        HOST = "m19.mock17.test"
        CHROME = [("user-agent", "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36"), ("accept", "*/*"), ("accept-language", "fa-IR,fa;q=0.9,en;q=0.8"),
                  ("accept-encoding", "gzip, deflate, br"), ("sec-ch-ua", '"Chromium";v="126", "Not.A/Brand";v="24"'), ("sec-ch-ua-mobile", "?0"), ("sec-ch-ua-platform", '"Linux"'),
                  ("sec-fetch-dest", "empty"), ("sec-fetch-mode", "cors"), ("sec-fetch-site", "same-origin")]
        FIREFOX = [("user-agent", "Mozilla/5.0 (X11; Linux x86_64; rv:127.0) Gecko/20100101 Firefox/127.0"), ("accept", "*/*"), ("accept-language", "en-US,en;q=0.5"), ("accept-encoding", "gzip, deflate, br"),
                   ("sec-fetch-dest", "empty")]
        BUILT = {"header.x-client": "web-1.4", "header.x-ts": "1", "header.x-sig": "s", "header.x-pow-prefix": "p", "header.x-pow-bits": "2", "header.x-pow": "7"}

        def setUp(self) -> None:
            self.f = TestGroupO17("test_o17_the_deterministic_path_never_asks_a_model")
            self.tmp = tempfile.mkdtemp()
            self.store = Store(Path(self.tmp))
            self.specs = [self.f.sig_spec(), self.f.pow_spec()]

        def tearDown(self) -> None:
            shutil.rmtree(self.tmp, ignore_errors=True)

        def site(self, ident: Optional[List[Tuple[str, str]]]) -> List[Dict[str, Any]]:
            exs = self.f.site()
            if ident is not None:
                for e in exs:
                    if e["method"] == "POST":                       # identity headers interleaved with content-type / origin exactly like a browser sends them
                        e["req_headers"] = [list(h) for h in ident[:4]] + [["content-type", "application/json"], ["origin", "https://mock17.test"]] + [list(h) for h in ident[4:]] + e["req_headers"]
            return exs

        def run19(self, exs: List[Dict[str, Any]], env: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
            return o18_run(self.store, self.HOST, exs, self.f.scripts(), self.specs, ("body.$.prompt",), "POST /api/chat", env)

        def sdir(self) -> Path:
            return self.store.path("site_modules", safe_host_dir(self.HOST))

        def test_o19_the_identity_of_the_real_capture_is_replayed_with_the_same_set_and_order(self) -> None:
            exs = self.site(self.CHROME)
            r = self.run19(exs, {"language": "fa-IR", "languages": ["fa-IR", "fa", "en"], "platform": "Linux x86_64", "timezone": "Asia/Tehran", "locale": "fa-IR", "junk": "x"})
            self.assertTrue(r["ok"], r)
            self.assertEqual((r["identity"]["present"], r["identity"]["ok"], r["identity"]["browser"]), (True, True, "chromium"))
            self.assertEqual(r["validation"]["identity"], {"ok": True, "scenarios": 3, "passed": 3})
            ld = o18_load(self.store, self.HOST, self.f.scripts())
            self.assertTrue(ld["use"])
            sent = [(n, v) for n, v in _o19_headers([e for e in exs if e["method"] == "POST"][0])]
            got = [tuple(h) for h in o19_build_headers(ld, {"header.x-client": "web-1.4", "header.x-ts": sent[-5][1], "header.x-sig": sent[-4][1], "header.x-pow-prefix": sent[-3][1], "header.x-pow-bits": "2", "header.x-pow": sent[-1][1]})]
            self.assertEqual(got, sent)                                                             # same names, same order, same values
            ident = ld["identity"]
            self.assertEqual((ident["env"]["timezone"], ident["env"]["locale"], "junk" in ident["env"]), ("Asia/Tehran", "fa-IR", False))
            self.assertEqual(ident["order"].index("content-type"), 4)                               # captured position, not a canonical one
            man = self.store.read(f"site_modules/{safe_host_dir(self.HOST)}/manifest.json")
            self.assertIn("identity.py", man["modules"])
            self.assertEqual(man["identity"]["header_names"][0], "user-agent")
            self.assertNotIn("Chrome/126", json.dumps(man))                                         # the manifest carries names and a hash, not the values

        def test_o19_nothing_is_invented_for_a_browser_that_did_not_send_it(self) -> None:
            r = self.run19(self.site(self.FIREFOX))
            self.assertTrue(r["ok"], r)
            self.assertEqual(r["identity"]["browser"], "firefox")
            text = (self.sdir() / "identity.py").read_text()
            self.assertNotIn("sec-ch-ua", text)                                                     # a Firefox capture has no client hints: none are added
            ld = o18_load(self.store, self.HOST, self.f.scripts())
            names = [n for n, _ in o19_build_headers(ld, self.BUILT)]
            self.assertFalse(any(n.startswith("sec-ch-ua") for n in names))
            self.assertEqual(names[:2], ["user-agent", "accept"])

        def test_o19_a_mixed_or_inconsistent_capture_is_refused_not_chosen_or_rotated(self) -> None:
            exs = self.site(self.CHROME)
            posts = [e for e in exs if e["method"] == "POST"]
            posts[1]["req_headers"][0][1] = "Mozilla/5.0 (Windows NT 10.0) Firefox/128.0"
            r = self.run19(exs)
            self.assertFalse(r["ok"])
            self.assertFalse(r["written"])
            self.assertIn("different user agents", r["identity"]["reason"])
            self.assertFalse((self.sdir() / "identity.py").exists())
            exs2 = self.site(self.CHROME)
            [e for e in exs2 if e["method"] == "POST"][2]["req_headers"][2][1] = "en-US,en;q=0.9"      # same UA, another language header
            r2 = self.run19(exs2)
            self.assertFalse(r2["ok"])
            self.assertIn("differ between captures", r2["identity"]["reason"])

        def test_o19_no_user_agent_means_no_identity_and_the_native_client_refuses_to_invent_one(self) -> None:
            r = self.run19(self.site(None))
            self.assertTrue(r["ok"], r)
            self.assertEqual((r["identity"]["present"], r["identity"]["ok"]), (False, False))
            self.assertFalse((self.sdir() / "identity.py").exists())
            self.assertNotIn("identity", r["manifest"])
            ld = o18_load(self.store, self.HOST, self.f.scripts())
            self.assertTrue(ld["use"])                                                              # the O18 token path is unchanged
            with self.assertRaises(BridgeError) as cm:
                o19_build_headers(ld, self.BUILT)
            self.assertIn("does not invent", str(cm.exception))

        def test_o19_identity_module_is_hash_pinned_allow_listed_and_falls_back_to_last_known_good(self) -> None:
            self.assertTrue(self.run19(self.site(self.CHROME))["ok"])
            p = self.sdir() / "identity.py"
            p.write_text(p.read_text().replace("Chrome/126", "Chrome/999"), encoding="utf-8")        # edited after validation
            ld = o18_load(self.store, self.HOST, self.f.scripts())
            self.assertEqual((ld["use"], ld["source"]), (True, "last_known_good"))
            self.assertTrue(any("edited after validation" in n for n in ld["notes"]))
            self.assertIn("Chrome/126", json.dumps(ld["identity"]))                                 # the last-known-good identity, not the edited one
            for bad in ("import os\nIDENTITY = {}\n", "import random\nIDENTITY = {}\n", "IDENTITY = open('x').read()\n"):
                self.assertTrue(o18_ast_problems(bad), bad)
                with self.assertRaises(BridgeError):
                    o18_load_source(bad, "identity")

        def test_o19_unsafe_values_are_refused(self) -> None:
            for ua in ("Mozilla/5.0 evil\r\nX-Injected: 1", "M" * 3000):
                ident = [(ua, ) if False else ("user-agent", ua)] + [h for h in self.CHROME[1:]]
                r = self.run19(self.site(ident))
                self.assertFalse(r["ok"], ua[:20])
                self.assertIn("control characters", r["identity"]["reason"])

        def test_o19_browser_environment_is_cleaned_and_a_mismatch_is_recorded_not_fixed(self) -> None:
            self.assertEqual(o19_clean_env({"language": "en-US", "languages": ["en-US", "en"], "timezone": "Europe/Berlin", "platform": "x" * 100, "locale": "bad\nvalue", "other": 1}), {"language": "en-US", "languages": ["en-US", "en"], "timezone": "Europe/Berlin"})
            self.assertEqual(o19_clean_env("not a dict"), {})
            self.assertEqual(o19_clean_env({"languages": ["ok", 5]}), {})

            class P:
                def evaluate(self, js: str) -> Any:
                    return {"language": "fa-IR", "languages": ["fa-IR"], "platform": "Linux x86_64", "timezone": "Asia/Tehran", "locale": "fa-IR"}

            class Broken:
                def evaluate(self, js: str) -> Any:
                    raise RuntimeError("page closed")
            self.assertEqual(o19_browser_env(P())["timezone"], "Asia/Tehran")
            self.assertEqual(o19_browser_env(Broken()), {})
            r = o19_extract(self.site(self.CHROME), "POST /api/chat", self.HOST, {"language": "en-US"})
            self.assertTrue(r["ok"])
            self.assertFalse(r["identity"]["env_consistent"])                                       # navigator says en-US, the header said fa-IR: reported
            self.assertEqual(dict(r["identity"]["headers"])["accept-language"], "fa-IR,fa;q=0.9,en;q=0.8")   # and left exactly as the browser sent it

        def test_o19_secrets_are_never_part_of_the_identity_and_the_cookie_slot_keeps_its_position(self) -> None:
            secret = "S3cretValue123456"
            exs = self.site(self.CHROME)
            for e in exs:
                if e["method"] == "POST":
                    e["req_headers"].insert(6, ["cookie", f"sid={secret}"])
                    e["req_headers"].insert(7, ["authorization", f"Bearer {secret}"])
            r = o19_extract(exs, "POST /api/chat", self.HOST)
            self.assertTrue(r["ok"])
            self.assertNotIn(secret, json.dumps(r["identity"]))
            self.assertIn("cookie", r["identity"]["order"])
            self.assertNotIn("cookie", dict(r["identity"]["headers"]))
            ns = o18_load_source(_O19_BUILD_HEADERS, "protocol")
            with_cookie = ns["build_headers"](self.BUILT, r["identity"], "sid=fresh")
            without = ns["build_headers"](self.BUILT, r["identity"], None)
            self.assertEqual([h[0] for h in with_cookie].index("cookie"), r["identity"]["order"].index("cookie"))
            self.assertNotIn("cookie", [h[0] for h in without])

        def test_o19_there_is_exactly_one_identity_deterministic_and_a_new_login_replaces_it(self) -> None:
            self.assertTrue(self.run19(self.site(self.CHROME))["ok"])
            ld = o18_load(self.store, self.HOST, self.f.scripts())
            a, b = o19_build_headers(ld, self.BUILT), o19_build_headers(ld, self.BUILT)
            self.assertEqual(a, b)                                                                  # no randomisation, no per-call variation
            self.assertEqual((self.sdir() / "identity.py").read_text().count("Chrome/126"), 1)                  # one identity value stored once (the name also appears in `order`)
            newer = [("user-agent", "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/127.0.0.0 Safari/537.36")] + self.CHROME[1:]
            r = self.run19(self.site(newer))
            self.assertTrue(r["ok"], r)
            self.assertTrue(r["manifest"]["identity"]["changed_since_previous"])                    # the browser itself was updated; recorded as an event, not a rotation
            ld2 = o18_load(self.store, self.HOST, self.f.scripts())
            self.assertIn("Chrome/127", json.dumps(ld2["identity"]))
            self.assertNotIn("Chrome/126", (self.sdir() / "identity.py").read_text())               # the old identity is not kept in a pool

        def test_o19_validation_fails_when_the_replay_would_differ_from_the_browser(self) -> None:
            exs = self.site(self.CHROME)
            r = self.run19(exs)
            self.assertTrue(r["ok"], r)
            files = {n: (self.sdir() / n).read_text() for n in ("tokens.py", "protocol.py", "identity.py")}
            files["identity.py"] = files["identity.py"].replace("Chrome/126", "Chrome/100")
            v = o19_validate(files, exs, "POST /api/chat")
            self.assertFalse(v["ok"])
            self.assertEqual(v["passed"], 0)
            files2 = dict(files, **{"identity.py": (self.sdir() / "identity.py").read_text(), "protocol.py": files["protocol.py"].replace('res.append([name, ident[name]])', 'res.append([name, ident[name].lower()])')})
            self.assertFalse(o19_validate(files2, exs, "POST /api/chat")["ok"])

    class TestGroupO8(unittest.TestCase):
        """O8 on a mock site ONLY: an in-process chat server that checks the real HMAC signature, and a loopback server for the real transport. No real site, browser or model."""
        HOST = "m8.mock17.test"
        STREAM = {"format": "sse", "text_paths": ["delta"], "cumulative": False, "ignore_values": []}

        class Site:
            def __init__(self, truncate_over: int = 0, single_event: bool = False, fail_status: int = 0, no_tools: bool = False, many: int = 400):
                self.truncate_over, self.single_event, self.fail_status, self.no_tools, self.many = truncate_over, single_event, fail_status, no_tools, many
                self.calls: List[Dict[str, Any]] = []
                self.convs: Dict[str, str] = {}
                self.produced, self.closed = 0, 0
                self.issued: Set[str] = set()

            def reply(self, prompt: str, conv: str) -> Tuple[str, str]:
                if self.truncate_over and len(prompt) > self.truncate_over:
                    prompt = prompt[:self.truncate_over]
                m = re.search(r"Remember the code (\w+)\.", prompt)
                if m:
                    conv = conv or f"c{len(self.convs) + 1}"
                    self.convs[conv] = m.group(1)
                    return "OK", conv
                if "What was the code" in prompt:
                    return self.convs.get(conv, "I do not know"), conv
                m = re.search(r"Tool result for battery_echo: (\w+)\.", prompt)
                if m:
                    return m.group(1), conv
                if prompt.startswith("Answer only with <tool_call>"):
                    return ("I will not call tools" if self.no_tools else prompt[len("Answer only with "):]), conv
                m = re.search(r"token (bm\w+)", prompt) or re.search(r"word (bm\w+)", prompt)
                if m and "many times" in prompt:
                    return " ".join([m.group(1)] * self.many), conv
                if m and "Count slowly" in prompt:
                    return " ".join([m.group(1)] * 3), conv
                if m and "single word" in prompt:
                    return m.group(1), conv
                return "I cannot see a token", conv

            def http(self, method: str, url: str, headers: List[List[str]], body: Optional[bytes], timeout: float) -> Dict[str, Any]:
                self.calls.append({"method": method, "url": url, "headers": [tuple(h) for h in headers], "body": body})
                if self.fail_status:
                    return {"status": self.fail_status, "headers": [("content-type", "application/json")], "chunks": iter([b'{"error":"boom"}']), "close": lambda: None}
                if method == "GET":                                                                # the proof-of-work challenge: a fresh prefix per request
                    prefix = f"pfx{len(self.issued) + 1}"
                    self.issued.add(prefix)
                    return {"status": 200, "headers": [("content-type", "application/json")], "chunks": iter([json.dumps({"prefix": prefix, "bits": "2"}).encode()]), "close": lambda: None}
                hd = dict(headers)
                pre = hd.get("x-pow-prefix", "")
                if pre not in self.issued or hd.get("x-pow") != o17_pow_solve(pre, 2):
                    return {"status": 403, "headers": [], "chunks": iter([b'{"error":"bad proof of work"}']), "close": lambda: None}
                self.issued.discard(pre)                                                           # a challenge is single-use
                d = json.loads(body or b"{}")
                want = hmac.new(TestGroupO17.SECRET.encode(), f"{hd.get('x-ts')}.{d.get('prompt')}".encode(), hashlib.sha256).hexdigest()
                if hd.get("x-sig") != want:
                    return {"status": 403, "headers": [], "chunks": iter([b'{"error":"bad signature"}']), "close": lambda: None}
                if d.get("prompt") == "":
                    return {"status": 400, "headers": [], "chunks": iter([b'{"error":"empty prompt"}']), "close": lambda: None}
                text, conv = self.reply(d["prompt"], d.get("conversation_id") or "")
                words = [text] if self.single_event else [w if i == 0 else " " + w for i, w in enumerate(text.split(" "))]
                site = self

                def gen() -> Iterator[bytes]:
                    yield ("data: " + json.dumps({"conv": conv}) + "\n\n").encode()
                    for w in words:
                        site.produced += 1
                        yield ("data: " + json.dumps({"delta": w}) + "\n\n").encode()
                    yield b"data: [DONE]\n\n"

                def close() -> None:
                    site.closed += 1
                return {"status": 200, "headers": [("content-type", "text/event-stream")], "chunks": gen(), "close": close}

        class Ref:
            """The page tier, as the battery sees it: same question, an answer from its own conversation."""
            def __init__(self, pad: int = 0, ok: bool = True):
                self.site, self.pad, self.ok = TestGroupO8.Site(), pad, ok

            def ask(self, prompt: str, conv: Optional[str] = None, cancel: Any = None) -> Dict[str, Any]:
                text, c = self.site.reply(prompt, conv or "")
                return {"ok": self.ok, "complete": self.ok, "text": text + "x" * self.pad, "conv": c}

        def setUp(self) -> None:
            self.f = TestGroupO17("test_o17_the_deterministic_path_never_asks_a_model")
            self.tmp = tempfile.mkdtemp()
            self.store = Store(Path(self.tmp))
            exs = self.f.site()
            for e in exs:
                if e["method"] == "POST":
                    j = json.loads(e["req_body"]["text"])
                    j["conversation_id"] = f"conv-{e['id']}"
                    e["req_body"]["text"] = json.dumps(j)
                    e["req_headers"] = [list(h) for h in TestGroupO19.CHROME[:4]] + [["content-type", "application/json"], ["origin", "https://mock17.test"]] + [list(h) for h in TestGroupO19.CHROME[4:]] + e["req_headers"]
            self.exs = exs
            r = o18_run(self.store, self.HOST, exs, self.f.scripts(), [self.f.sig_spec(), self.f.pow_spec()], ("body.$.prompt", "body.$.conversation_id"), "POST /api/chat")
            assert r["ok"], r
            self.loaded = o18_load(self.store, self.HOST, self.f.scripts())
            self.t = [0.0]
            self.n = [0]

        def tearDown(self) -> None:
            shutil.rmtree(self.tmp, ignore_errors=True)

        def tick(self) -> float:
            self.t[0] += 0.01
            return self.t[0]

        def nonce(self) -> str:
            self.n[0] += 1
            return f"bm{self.n[0]:08x}"

        def test_o29_experiment_sends_one_synthetic_turn_with_only_the_requested_part_changed(self) -> None:
            class Tx:
                skip_headers: set = set()
                def __init__(self) -> None: self.calls = []
                def request(self, method: str, url: str, headers: Dict[str, str], body: Optional[bytes], timeout: float = 60):
                    self.calls.append((method, url, dict(headers), body))
                    return 200, {"content-type": "text/event-stream"}, iter([b'data: {"delta":"OK"}\n\n'])
            recipe = {"chat": {"method": "POST", "url": "https://mock17.test/api/chat", "headers": {"x-proof": "observed"},
                               "body_kind": "json", "body": {"prompt": "{{prompt}}", "proof": "captured"}},
                      "stream": {"format": "sse", "text_paths": ["delta"], "cumulative": False, "ignore_values": []}}
            tx = Tx()
            result = o29_safe_experiment(recipe, {"cookies": [], "auth": {}}, "change_value",
                {"loc": "body.$.proof", "expected": "captured"}, self.HOST, "POST /api/chat", {"mock17.test"},
                transport=tx, guard=lambda u: u)
            self.assertTrue(result["accepted"], result)
            self.assertEqual(result["requests"], 1)
            self.assertEqual(len(tx.calls), 1)
            sent = json.loads(tx.calls[0][3].decode())
            self.assertEqual(sent, {"prompt": "Reply with exactly the word OK.", "proof": "bridge-o29-invalid"})
            self.assertNotIn("captured", tx.calls[0][3].decode())

        def test_o29_experiment_refuses_setup_and_uncaptured_hosts_without_sending(self) -> None:
            class Tx:
                skip_headers: set = set()
                calls = 0
                def request(self, *args: Any, **kwargs: Any): self.calls += 1; raise AssertionError("must not send")
            base = {"chat": {"method": "POST", "url": "https://mock17.test/api/chat", "headers": {}, "body_kind": "json", "body": {"prompt": "{{prompt}}"}},
                    "stream": {"format": "sse", "text_paths": ["delta"], "cumulative": False, "ignore_values": []}}
            tx = Tx()
            setup = o29_safe_experiment(dict(base, pre=[{}]), {}, "omit_header", {"loc": "header.x"}, self.HOST,
                "POST /api/chat", {"mock17.test"}, transport=tx, guard=lambda u: u)
            self.assertFalse(setup["accepted"])
