        def test_o8_native_client_builds_the_request_from_the_modules_and_replays_the_captured_header_order(self) -> None:
            site = TestGroupO8.Site()
            r = self.client(site).ask("Reply with the single word bm0000abcd and nothing else.")
            self.assertTrue(r["ok"] and r["complete"], r)
            self.assertEqual(r["text"], "bm0000abcd")
            self.assertEqual([c["method"] for c in site.calls], ["GET", "POST"])                    # the challenge request is made by the client itself
            self.assertEqual([n for n, _ in site.calls[0]["headers"]], [n for n, _ in TestGroupO19.CHROME])   # and carries the identity headers only, as captured
            c = site.calls[1]
            self.assertEqual((c["method"], c["url"]), ("POST", "https://mock17.test/api/chat"))
            names = [n for n, _ in c["headers"]]
            sent = [n for n, _ in _o19_headers([e for e in self.exs if e["method"] == "POST"][0]) if n not in ("host", "content-length", "connection")]
            self.assertEqual(names, sent)                                                           # the browser's set and order (O19)
            self.assertEqual(json.loads(c["body"]), {"prompt": "Reply with the single word bm0000abcd and nothing else.", "model": "m-fast", "conversation_id": ""})
            self.assertTrue(r["first_byte_ms"] is not None and r["latency_ms"] >= r["first_byte_ms"] > 0)   # measured, not invented
            self.assertEqual(r["deltas"], 1)

