        def test_o9_o8_validation_uses_the_real_refresh_and_two_independent_runs_promote(self) -> None:
            f, site, rs, cl = self.f8()
            ref = O9Refresher(dict(self.SPEC), [list(h) for h in TestGroupO19.CHROME], self.cookies(rs), {}, http=cl.http, guard=lambda u: u, client=cl)
            acct: Dict[str, Any] = {"id": "a1"}
