        # -- O9.2 browser lifecycle
        def test_o9_a_browser_opens_only_for_a_permitted_reason_within_its_budget_and_closes_by_the_idle_timer(self) -> None:
            log: List[str] = []
            t = [0.0]
            br = O9Browsers(lambda aid, reason: TestGroupO9.FakeBrowser(log, aid), idle=20.0, max_open=1, clock=lambda: t[0])
            with self.assertRaises(BridgeError):
                br.acquire("a1", "chat_request")                                                        # a normal request never opens a browser
            h = br.acquire("a1", "refresh")
            self.assertEqual(br.snapshot()["open"][0]["reason"], "refresh")
            with self.assertRaises(BridgeError) as cm:
                br.acquire("a2", "repair")                                                              # budget: one at a time
            self.assertEqual(cm.exception.status, 429)
            self.assertIs(br.acquire("a1", "refresh"), h)                                               # the same account shares the open browser
            br.release("a1")
            br.release("a1")
            self.assertEqual(log, [])                                                                   # idle, but the timer has not run out yet
            t[0] = 19.9
            self.assertEqual(br.reap(), [])
            t[0] = 20.0
            self.assertEqual((br.reap(), log, br.snapshot()["open"]), (["a1"], ["close:a1"], []))
            self.assertEqual([e["event"] for e in br.snapshot()["events"]], ["refused", "launched", "refused", "closed"])
            br.run("a2", "repair", lambda h_: None)                                                     # run(): closed at once (linger 0)
            self.assertEqual((log[-1], br.snapshot()["open"]), ("close:a2", []))
            with self.assertRaises(ValueError):
                br.run("a3", "recover_login", lambda h_: (_ for _ in ()).throw(ValueError("boom")))
            self.assertEqual(log[-1], "close:a3")                                                       # also closed when the work fails: no leak
            br.acquire("a4", "refresh")
            br.close_all()
            self.assertEqual((log[-1], br.snapshot()["open"]), ("close:a4", []))

        def test_o9_no_browser_process_exists_when_idle_and_relaunching_leaves_none_behind_measured_in_the_process_table(self) -> None:
            if not os.path.isdir("/proc/self") and not shutil.which("ps"):
                self.skipTest("no process table on this system")

            class Proc:
                def __init__(self) -> None:
                    self.p = subprocess.Popen([sys.executable, "-c", "import time; time.sleep(60)", "--fake-chromium-o9", "x" * 20000])
                    self.pid = self.p.pid

                def close(self) -> None:
                    self.p.terminate()
                    self.p.wait(10)
            br = O9Browsers(lambda aid, reason: Proc(), idle=0.0, max_open=1)
            before = o9_measure()
            self.assertEqual((before["browser_processes"], before["browser_rss_kb"]), (0, 0))          # stable + idle: none (also none of this test's own)
            self.assertIsInstance(before["bridge_rss_kb"], int)
            seen: List[Dict[str, Any]] = []
            for _ in range(2):                                                                          # launch for a refresh, then again for a repair: closed each time
                br.run("a1", "refresh" if not seen else "repair", lambda h: seen.append(o9_measure()))
                self.assertEqual(o9_measure()["browser_processes"], 0)
            self.assertTrue(all(m["browser_processes"] == 1 and m["browser_rss_kb"] > 0 for m in seen), seen)   # while open it WAS visible in the table, with a measured RSS
            self.assertEqual(o9_measure()["pids"], [])
            tab = [{"pid": 1, "ppid": 0, "rss_kb": 1, "cmd": "init"}, {"pid": 2, "ppid": 1, "rss_kb": 50, "cmd": "python bridge.py"}, {"pid": 3, "ppid": 2, "rss_kb": 700, "cmd": "/x/Chromium --headless"},
                   {"pid": 4, "ppid": 3, "rss_kb": 300, "cmd": "/x/chrome --type=renderer"}, {"pid": 5, "ppid": 1, "rss_kb": 900, "cmd": "chrome (the owner's own browser)"}]
            self.assertEqual([p["pid"] for p in o9_browser_procs(2, table=tab)], [3, 4])               # only descendants of the bridge count, never the owner's own browser

        # -- O9.3 needs_login card
