        # -- O9.4 repair loop
        def stable_account(self) -> Tuple[Any, Any, Any, Dict[str, Any], Callable[[float], Dict[str, Any]]]:
            f, site, rs, cl = self.f8()
            acct: Dict[str, Any] = {"id": "r1"}
            lc_init(acct, "learning", "test")
            for at in (1000.0, 1300.0):
                out = o8_step(f.store, f.HOST, acct, cl, TestGroupO8.Ref(), lambda: True, clock=lambda at=at: at, nonce=f.nonce, long_chars=500)
            assert out["status"] == "promoted", out
            tick = lambda at, relearn: o9_repair_tick(f.store, f.HOST, acct, relearn, cl, TestGroupO8.Ref(), lambda: True, clock=lambda: at, nonce=f.nonce, long_chars=500)       # noqa: E731
            return f, site, cl, acct, tick

        def test_o9_drift_drops_a_stable_account_to_the_fallback_and_the_repair_returns_it_only_through_fresh_validation(self) -> None:
            f, site, cl, acct, tick = self.stable_account()
            self.assertEqual(tick(2000.0, lambda: True)["status"], "stable")                           # nothing to repair while stable
            rec = o9_on_drift(f.store, f.HOST, acct, {"kind": "recipe_drift", "token": "abcdefghijklmnop12345"})
            self.assertEqual((lc_state(acct), rec["status"]), ("degraded_fallback", "pending"))        # the classic path keeps serving
            self.assertNotIn("abcdefghijklmnop12345", json.dumps(acct["lifecycle"]))
            v = f.store.read(f"site_modules/{safe_host_dir(f.HOST)}/validation.json", {})
            self.assertEqual((v["runs"], "promoted" in v), ([], False))                                # the old validation no longer counts
            calls: List[int] = []
            fail = lambda: calls.append(1) or False                                                     # noqa: E731
            r1 = tick(3000.0, fail)
            self.assertEqual((r1["status"], r1["attempt"], lc_state(acct), r1["retry_at"]), ("failed", 1, "degraded_fallback", 3120.0))
            self.assertEqual(tick(3100.0, fail)["status"], "waiting")                                   # backoff: no hot loop
            self.assertEqual(calls, [1])
            ok = lambda: calls.append(2) or True                                                        # noqa: E731
            self.assertEqual((tick(3200.0, ok)["status"], lc_state(acct)), ("relearned", "repairing"))
            self.assertEqual(tick(3300.0, ok)["validation"]["status"], "pending")                       # one run is not enough: still not stable
            self.assertEqual(lc_state(acct), "validating")
            last = tick(3600.0, ok)
            self.assertEqual((last["status"], last["validation"]["status"], lc_state(acct)), ("validating", "promoted", "stable_direct"))
            self.assertEqual(f.store.read(_o9_rel(f.HOST), {})["status"], "done")
            self.assertEqual(calls, [1, 2])                                                             # re-learn ran exactly twice: the loop did not spin

        def test_o9_the_repair_is_bounded_asks_the_owner_when_exhausted_and_needs_login_stops_it(self) -> None:
            f, site, cl, acct, tick = self.stable_account()
            o9_on_drift(f.store, f.HOST, acct, "shape changed")
            at, n = 10000.0, [0]
            for i in range(O9_REPAIR_ATTEMPTS):
                out = tick(at, lambda: n.__setitem__(0, n[0] + 1) or False)
                self.assertEqual(out["status"], "failed")
                at = out["retry_at"] + 1
            self.assertEqual(n[0], O9_REPAIR_ATTEMPTS)
            self.assertEqual(tick(at, lambda: True)["status"], "exhausted")                             # no further attempt, however often it is ticked
            self.assertEqual(tick(at + 1e6, lambda: True)["status"], "exhausted")
            self.assertEqual((n[0], lc_state(acct), acct["card_action"]["kind"]), (O9_REPAIR_ATTEMPTS, "degraded_fallback", "relearn"))
            f2, site2, cl2, acct2, tick2 = self.stable_account()
            o9_on_drift(f2.store, f2.HOST, acct2, "shape changed")
            out2 = tick2(20000.0, lambda: (_ for _ in ()).throw(BridgeError("the site asks for a login", "auth", 401)))
            self.assertEqual((out2["status"], lc_state(acct2), acct2["card_action"]["kind"]), ("needs_login", "needs_login", "relogin"))
            self.assertEqual(tick2(30000.0, lambda: True)["status"], "needs_login")                    # the owner is needed: the loop does not retry on its own

        def test_o9_a_repair_that_does_not_validate_counts_as_an_attempt_and_the_state_survives_a_restart(self) -> None:
            f, site, cl, acct, tick = self.stable_account()
            o9_on_drift(f.store, f.HOST, acct, "shape changed")
