            r2["state"] = {"cid": {"kind": "response", "path": "v.conv"}}
            n3, l3, _ = native_data_from_recipe(r2)
            self.assertEqual((n3["conv_loc"], n3["conv_path"], l3), ("body.$.conv", "v.conv", ("body.$.prompt", "body.$.conv")))
