    class TestGroupO21Link(unittest.TestCase):
        """7.27 step (b) (mock only): O21 extractions of standard hash/HMAC functions become O17 specs, are bound to request locations by exhaustive search over the recorded requests, and only
        trusted if they reproduce every capture uniquely. No parser, browser, site or model is involved (the extraction records are written by hand in the analyzer's format)."""
        URL = "https://mock17.test/app.js"

        def setUp(self) -> None:
            self.f = TestGroupO17("test_o17_the_deterministic_path_never_asks_a_model")
            self.key = TestGroupO17.SECRET

        def script(self, fn: str = "function sign(ts, body) { return CryptoJS.HmacSHA256(ts + \".\" + body, SECRET).toString(); }") -> Tuple[str, Dict[str, Any]]:
            text = f'const SECRET = "{self.key}";\n// padding\n{fn}\n'
            name = re.search(r"(?:function|const)\s+(\w+)", fn).group(1)
            ex = {"script": self.URL, "sha256": "S", "name": name, "text": fn, "line_from": 3, "line_to": 3,
                  "deps": [{"name": "SECRET", "text": f'const SECRET = "{self.key}";', "line_from": 1, "line_to": 1}]}
            src = {"call_sites": [{"sha256": "S", "headers": [{"name": "x-sig", "class": "computed", "value": f"<computed:{name}(ts, body)>"}]}], "extractions": [ex]}
            return text, src

        def derive(self, fn: Optional[str] = None, key_in_script: Optional[str] = None, exs: Any = None) -> Tuple[List[Dict[str, Any]], List[str], str]:
            text, src = self.script(fn) if fn else self.script()
            if key_in_script:
                text = text.replace(self.key, key_in_script)
            specs, notes = o21_specs(src, exs or self.f.site(pow_=False), [{"url": self.URL, "text": text}], "POST /api/chat")
            return specs, notes, text

        def test_a_standard_hmac_function_becomes_a_spec_that_reproduces_every_capture_and_goes_all_the_way_to_native_data(self) -> None:
            specs, notes, text = self.derive()
            self.assertEqual(len(specs), 1, notes)
            sp = specs[0]
            self.assertEqual((sp["loc"], sp["provenance"]["kind"], sp["provenance"]["lines"]), ("header.x-sig", "script", [1, 3]))
            self.assertEqual(sp["expr"], {"hmac_sha256": {"key": {"lit": self.key}, "msg": {"cat": [{"ref": "header.x-ts"}, {"lit": "."}, {"ref": "body.$.prompt"}]}}, "enc": "hex"})
            exs = self.f.site(pow_=False)
            self.assertTrue(o17_validate_spec(sp, {self.URL: text})["ok"])
            self.assertTrue(o17_cross_check(sp, exs, "POST /api/chat")["trusted"])
            an = o17_analyze(exs, "mock17.test", [{"url": self.URL, "text": text}], specs, endpoint="POST /api/chat", input_locs=("body.$.prompt",))
            self.assertEqual(an["verdict"], "direct_candidate", an)
            tmp = tempfile.mkdtemp()
            try:
                st = Store(Path(tmp))
                nat = dict(TestGroupO827.NATIVE, conv_loc="", conv_path="")
                r = o18_run(st, "mock17.test", exs, [{"url": self.URL, "text": text}], specs, ("body.$.prompt",), "POST /api/chat", None, nat)
                self.assertTrue(r["ok"] and r["native_problem"] == "", r)
                self.assertTrue(o18_load(st, "mock17.test", [{"url": self.URL, "text": text}])["native"])
            finally:
                shutil.rmtree(tmp, ignore_errors=True)

        def test_nothing_is_guessed_custom_algorithms_wrong_constants_and_ambiguous_bindings_stay_unknown(self) -> None:
            specs, notes, _t = self.derive("function sign(ts, body) { return mix(ts + body); }")
            self.assertEqual((specs, "not portable" in notes[0]), ([], True))                       # a home-made algorithm is not translated
            specs, notes, _t = self.derive("function sign(ts, body) { return CryptoJS.HmacSHA256(ts + body, SECRET).toString(); }")
            self.assertEqual((specs, "no binding" in notes[0]), ([], True))                         # a different separator: no binding reproduces the captures
            text, src = self.script()
            src["extractions"][0]["deps"][0]["text"] = 'const SECRET = "another-key";'
            specs, notes = o21_specs(src, self.f.site(pow_=False), [{"url": self.URL, "text": text}], "POST /api/chat")
            self.assertEqual((specs, "no binding" in notes[0]), ([], True))                         # the constant is read from the extraction, never filled in
            dup = self.f.site(pow_=False, extra=lambda k: [("x-ts-copy", str(int((1_900_000_000.0 + 2 * k + 1) * 1000)))])
            specs, notes, _t = self.derive(exs=dup)
            self.assertEqual((specs, "ambiguous" in notes[0]), ([], True))                          # two request values explain the output equally: not guessed
            specs, notes = o21_specs(src, self.f.site(n=2, pow_=False), [{"url": self.URL, "text": text}], "POST /api/chat")
            self.assertEqual((specs, "capture(s)" in notes[0]), ([], True))                         # fewer than 3 captures
            self.assertEqual(o21_specs(None, [], [], None), ([], []))

        def test_the_closed_grammar_accepts_hash_shapes_and_refuses_everything_else(self) -> None:
            p = lambda e, ps=("a", "b"), c=None: _o21_parse_return(e, list(ps), c or {})          # noqa: E731
            self.assertEqual(p("CryptoJS.SHA256(a + `-${b}`).toString(CryptoJS.enc.Base64)"), {"sha256": {"cat": [{"param": "a"}, {"lit": "-"}, {"param": "b"}]}, "enc": "b64"})
            self.assertEqual(p("btoa(a + ':' + K)", c={"K": "k"}), {"b64": {"cat": [{"param": "a"}, {"lit": ":"}, {"lit": "k"}]}})
            self.assertEqual(p("sha256(a)"), {"sha256": {"param": "a"}, "enc": "hex"})
            for bad in ("evil(a)", "a.length", "CryptoJS.HmacSHA256(a)", "a + unknown", "'x\\ny'", "sha256(a).slice(0, 8)", "CryptoJS.SHA256(a).toString(CryptoJS.enc.Latin1)"):
                with self.assertRaises(ValueError, msg=bad):
                    p(bad)
            self.assertEqual(_o21_params_and_return("const f = (a, b) => sha256(a + b);")[0], ["a", "b"])
            self.assertEqual(_o21_params_and_return("async function f(a){ return a; }")[1], "a")
            with self.assertRaises(ValueError):
                _o21_params_and_return("function f(a){ const x = a; return x; }")

    class TestGroupO14(unittest.TestCase):
        """O14 on mocks ONLY: per-account model choice after discovery (default / fixed / policy), persistence, re-resolution by native id after a
        refresh or a repair, routing that honours the choice, and the admin API. No real site, login, browser or model was exercised."""
        HOST = "o14.test"
        RECIPE = dict(mk_recipe("o14.test", {"model": "{{model}}", "q": "{{prompt}}"}), model_select={"kind": "template", "where": "body.model", "slot": ["body", "model"], "default": "m-a"})

        def setUp(self) -> None:
            self.tmp, self.store, self.cfg, self.app = mk_env({"cache_seconds": 0})
            self.acc, self.eng = self.app.acc, self.app.engine
            self.a1 = add_acct(self.app, "a1", "Alpha", self.HOST)
            self.b2 = add_acct(self.app, "b2", "Beta", "beta14.test")
            self.store.write(f"recipes/{self.HOST}.json", self.RECIPE)
            self.seen: List[Tuple[str, str, str]] = []

            def fake_run(acct: Dict[str, Any], req: NormReq, emit: Callable[[str], None], cancel: threading.Event) -> Outcome:
                self.seen.append((acct["id"], req.model, req.variant_native))
                emit("ok")
                return Outcome("ok", [], "ok")
            self.app.router._run = fake_run                                  # type: ignore[assignment]

        def tearDown(self) -> None:
            shutil.rmtree(self.tmp, ignore_errors=True)

        @staticmethod
        def var(nid: str, mode: str = "default", **kw: Any) -> ModelVariant:
            caps = norm_caps(kw.pop("caps", {}))
            return ModelVariant(id=make_variant_id(nid, nid, mode), display=nid.upper(), native_id=nid, mode=mode, capabilities=caps, source="site_network",
                                discovered_at=1.0, verified_at=1.0, status=kw.pop("status", "available"), confidence="observed", **kw)

        def catalog(self, aid: str, variants: List[ModelVariant]) -> None:
            cat = new_catalog(aid)
            cat["variants"] = [v.to_dict() for v in variants]
            cat["status"] = "fresh"
            self.acc.save_catalog(aid, cat)

        def three(self) -> List[ModelVariant]:
            vs = [self.var("m-a"), self.var("m-b", caps={"image_input": "supported"}), self.var("m-c", caps={"image_input": "unsupported"})]
            self.catalog("a1", vs)
            return vs

        def codes(self, rid: str) -> List[str]:
            r = self.eng.assess(rid, {"name": "t", "kind": "auto"}, {"capabilities": [], "tokens": 0, "max_tokens": 0}, "", set(), default_routing(), None)
            return [c for c, _d in r["codes"]]

        # -- the selector exists only when there is something real to choose
        def test_selector_is_absent_for_one_model_no_mechanism_or_no_discovery(self) -> None:
            sel = self.acc.o14_view("a1")["selector"]
            self.assertEqual((sel["present"], sel["options"], sel["discovered"]), (False, [], 0))
            self.assertIn("no models were discovered", sel["reason"])
            self.catalog("a1", [self.var("only-one")])
            sel = self.acc.o14_view("a1")["selector"]
            self.assertEqual((sel["present"], sel["count"], sel["options"]), (False, 1, []))        # one model: absent, not faked
            self.assertIn("nothing to choose", sel["reason"])
            self.three()
            self.assertEqual([o["id"] for o in self.acc.o14_view("a1")["selector"]["options"]], ["m-a", "m-b", "m-c"])
            self.catalog("b2", [self.var("x-1"), self.var("x-2")])                                  # b2 has no recipe -> no learned selection mechanism
            sel = self.acc.o14_view("b2")["selector"]
            self.assertEqual((sel["present"], sel["discovered"], sel["count"]), (False, 2, 0))
            self.assertIn("no way to select", sel["reason"])
            with self.assertRaises(BridgeError) as cx:
                self.acc.set_model_choice("b2", {"mode": "fixed", "variant": "x-1"})
            self.assertEqual(cx.exception.status, 409)
            self.catalog("a1", [self.var("m-a"), self.var("m-gone", status="unavailable")])         # an unavailable variant is not an option
            self.assertFalse(self.acc.o14_view("a1")["selector"]["present"])

        def test_validation_refuses_anything_that_cannot_be_selected(self) -> None:
            self.three()
            bad = [({"mode": "nope"}, 400), ("x", 400), ({"mode": "fixed"}, 400), ({"mode": "fixed", "variant": "ghost"}, 400),
                   ({"mode": "policy"}, 400), ({"mode": "policy", "prefer": ["ghost"]}, 400), ({"mode": "policy", "require": ["telepathy"]}, 400),
                   ({"mode": "policy", "prefer": ["m-a"], "fallback": "sometimes"}, 400), ({"mode": "policy", "prefer": [f"m-{i}" for i in range(21)]}, 400)]
            for data, code in bad:
                with self.assertRaises(BridgeError) as cx:
                    self.acc.set_model_choice("a1", data)
                self.assertEqual(cx.exception.status, code, data)
            self.assertNotIn("model_choice", self.a1)                                                # nothing half-stored
            with self.assertRaises(BridgeError) as cx:
                self.acc.set_model_choice("zz", {"mode": "default"})
            self.assertEqual(cx.exception.status, 404)

        # -- fixed choice: persisted, used by routing, never overriding an explicit route
        def test_fixed_choice_persists_and_routing_sends_the_native_id(self) -> None:
            self.three()
            v = self.acc.set_model_choice("a1", {"mode": "fixed", "variant": "m-b"})
            self.assertEqual((v["choice"]["mode"], v["choice"]["variant"], v["effective"]["status"], v["effective"]["variant"]), ("fixed", "m-b", "ok", "m-b"))
            self.assertEqual(v["effective"]["native_id"], "m-b")
            acc2 = Accounts(self.store, self.cfg)                                                   # a restart: it came from accounts.json
            self.assertEqual(acc2.get("a1")["model_choice"]["variant"], "m-b")
            self.assertEqual(acc2.o14_effective("a1")["variant"]["id"], "m-b")
            self.app.router.handle(normalize_anthropic({"model": "acct:a1", "max_tokens": 10, "messages": [{"role": "user", "content": "hi"}]}), lambda t: None, "", threading.Event(), scope="k")
            self.assertEqual(self.seen[-1][0::2], ("a1", "m-b"))                                    # the chosen variant's native id is what the backend gets
            r = self.eng.assess("acct:a1", {"name": "t", "kind": "auto"}, {"capabilities": [], "tokens": 0, "max_tokens": 0}, "", set(), default_routing(), None)
            self.assertEqual((r["ok"], r["variant"]["id"]), (True, "m-b"))
            self.assertTrue(any("chosen by the owner" in f or "chosen by the owner's" in f for f in r["flags"]))
            self.app.router.handle(normalize_anthropic({"model": "acct:a1/model:m-c", "max_tokens": 10, "messages": [{"role": "user", "content": "hi"}]}), lambda t: None, "", threading.Event(), scope="k")
            self.assertEqual(self.seen[-1][0::2], ("a1", "m-c"))                                    # an explicit variant route is never overridden
            self.app.router.handle(normalize_anthropic({"model": "acct:b2", "max_tokens": 10, "messages": [{"role": "user", "content": "hi"}]}), lambda t: None, "", threading.Event(), scope="k")
            self.assertEqual(self.seen[-1][0::2], ("b2", ""))                                       # another account is untouched
            self.assertEqual(self.acc.set_model_choice("a1", {"mode": "default"})["choice"], {"mode": "default"})
            self.assertNotIn("model_choice", self.a1)                                                # absent = the site's own default
            self.app.router.handle(normalize_anthropic({"model": "acct:a1", "max_tokens": 10, "messages": [{"role": "user", "content": "hi"}]}), lambda t: None, "", threading.Event(), scope="k")
            self.assertEqual(self.seen[-1][0::2], ("a1", ""))

        # -- A2: survives a repair / refresh by native id; never substitutes another model
        def test_choice_is_re_resolved_by_native_id_after_a_refresh_and_after_a_repair(self) -> None:
            self.three()
            self.acc.set_model_choice("a1", {"mode": "fixed", "variant": "m-b"})
            renamed = ModelVariant(id="site-renamed-b", display="B (new label)", native_id="m-b", capabilities=norm_caps({}), source="site_network", status="available", confidence="observed")
            self.acc.discover_hook = lambda a, ui: ([self.var("m-a"), renamed, self.var("m-c")], "site_network")
            self.acc.refresh_catalog("a1", "test", force=True)
            ch = self.acc.get("a1")["model_choice"]
            self.assertEqual((ch["variant"], ch["status"], ch["display"]), ("site-renamed-b", "ok", "B (new label)"))
            ev = [e for e in ch["events"] if e["type"] == "re_resolved"]
            self.assertEqual((len(ev), ev[0]["from"], ev[0]["to"], ev[0]["how"]), (1, "m-b", "site-renamed-b", "native_id"))
            self.assertEqual(self.acc.o14_effective("a1")["variant"]["native_id"], "m-b")
            # a repair that stores a recipe whose selection mechanism now lives elsewhere: the choice is re-resolved on that host, not forgotten
            n = len(ch["events"])
            moved = dict(self.RECIPE, model_select={"kind": "template", "where": "body.m", "slot": ["body", "m"], "default": "m-a"})
            self.acc.store_recipe(moved, {"ok": True})
            self.assertEqual(self.acc.get("a1")["model_choice"]["status"], "ok")
            self.assertEqual(len(self.acc.get("a1")["model_choice"]["events"]), n)                  # nothing changed -> no event spam
            # the model disappears: unresolved, the account is excluded for acct:<id>, and NOTHING else is substituted
            self.acc.discover_hook = lambda a, ui: ([self.var("m-a"), self.var("m-c")], "site_network")
            self.acc.refresh_catalog("a1", "test", force=True)
            ch = self.acc.get("a1")["model_choice"]
            self.assertEqual(ch["status"], "unresolved")
            self.assertIn("no longer offered", ch["status_reason"])
            self.assertEqual(ch["events"][-1]["type"], "unresolved")
            self.assertEqual(self.codes("acct:a1"), ["model_choice_unresolved"])
            self.assertEqual(self.codes("acct:a1/model:m-a"), [])                                   # the owner can still name a route explicitly
            self.assertEqual(self.codes("acct:b2"), [])
            with self.assertRaises(BridgeError):
                self.app.router.handle(normalize_anthropic({"model": "acct:a1", "max_tokens": 10, "messages": [{"role": "user", "content": "hi"}]}), lambda t: None, "", threading.Event(), scope="k")
            self.assertEqual(self.seen, [])                                                         # nothing was sent to a different model
            self.acc.discover_hook = lambda a, ui: ([self.var("m-a"), self.var("m-b"), self.var("m-c")], "site_network")      # the model returns
            self.acc.refresh_catalog("a1", "test", force=True)
            ch = self.acc.get("a1")["model_choice"]
            self.assertEqual((ch["status"], ch["variant"], ch["events"][-1]["type"]), ("ok", "m-b", "re_resolved"))      # back again, under the id the site uses now
            self.assertEqual(self.codes("acct:a1"), [])

        def test_a_mode_is_part_of_the_identity(self) -> None:
            vs = [self.var("m-a"), self.var("m-a", mode="thinking"), self.var("m-c")]
            self.catalog("a1", vs)
            self.assertEqual(vs[1].id, "m-a@thinking")
            self.acc.set_model_choice("a1", {"mode": "fixed", "variant": "m-a@thinking"})
            renamed = ModelVariant(id="think-renamed", display="Think", native_id="m-a", mode="thinking", capabilities=norm_caps({}), source="site_network", status="available", confidence="observed")
            self.acc.discover_hook = lambda a, ui: ([self.var("m-a"), renamed, self.var("m-c")], "site_network")
            self.acc.refresh_catalog("a1", "t", force=True)
            self.assertEqual(self.acc.get("a1")["model_choice"]["variant"], "think-renamed")        # the thinking mode, not the plain one that shares the native id

        # -- policy choice
        def test_policy_choice_prefers_requires_and_falls_back_to_measured_latency(self) -> None:
            vs = self.three()
            self.acc.set_model_choice("a1", {"mode": "policy", "prefer": ["m-c", "m-b"], "require": ["image_input"]})
            self.assertEqual(self.acc.o14_effective("a1")["variant"]["id"], "m-b")                  # m-c is preferred first but lacks image input
            self.acc.set_model_choice("a1", {"mode": "policy", "prefer": ["m-c"]})
            self.assertEqual(self.acc.o14_effective("a1")["variant"]["id"], "m-c")
            self.acc.set_model_choice("a1", {"mode": "policy", "require": ["image_input"], "fallback": "none"})
            e = self.acc.o14_effective("a1")
            self.assertEqual((e["status"], e["how"]), ("unresolved", "none"))                       # no prefer list and fallback none: nothing is guessed
            lat = [v.to_dict() for v in vs]
            lat[0]["latency"], lat[1]["latency"], lat[2]["latency"] = {"samples": 4, "ema_ms": 900}, {"samples": 4, "ema_ms": 300}, {"samples": 0, "ema_ms": 1}
            cat = self.acc.catalog("a1")
            cat["variants"] = lat
            self.acc.save_catalog("a1", cat)
            self.acc.set_model_choice("a1", {"mode": "policy", "prefer": ["m-a"], "require": ["image_input"], "fallback": "latency"})
            e = self.acc.o14_effective("a1")
            self.assertEqual((e["variant"]["id"], e["how"]), ("m-a", "policy:prefer"))              # the preferred m-a has UNKNOWN image support: allowed, but flagged, never "verified"
            self.assertEqual(e["flags"], ["image_input support unknown"])
            self.acc.set_model_choice("a1", {"mode": "policy", "prefer": ["m-c"], "require": ["image_input"], "fallback": "latency"})
            e = self.acc.o14_effective("a1")
            self.assertEqual(e["variant"]["id"], "m-b")                                             # the preferred one is unsupported -> measured fallback among the capable ones
            last = self.acc.get("a1")["model_choice"]["events"][-1]
            self.assertEqual((last["type"], last["to"]), ("policy_selected", "m-b"))                # the policy's pick changed -> one visible event

        def test_policy_with_nothing_left_is_unresolved_not_a_guess(self) -> None:
            self.three()
            self.acc.set_model_choice("a1", {"mode": "policy", "prefer": ["m-b"], "fallback": "none"})
            self.acc.discover_hook = lambda a, ui: ([self.var("m-a"), self.var("m-c")], "site_network")
            self.acc.refresh_catalog("a1", "t", force=True)
            self.assertEqual(self.acc.get("a1")["model_choice"]["status"], "unresolved")
            self.assertIn("model_choice_unresolved", self.codes("acct:a1"))

        # -- admin API and listings
        def test_http_api_and_listings_show_the_choice(self) -> None:
            self.three()
            srv = Server(self.app)
            try:
                A = {"x-admin-key": self.cfg["admin_key"]}
                self.assertEqual(call(srv.port, "GET", "/api/accounts/a1/model-choice")[0], 401)
                self.assertEqual(call(srv.port, "GET", "/api/accounts/zz/model-choice", headers=A)[0], 404)
                st, _h, b = call(srv.port, "GET", "/api/accounts/a1/model-choice", headers=A)
                self.assertEqual((st, json.loads(b)["selector"]["present"], json.loads(b)["choice"]), (200, True, {"mode": "default"}))
                self.assertEqual(call(srv.port, "POST", "/api/accounts/a1/model-choice", {"mode": "fixed", "variant": "ghost"}, A)[0], 400)
                self.assertEqual(call(srv.port, "POST", "/api/accounts/b2/model-choice", {"mode": "fixed", "variant": "x"}, A)[0], 409)
                st, _h, b = call(srv.port, "POST", "/api/accounts/a1/model-choice", {"mode": "fixed", "variant": "m-c"}, A)
                self.assertEqual((st, json.loads(b)["effective"]["variant"]), (200, "m-c"))
                st, _h, b = call(srv.port, "GET", "/api/state", headers=A)
                row = next(x for x in json.loads(b)["accounts"] if x["id"] == "a1")
                self.assertEqual((row["model_choice"]["choice"]["variant"], row["model_choice"]["selector"]["present"]), ("m-c", True))
                st, _h, b = call(srv.port, "GET", "/v1/models", headers={"x-api-key": self.cfg.data["keys"][0]["key"]})
                self.assertEqual(st, 200)
                route = next(x for x in json.loads(b)["data"] if x["id"] == "acct:a1")
                self.assertEqual(route["x_bridge"]["model_choice"], {"mode": "fixed", "status": "ok"})
                self.assertNotIn("native_ids", b.decode())
                st, _h, b = call(srv.port, "DELETE", "/api/accounts/a1/model-choice", headers=A)
                self.assertEqual((st, json.loads(b)["choice"]), (200, {"mode": "default"}))
            finally:
                srv.close()

        def test_the_decision_records_the_chosen_variant(self) -> None:
            self.three()
            self.acc.set_model_choice("a1", {"mode": "fixed", "variant": "m-b"})
            plan, dec = self.eng.plan(normalize_anthropic({"model": "acct:a1", "max_tokens": 10, "messages": [{"role": "user", "content": "hi"}]}), "", "", set(), "req_o14", "")
            self.assertEqual((dec.selected["account"], dec.selected["variant"]), ("a1", "m-b"))

