        def test_view_lists_browser_accounts_only_with_lifecycle_and_no_supervisor_yet(self) -> None:
            v = self.acc.o12_view()
            self.assertEqual([r["id"] for r in v["accounts"]], ["a1"])                       # the API account has no direct path to validate
            self.assertFalse(v["supervisor_running"])
            r = v["accounts"][0]
            self.assertEqual(r["lifecycle"]["state"], "validating")
            self.assertNotIn("validation", r)                                                  # nothing is invented when no battery ever ran
            self.assertNotIn("card_action", r)
