        def test_validation_record_is_summarised_and_bounded(self) -> None:
            rel = f"site_modules/{safe_host_dir(self.HOST)}/validation.json"
            self.store.write(rel, {"schema": O8_SCHEMA, "host": self.HOST, "fails": 2, "next_try_at": 123.0,
                                   "runs": [{"t": 1.0, "ok": True, "failed": [], "scenarios": {}}, {"t": 2.0, "ok": False, "failed": ["streaming"] * 9, "scenarios": {}}],
                                   "last_failure": {"t": 2.0, "failed": ["streaming"], "why": "x" * 900, "scenarios": {}},
                                   "promoted": {"validation_id": "o8-abc123", "validated_at": 5.0, "runs_counted": 2, "latency_ms_median": {"single_turn": 41.0}}}, private=True)
            v = self.row()["validation"]
            self.assertEqual((v["runs_total"], v["runs_ok"], v["fails"], v["next_try_at"]), (2, 1, 2, 123.0))
            self.assertEqual(len(v["last_run"]["failed"]), 5)                                  # bounded
            self.assertEqual(len(v["last_failure"]["why"]), 200)
            self.assertEqual(v["promoted"]["validation_id"], "o8-abc123")
            self.assertEqual((v["runs_needed"], v["gap_s"]), (O8_RUNS_NEEDED, O8_GAP_DEFAULT))
            self.assertNotIn("scenarios", json.dumps(v))                                       # the raw battery data stays on disk

        def test_repair_record_is_shown(self) -> None:
            self.store.write(f"site_modules/{safe_host_dir(self.HOST)}/validation.json", {"schema": O8_SCHEMA, "runs": []}, private=True)
            self.store.write(_o9_rel(self.HOST), {"schema": O9_SCHEMA, "host": self.HOST, "status": "pending", "attempts": 1, "next_try_at": 77.0, "log": []}, private=True)
            self.assertEqual(self.row()["repair"], {"status": "pending", "attempts": 1, "next_at": 77.0})

