        def test_http_route_is_admin_only_and_the_dashboard_carries_the_panel_without_model_requests(self) -> None:
            sent: List[int] = []
            self.app.router._run = lambda *a_, **k_: sent.append(1)                        # type: ignore[assignment]
            srv = Server(self.app)
