    class TestGroupO28(unittest.TestCase):
        """7.36 O28: the advisory review on the O27 result of the O17 mock site and a FAKE reviewer (no real model)."""

        def setUp(self) -> None:
            self.h27 = TestGroupO27("test_o27_a_correct_draft_passes_every_gate_and_the_generated_test_file_runs_for_real")
            self.h27.setUp()
            self.spec = self.h27.o26["specs"][0]
            self.subtle = self.h27.good().replace('message = ctx["header.x-ts"] + "." + ctx["body.$.prompt"]', 'message = ctx["header.x-ts"] + "." + ctx["body.$.prompt"].replace("\\n", " ")')
            br, _ = self.h27.brain({"o27_author": {"tokens_py": self.subtle}})
            self.r27 = self.h27.go(br)

        def tearDown(self) -> None:
            self.h27.tearDown()

        def review(self, answer: Any, o27: Optional[Dict[str, Any]] = None, budget: Optional[int] = None) -> Tuple[Dict[str, Any], "FakeBrain"]:
            self.h27.spent.clear()
            br, fake = self.h27.brain({"o28_review": answer}, budget=budget)
            return o28_review(br, self.r27 if o27 is None else o27, self.h27.scripts, [self.spec], self.h27.h.HOST), fake

        def test_o28_a_subtle_difference_that_passes_every_recorded_capture_is_flagged_and_confirmed_by_one_extra_run(self) -> None:
            self.assertEqual(self.r27["outcome"], "modules", self.r27)                                  # the gates really accepted this draft: the review is the second line
            probe = {"loc": "header.x-sig", "ctx": {"header.x-ts": "1900000001000", "body.$.prompt": "line1\nline2"}}
            ans = {"verdict": "one input class is handled differently from the script", "findings": [
                {"check": "matches_source", "severity": "defect", "text": "newlines in the prompt are replaced; the cited lines do not do that", "quote": '.replace("\\n", " ")', "probe": probe},
                {"check": "readability", "severity": "info", "text": "fine"}]}
            r, fake = self.review(ans)
            self.assertEqual((r["outcome"], r["requests"], r["promotes"], r["confirmed_defects"]), ("reviewed", 1, False, 1), r)
            self.assertEqual((r["findings"][0]["probe"], r["findings"][0]["quote_ok"]), ("confirmed", True))
            self.assertTrue(any("probe confirmed" in x for x in o28_report_lines(r)))
            self.assertIn("matches_source", fake.prompts[0])                                           # the fixed checklist was sent

        def test_o28_an_opinion_without_a_reproducing_probe_is_never_a_confirmed_defect_and_a_fabricated_quote_is_marked(self) -> None:
            same = {"loc": "header.x-sig", "ctx": {"header.x-ts": "1900000001000", "body.$.prompt": "plain text"}}
            ans = {"verdict": "v", "findings": [
                {"check": "edge_cases", "severity": "defect", "text": "might differ", "quote": "this text is not in the module at all", "probe": same},
                {"check": "nothing_guessed", "severity": "warn", "text": "opinion only"},
                {"check": "not_a_check", "severity": "defect", "text": "dropped"},
                {"check": "edge_cases", "severity": "defect", "text": "bad probe", "probe": {"loc": "header.x-sig", "ctx": {}}}]}
            r, _ = self.review(ans)
            self.assertEqual((r["confirmed_defects"], [f["probe"] for f in r["findings"]]), (0, ["not_reproduced", None, "invalid"]))
            self.assertIs(r["findings"][0]["quote_ok"], False)
            self.assertTrue(any("quote not found" in x for x in o28_report_lines(r)))

        def test_o28_only_a_gated_module_set_is_reviewed_and_a_failed_or_empty_budget_review_changes_nothing(self) -> None:
            r, fake = self.review({"verdict": "v", "findings": []}, o27={"outcome": "refused", "files": {}})
            self.assertEqual((r["outcome"], r["requests"], fake.prompts), ("skipped", 0, []))
            r, _ = self.review("not json at all")
            self.assertEqual((r["outcome"], r["findings"], r["promotes"]), ("failed", [], False))
            r, fake = self.review({"verdict": "v", "findings": []}, budget=0)
            self.assertEqual((r["outcome"], fake.prompts), ("failed", []))
            self.assertEqual(o28_report_lines(r)[0][:14], "review: failed")

        def test_o28_the_review_code_names_no_site_or_provider(self) -> None:
            src = Path(__file__).read_text(encoding="utf-8")
            body = src[src.index("O28_CHECKS ="):src.index("# --- end of the O28 review ---")].lower()
            for name in ("chatgpt", "openai", "gemini", "claude", "anthropic", "deepseek", "kimi", "qwen", "grok", "perplexity", "mistral", "copilot", "poe.com"):
                self.assertNotIn(name, body)

    class TestGroupO11(unittest.TestCase):
        """7.29 (O11) on mocks ONLY: the editable site directory (data file), honest status from the real accounts, custom entries, admin API, dashboard card."""

        def setUp(self) -> None:
            self.tmp, self.store, self.cfg, self.app = mk_env({"cache_seconds": 0})

        def tearDown(self) -> None:
            shutil.rmtree(self.tmp, ignore_errors=True)

        def view(self) -> Dict[str, Any]:
            return site_dir_view(self.store, self.app.acc.items)

        def test_starter_list_is_data_labelled_unverified_and_has_no_model_names(self) -> None:
            v = self.view()
            self.assertIn("verify before relying", v["label"])
            self.assertTrue(self.store.read("site_directory.json")["entries"])                  # written once into the data folder: the owner can edit it
            self.assertTrue(all(e["verified_at"] is None and e["status"] == "not added" and e["category"] in SITE_DIR_CATEGORIES for e in v["entries"]))
            self.assertTrue({"official_chat", "model_arena_compare", "aggregator", "api_compatible"} <= {e["category"] for e in v["entries"]})
            blob = json.dumps({k: (x if k != "entries" else [{kk: vv for kk, vv in e.items() if kk != "id"} for e in x]) for k, x in v.items()}).lower()   # the `id` is a slug of the host (gemini-google-com): a site name, not a model name
            for model_word in ("gpt-4", "sonnet", "opus", "gemini-", "llama-", "o1-"):
                self.assertNotIn(model_word, blob)

        def test_status_comes_from_real_accounts_including_needs_login(self) -> None:
            self.view()
            a = add_acct(self.app, "a1", "Claude", "claude.ai")
            lc_init(a, "ready", "t")
            st = {e["host"]: e["status"] for e in self.view()["entries"]}
            self.assertEqual(st["claude.ai"], "added")
            lc_init(a, "validating", "t")
            lc_transition(a, "needs_login", "again")
            self.assertEqual({e["host"]: e["status"] for e in self.view()["entries"]}["claude.ai"], "needs login")
            add_acct(self.app, "k1", "Api", "chatgpt.com", type="api")
            self.assertEqual({e["host"]: e["status"] for e in self.view()["entries"]}["chatgpt.com"], "not added")     # an API key is not a browser account

        def test_owner_edits_to_the_file_are_respected_and_bad_entries_are_ignored(self) -> None:
            d = site_dir_load(self.store)
            d["entries"].append({"id": "bad", "name": "x", "url": "https://x.test", "host": "x.test", "category": "bogus"})
            d["entries"] = [e for e in d["entries"] if e["id"] != "claude-ai"]
            self.store.write("site_directory.json", d)
            ids = [e["id"] for e in self.view()["entries"]]
            self.assertNotIn("bad", ids)
            self.assertNotIn("claude-ai", ids)

        def test_add_custom_site_validates_and_refuses_duplicates(self) -> None:
            self.assertEqual(site_dir_add(self.store, {"name": "My chat", "url": "chat.example.org", "category": "other", "notes": "n" * 500})["id"], "chat-example-org")
            e = next(x for x in self.view()["entries"] if x["id"] == "chat-example-org")
            self.assertEqual((e["custom"], e["url"], len(e["notes"])), (True, "https://chat.example.org/", 200)) if e["url"].endswith("/") else self.assertEqual((e["custom"], len(e["notes"])), (True, 200))
            for bad in ({}, {"name": "", "url": "a.test", "category": "other"}, {"name": "x", "url": "a.test", "category": "nope"}, {"name": "x", "url": "ftp://a.test", "category": "other"}, {"name": "x", "url": "has space", "category": "other"}):
                with self.assertRaises(BridgeError):
                    site_dir_add(self.store, bad)
            with self.assertRaises(BridgeError):
                site_dir_add(self.store, {"name": "again", "url": "https://chat.example.org", "category": "other"})
            self.assertTrue(site_dir_remove(self.store, "chat-example-org"))
            self.assertFalse(site_dir_remove(self.store, "chat-example-org"))

        def test_http_api_and_dashboard_card(self) -> None:
            srv = Server(self.app)
            try:
                H = {"x-admin-key": self.cfg["admin_key"]}
                self.assertEqual(call(srv.port, "GET", "/api/directory")[0], 401)
                st, _h, b = call(srv.port, "GET", "/api/directory", headers=H)
                self.assertEqual(st, 200)
                self.assertTrue(json.loads(b)["entries"])
                self.assertEqual(call(srv.port, "POST", "/api/directory", {"name": "N", "url": "n.example", "category": "other"}, H)[0], 200)
                self.assertEqual(call(srv.port, "POST", "/api/directory", {"name": "N", "url": "n.example", "category": "other"}, H)[0], 409)
                self.assertEqual(call(srv.port, "POST", "/api/directory", {"name": "N", "url": "javascript:alert(1)", "category": "other"}, H)[0], 400)
                self.assertEqual(call(srv.port, "DELETE", "/api/directory/n-example", headers=H)[0], 200)
                self.assertEqual(call(srv.port, "DELETE", "/api/directory/n-example", headers=H)[0], 404)
                html = call(srv.port, "GET", "/")[2].decode("utf-8")
                for needle in ('id="dircard"', 'id="dir_rows"', "api('directory')", "dirStart", "No sites match", "not verified"):
                    self.assertIn(needle, html, needle)
            finally:
                srv.close()

    class TestLogFile(unittest.TestCase):
        """7.28: the persistent log file (`logs/bridge.log`): lines with a full date, rotation, secrets masked, thread exceptions with traceback, lifecycle transitions."""

        def setUp(self) -> None:
            self.tmp = Path(tempfile.mkdtemp(prefix="bridge-log-"))
            self.old = dict(_LOGFILE)

        def tearDown(self) -> None:
            _LOGFILE.clear()
            _LOGFILE.update(self.old)
            sys.excepthook, threading.excepthook = sys.__excepthook__, threading.__excepthook__
            shutil.rmtree(self.tmp, ignore_errors=True)

        def test_lines_reach_the_file_with_date_and_secrets_masked(self) -> None:
            p = log_file_open(self.tmp / "logs")
            log("hello world", "warn")
            log("token Bearer abcdefghijklmnop1234567890 leaked", "error")
            txt = p.read_text("utf-8")
            self.assertRegex(txt, r"\d{4}-\d\d-\d\d \d\d:\d\d:\d\d WARN  hello world")
            self.assertIn("ERROR", txt)
            self.assertNotIn("abcdefghijklmnop1234567890", txt)

        def test_rotation_keeps_a_bounded_number_of_files(self) -> None:
            p = log_file_open(self.tmp / "logs", max_bytes=300, keep=2)
            for i in range(60):
                log(f"line {i} " + "x" * 40)
            names = sorted(x.name for x in p.parent.iterdir())
            self.assertEqual(names, ["bridge.log", "bridge.log.1", "bridge.log.2"])

        def test_an_unwritable_folder_never_raises(self) -> None:
            blocker = self.tmp / "file"
            blocker.write_text("x")
            self.assertIsNone(log_file_open(blocker / "sub"))
            log("still fine")                                                                # no exception, console and memory buffer still work

        def test_uncaught_thread_exception_and_lifecycle_transition_are_logged(self) -> None:
            p = log_file_open(self.tmp / "logs")
            log_install_hooks()

            def boom() -> None:
                raise ValueError("kaboom-7-28")
            th = threading.Thread(target=boom, name="t-boom")
            th.start()
            th.join()
            a = {"id": "z1", "host": "z.test"}
            lc_init(a, "validating", "x")
            lc_transition(a, "degraded_fallback", "battery failed: streaming")
            txt = p.read_text("utf-8")
            self.assertIn("UNCAUGHT in thread t-boom", txt)
            self.assertIn("kaboom-7-28", txt)
            self.assertIn("lifecycle z1 (z.test): validating -> degraded_fallback: battery failed: streaming", txt)

        def test_tail_filters_by_level_and_keeps_tracebacks_together(self) -> None:
            p = log_file_open(self.tmp / "logs")
            log("quiet info line")
            log("a warning line", "warn")
            log("multi\nline\nerror record", "error")
            self.assertEqual(len(log_tail(50, "all")), 3)
            w = log_tail(50, "warn")
            self.assertEqual(len(w), 2)
            self.assertIn("multi\nline\nerror record", w[-1])
            self.assertEqual(len(log_tail(50, "error")), 1)

        def test_log_every_holds_back_identical_lines_and_reports_the_count(self) -> None:
            p = log_file_open(self.tmp / "logs")
            _LOGSTAT["every"].clear()
            self.assertTrue(log_every("k1", 60, "same problem", "warn"))
            for _ in range(3):
                self.assertFalse(log_every("k1", 60, "same problem", "warn"))
            _LOGSTAT["every"]["k1"] = (time.time() - 61, 3)
            self.assertTrue(log_every("k1", 60, "same problem", "warn"))
            txt = p.read_text("utf-8")
            self.assertEqual(txt.count("same problem"), 2)
            self.assertIn("+3 identical line(s) held back", txt)

        def test_error_burst_is_reported_once(self) -> None:
            p = log_file_open(self.tmp / "logs")
            _LOGSTAT["errors_recent"].clear()
            _LOGSTAT["burst_at"] = 0.0
            for i in range(25):
                log(f"boom {i}", "error")
            self.assertEqual(p.read_text("utf-8").count("ERROR BURST"), 1)

        def test_log_kv_leaves_empty_values_out(self) -> None:
            p = log_file_open(self.tmp / "logs")
            log_kv("hello", "info", a=1, b="", c=None, d="x")
            self.assertIn("hello | a=1 d=x", p.read_text("utf-8"))

        def test_session_header_names_version_and_folder(self) -> None:
            p = log_file_open(self.tmp / "logs")
            log_session_header("data folder: /x")
            txt = p.read_text("utf-8")
            self.assertIn("SESSION START  v" + VERSION, txt)
            self.assertIn("data folder: /x", txt)

    class TestPersonalChrome(unittest.TestCase):
        """7.24: the personal-Chrome layer. A FAKE extension (Python) speaks the real wire protocol to a real hub, and the real background.js runs under node with a stubbed
        `chrome` API against the same hub. NOT covered here (needs a real Chrome): the DOM finder script, real debugger events, real tab behaviour."""
        ORIGIN = "chrome-extension://abcdefghijklmnopabcdefghijklmnop"

        def setUp(self) -> None:
            self.tmp = Path(tempfile.mkdtemp(prefix="bridge_pc_"))
            s = socket.socket()
            s.bind(("127.0.0.1", 0))
            self.port = s.getsockname()[1]
            s.close()
            self.hub = PCHub(self.tmp / "personal_chrome", self.port)
            self.hub.grace = 1.5
            self.assertTrue(self.hub.start())
            self.exts: List[Any] = []

        def tearDown(self) -> None:
            for e in self.exts:
                e.stop()
            self.hub.stop()
            shutil.rmtree(self.tmp, ignore_errors=True)

        # -- helpers -----------------------------------------------------------------------------------------------------------------------------
        def post(self, path: str, body: Any = None, origin: Optional[str] = None, token: str = "", host: Optional[str] = None, raw: Optional[bytes] = None) -> Tuple[int, Any]:
            c = hc.HTTPConnection("127.0.0.1", self.port, timeout=15)
            h = {"Content-Type": "application/json", "Host": host or f"127.0.0.1:{self.port}"}
            if origin:
                h["Origin"] = origin
            if token:
                h["X-Bridge-PC-Token"] = token
            c.request("POST", path, body=raw if raw is not None else json.dumps(body or {}).encode(), headers=h)
            r = c.getresponse()
            data = r.read()
            c.close()
            try:
                return r.status, json.loads(data)
            except Exception:
                return r.status, data

        def pair(self) -> str:
            code = self.hub.new_pairing()
            st, j = self.post("/pc/pair", {"code": code}, origin=self.ORIGIN)
            self.assertEqual(st, 200)
            return j["token"]

        def fake(self, tabs: Optional[Dict[int, Dict[str, Any]]] = None, **kw: Any) -> Any:
            tok = self.pair() if not self.hub.paired() else self.tok
            self.tok = tok
            e = FakeExt(self, tok, **kw)
            if tabs is not None:
                e.tabs = tabs
            self.exts.append(e)
            e.start()
            end = time.time() + 5
            while time.time() < end and not self.hub.connected():                                                        # like the real worker: its first poll marks it connected
                time.sleep(0.02)
            return e

        class _Ext:
            pass

        # -- packaging / permissions -------------------------------------------------------------------------------------------------------------
        def test_embedded_assets_are_a_valid_minimal_mv3_extension(self) -> None:
            m = pc_manifest()
            self.assertEqual(m["manifest_version"], 3)
            self.assertEqual(set(m["permissions"]), {"debugger", "tabs", "storage", "alarms"})
            self.assertEqual(m["host_permissions"], ["http://127.0.0.1/*"])
            self.assertNotIn("<all_urls>", json.dumps(m))
            assets = pc_assets()
            for rel in (m["background"]["service_worker"], m["action"]["default_popup"], m["options_ui"]["page"]):
                self.assertIn(rel, assets)
            for rel in ("popup.html", "options.html"):
                for ref in re.findall(r'(?:src|href)="([^"]+)"', assets[rel]):
                    self.assertIn(ref, assets)
            for name, text in assets.items():                                                                             # no embedded secret: no long random-looking literal anywhere
                self.assertEqual(re.findall(r"['\"][A-Za-z0-9_\-]{32,}['\"]", text), [], name)

        def test_extraction_is_repeatable_verified_and_confined(self) -> None:
            root = self.tmp / "pcx"
            (root / "extension").mkdir(parents=True)
            (root / "extension" / "unrelated.txt").write_text("keep me")
            r1 = pc_extract(root)
            self.assertEqual(sorted(r1["changed"]), sorted(pc_assets()))
            self.assertEqual(pc_extract(root)["changed"], [])
            (root / "extension" / "background.js").write_text("tampered")
            self.assertEqual(pc_extract(root)["changed"], ["background.js"])
            self.assertEqual((root / "extension" / "unrelated.txt").read_text(), "keep me")
            on_disk = json.loads((root / "extension.sha256.json").read_text())["files"]
            for rel, h in on_disk.items():
                self.assertEqual(hashlib.sha256((root / "extension" / rel).read_bytes()).hexdigest(), h)

        def test_extension_scripts_parse(self) -> None:
            import shutil as sh
            node = sh.which("node")
            if not node:
                raise unittest.SkipTest("node is not installed; extension syntax not checked")
            for rel in ("background.js", "popup.js", "options.js"):
                p = self.tmp / rel
                p.write_text(pc_assets()[rel], "utf-8")
                r = subprocess.run([node, "--check", str(p)], capture_output=True, text=True, timeout=30)
                self.assertEqual(r.returncode, 0, f"{rel}: {r.stderr}")
            p = self.tmp / "find.js"
            p.write_text("const f = " + PC_FIND_JS + ";", "utf-8")
            r = subprocess.run([node, "--check", str(p)], capture_output=True, text=True, timeout=30)
            self.assertEqual(r.returncode, 0, r.stderr)

        # -- channel security --------------------------------------------------------------------------------------------------------------------
        def test_channel_rejects_everything_that_is_not_the_paired_extension(self) -> None:
            tok = self.pair()
            self.assertEqual(self.post("/pc/poll", {"wait_ms": 10})[0], 401)                                              # no origin, no token
            self.assertEqual(self.post("/pc/poll", {"wait_ms": 10}, origin="https://evil.example", token=tok)[0], 401)  # a web page cannot use a stolen token
            self.assertEqual(self.post("/pc/poll", {"wait_ms": 10}, origin=self.ORIGIN, token="wrong")[0], 401)
            self.assertEqual(self.post("/pc/poll", {"wait_ms": 10}, origin="chrome-extension://otherotherotherotherotherotherot", token=tok)[0], 401)   # another extension
            self.assertEqual(self.post("/pc/poll", {"wait_ms": 10}, origin=self.ORIGIN, token=tok, host="evil.example")[0], 403)                      # DNS rebinding
            self.assertEqual(self.post("/pc/poll", {"wait_ms": 10}, origin=self.ORIGIN, token=tok)[0], 200)
            self.assertEqual(self.post("/pc/poll", origin=self.ORIGIN, token=tok, raw=b"{not json")[0], 400)
            old_max = globals()["PC_MAX_BODY"]
            globals()["PC_MAX_BODY"] = 2000
            try:
                self.assertEqual(self.post("/pc/poll", origin=self.ORIGIN, token=tok, raw=b"x" * 5000)[0], 413)
            finally:
                globals()["PC_MAX_BODY"] = old_max
            c = hc.HTTPConnection("127.0.0.1", self.port, timeout=5)
            c.request("GET", "/pc/poll")
            self.assertEqual(c.getresponse().status, 405)
            c.close()
            self.assertGreaterEqual(self.hub.stats["rejected"], 3)

        def test_pairing_rules(self) -> None:
            code = self.hub.new_pairing()
            self.assertEqual(self.post("/pc/pair", {"code": code}, origin="https://evil.example")[0], 403)                # only an extension origin may pair
            self.assertEqual(self.post("/pc/pair", {"code": code})[0], 403)
            for _ in range(5):
                self.assertEqual(self.post("/pc/pair", {"code": "WRONGCODE"}, origin=self.ORIGIN)[0], 403)
            self.assertEqual(self.post("/pc/pair", {"code": code}, origin=self.ORIGIN)[0], 403)                           # five failures burn the code
            code = self.hub.new_pairing()
            st, j = self.post("/pc/pair", {"code": code}, origin=self.ORIGIN)
            self.assertEqual(st, 200)
            self.assertEqual(self.post("/pc/pair", {"code": code}, origin=self.ORIGIN)[0], 403)                           # one use only
            saved = (self.hub.root / "pairing.json").read_text()
            self.assertNotIn(j["token"], saved)                                                                          # only the hash is stored
            self.assertNotIn(j["token"], json.dumps(self.hub.status()))
            self.assertNotIn(j["token"], pc_instructions(self.hub))

        def test_commands_are_validated_before_they_are_queued(self) -> None:
            self.fake()
            for op, a in (("evil.op", {}), ("cdp.send", {"tab": 1, "method": "Storage.getCookies"}), ("cdp.send", {"tab": 1, "method": "Network.getAllCookies"}),
                          ("cdp.send", {"tab": 1, "method": "Fetch.enable"}), ("cdp.send", {"tab": "1", "method": "Page.enable"}), ("tab.close", {})):
                with self.assertRaises(PCError, msg=f"{op} {a}"):
                    self.hub.call(op, a, timeout=3)

        # -- command lifecycle -------------------------------------------------------------------------------------------------------------------
        def test_round_trip_ack_and_structured_errors(self) -> None:
            e = self.fake()
            self.assertTrue(self.hub.call("ping", {})["pong"])
            t = self.hub.call("tab.create", {"url": "about:blank"})
            self.assertIn(t["id"], e.tabs)
            with self.assertRaises(PCError) as cm:
                self.hub.call("tab.close", {"tab": 999})
            self.assertIn("did not open", str(cm.exception))
            with self.assertRaises(PCError) as cm:
                self.hub.call("cdp.send", {"tab": 12345, "method": "Page.enable"})
            self.assertTrue(is_window_closed_error(cm.exception))                                                        # existing 'window closed' handling still recognises it

        def test_a_redelivered_command_is_not_executed_twice(self) -> None:
            e = self.fake()
            cmd = {"id": "dup1", "op": "tab.create", "args": {"url": "about:blank"}}
            r1, r2 = e.execute_cached(cmd), e.execute_cached(cmd)
            self.assertEqual(r1, r2)
            self.assertEqual(sum(1 for x in e.executed if x[0] == "tab.create"), 1)

        def test_cancellation_before_and_during_execution(self) -> None:
            e = self.fake(hold={"tab.create"})
            ev = threading.Event()
            threading.Timer(0.6, ev.set).start()
            with self.assertRaises(PCError) as cm:
                self.hub.call("tab.create", {"url": "about:blank"}, timeout=10, cancel=ev)
            self.assertTrue(cm.exception.unknown_outcome)                                                                # it was already sent: the bridge cannot know
            self.assertEqual(self.hub.call("ping", {})["pong"], True)                                                    # the channel is still healthy

        def test_timeout_is_reported_with_unknown_outcome_for_unsafe_commands(self) -> None:
            self.fake(hold={"tab.create"})
            with self.assertRaises(PCError) as cm:
                self.hub.call("tab.create", {"url": "about:blank"}, timeout=1.0)
            self.assertTrue(cm.exception.unknown_outcome)
            self.assertIn("may or may not", str(cm.exception))

        def test_disconnect_midflight_unsafe_is_never_repeated_safe_is_resumed(self) -> None:
            e = self.fake(hold={"tab.create", "tabs.list"})
            out: Dict[str, Any] = {}

            def unsafe() -> None:
                try:
                    self.hub.call("tab.create", {"url": "about:blank"}, timeout=15)
                except PCError as x:
                    out["unsafe"] = x

            def safe() -> None:
                try:
                    out["safe"] = self.hub.call("tabs.list", {}, timeout=15)
                except PCError as x:
                    out["safe_err"] = x
            ts = [threading.Thread(target=unsafe), threading.Thread(target=safe)]
            for t in ts:
                t.start()
            time.sleep(0.8)
            e.stop()                                                                                                     # the extension goes away holding both commands
            ts[0].join(8)
            self.assertTrue(out["unsafe"].unknown_outcome)
            e2 = self.fake()                                                                                             # and comes back
            ts[1].join(10)
            self.assertIn("safe", out, out)
            self.assertEqual(sum(1 for x in e2.executed if x[0] == "tab.create"), 0)                                     # the unsafe one was NOT sent again
            self.assertGreaterEqual(self.hub.epoch, 2)

        def test_not_connected_gives_the_human_step(self) -> None:
            with self.assertRaises(PCError) as cm:
                self.hub.call("ping", {})
            self.assertIn("pair", str(cm.exception).lower())
            self.assertIn("chrome://extensions", str(cm.exception))

        # -- compatibility layer against the fake extension ---------------------------------------------------------------------------------------
        def ctx(self, e: Any, **kw: Any) -> "PCContext":
            return PCContext(self.hub, kw.pop("acct", "a1"), **kw)

        def test_context_pages_goto_evaluate_and_close_only_own_tabs(self) -> None:
            e = self.fake()
            e.tabs[5] = {"id": 5, "url": "https://personal.example/", "title": "mine", "owned": False}                   # the user's own tab
            ctx = self.ctx(e)
            self.assertEqual(ctx.pages, [])
            pg = ctx.new_page()
            self.assertEqual(len(ctx.pages), 1)
            e.evals["document.title"] = "Hello"
            pg.goto("https://site.test/", wait_until="domcontentloaded", timeout=5000)
            self.assertEqual(pg.url, "https://site.test/")
            self.assertEqual(pg.title(), "Hello")
            e.eval_fn = lambda code: {"echo": code}
            r = pg.evaluate("(x) => x.a + 1", {"a": 1})
            self.assertEqual(r["echo"], '((x) => x.a + 1)({"a": 1})')                                                    # function strings are called with the argument
            self.assertEqual(pg.evaluate("navigator.userAgent")["echo"], "navigator.userAgent")                          # plain expressions are evaluated as they are
            with self.assertRaises(PCError):
                pg.goto("file:///etc/passwd")
            with self.assertRaises(PCError):
                pg.goto("javascript:alert(1)")
            ctx.close()
            self.assertIn(5, e.tabs)                                                                                     # the user's tab was never closed
            self.assertEqual([t for t in e.tabs if e.tabs[t].get("owned")], [])

        def test_locator_click_fill_keys_use_trusted_input_events(self) -> None:
            e = self.fake()
            ctx = self.ctx(e)
            pg = ctx.new_page()
            seen: List[Any] = []

            def ev(code: str) -> Any:
                m = re.search(r"\[(\{.*\}), \"(\w+)\", (.*)\]\)$", code, re.S)
                op = m.group(2) if m else ""
                seen.append(op)
                if op == "rect":
                    return {"found": True, "x": 50.0, "y": 60.0, "vis": True, "enabled": True, "hit": True}
                if op == "focus":
                    return {"found": True, "kind": "field", "editable": True}
                if op == "value":
                    return {"found": True, "v": "hello"}
                if op == "count":
                    return {"found": True, "v": 2}
                return {"found": False}
            e.eval_fn = ev
            self.assertEqual(pg.locator("textarea:visible").count(), 2)
            pg.locator("button").first.click(timeout=2000)
            kinds = [x[1].get("type") for x in e.input_log if x[0] == "Input.dispatchMouseEvent"]
            self.assertEqual(kinds, ["mouseMoved", "mousePressed", "mouseReleased"])
            pg.locator("textarea").last.fill("hello", timeout=2000)
            self.assertIn(("Input.insertText", {"text": "hello"}), e.input_log)
            pg.keyboard.press("Enter")
            self.assertTrue(any(x[0] == "Input.dispatchKeyEvent" and x[1].get("key") == "Enter" for x in e.input_log))
            with self.assertRaises(PCError) as cm:                                                                       # honest timeout instead of a fake success
                e.eval_fn = lambda code: {"found": False}
                pg.locator("#nope").click(timeout=300)
            self.assertIn("Timeout", str(cm.exception))
            ctx.close()

        def test_network_events_reach_capture_and_cdp_recorder(self) -> None:
            e = self.fake()
            ctx = self.ctx(e)
            cap = Capture(ctx)
            rec = CdpRecorder(ctx)
            pg = ctx.new_page()
            rec.start()
            self.assertEqual(rec.errors, [])
            m0 = cap.mark()
            e.bodies["R1"] = ('{"ok":true}', False)
            e.emit(pg.tab_id, "Network.requestWillBeSent", {"requestId": "R1", "type": "Fetch", "frameId": "F", "timestamp": 1.0, "wallTime": time.time(),
                                                           "request": {"url": "https://site.test/api/chat", "method": "POST", "headers": {"Content-Type": "application/json"}, "postData": '{"q":1}', "hasPostData": True},
                                                           "initiator": {"type": "script"}})
            e.emit(pg.tab_id, "Network.requestWillBeSentExtraInfo", {"requestId": "R1", "headers": {"Content-Type": "application/json", "Cookie": "s=1"}})
            e.emit(pg.tab_id, "Network.responseReceived", {"requestId": "R1", "timestamp": 1.1, "response": {"url": "https://site.test/api/chat", "status": 200, "headers": {"Content-Type": "application/json"}, "mimeType": "application/json"}})
            e.emit(pg.tab_id, "Network.loadingFinished", {"requestId": "R1", "timestamp": 1.2})
            e.emit(pg.tab_id, "Network.requestWillBeSent", {"requestId": "R2", "type": "Script", "request": {"url": "https://site.test/app.js", "method": "GET", "headers": {}}, "timestamp": 1.3})
            e.emit(pg.tab_id, "Network.responseReceived", {"requestId": "R2", "response": {"url": "https://site.test/app.js", "status": 200, "headers": {}}})
            e.bodies["R2"] = ("console.log(1)", False)
            e.emit(pg.tab_id, "Network.loadingFinished", {"requestId": "R2", "timestamp": 1.4})
            e.emit(pg.tab_id, "Network.requestWillBeSent", {"requestId": "R3", "type": "XHR", "request": {"url": "https://site.test/never", "method": "GET", "headers": {}}, "timestamp": 1.5})
            e.emit(pg.tab_id, "Network.loadingFailed", {"requestId": "R3", "errorText": "net::ERR_CONNECTION_RESET"})
            e.flush()
            self.assertTrue(ctx.drain(5))
            snap = cap.snapshot(m0, settle=2.0)
            self.assertEqual([s["url"] for s in snap], ["https://site.test/api/chat", "https://site.test/never"])
            self.assertEqual((snap[0]["status"], snap[0]["body"], snap[0]["resp_body"]), (200, '{"q":1}', '{"ok":true}'))
            self.assertEqual(snap[0]["headers"].get("cookie"), "s=1")                                                    # the raw (extra-info) headers win, as with Playwright's all_headers()
            self.assertEqual(snap[1]["status"], 0)                                                                       # a failed request is reported as failed, not as success
            self.assertEqual([u for u, _b in cap.script_bodies()], ["https://site.test/app.js"])
            raws = rec.raw_exchanges()
            self.assertTrue(any(x.get("url") == "https://site.test/api/chat" for x in raws))
            ctx.close()

        def test_cookies_are_limited_to_the_accounts_own_site(self) -> None:
            e = self.fake()
            ctx = self.ctx(e)
            pg = ctx.new_page()
            pg._url = "https://chat.site.test/c/1"
            e.cookies = [{"name": "sid", "value": "v", "domain": ".site.test", "path": "/", "httpOnly": True, "secure": True}]
            got = ctx.cookies()
            self.assertEqual([c["name"] for c in got], ["sid"])
            asked = [x[1] for x in e.cdp_log if x[0] == "Network.getCookies"][0]["urls"]
            self.assertIn("https://chat.site.test/", asked)
            self.assertTrue(all(u.startswith("https://") and "site.test" in u for u in asked))
            with self.assertRaises(PCError):
                self.hub.call("cdp.send", {"tab": pg.tab_id, "method": "Network.getAllCookies"})
            ctx.close()

        def test_reconnection_revalidates_tabs_and_keeps_closed_tabs_closed(self) -> None:
            e = self.fake()
